/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080604-16","meetingId":"h20-cm06","date":"2008年6月4日","dateIso":"2008-06-04","committee":"街づくり特別委員会","time":"午後１時０２分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"八潮の部分なんですけれども、改めて今年の４月に八潮まちづくり検討委員会、自治会連合会長のところから区に提言書が出されたということで、先ほども説明、紹介がありましたけれども、この扱いについて改めてちょっと伺いたいと思いますし、それぞれさっきの説明では、いろいろな分野、角度にわたって提言がされているので。","respondent":"日下部企画財政課長、青木都市開発課長","answer":"最初に最後の３点目からご答弁を申し上げたいというふうに思いますけれども、八潮まちづくり検討委員会の提言、地域の皆様方が一生懸命になって検討された、そういう成果でもありますので。現在、資料の９ページのところで検討されています地区計画の内容で、八潮北小学校跡地の部分、現在、明晴学園という私立学校が入居しているところについて、生活関連地区というくくりにしていることの説明ですけれども、現在。","voiceIndex":47,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"１つは区道のマンホールの件と、もう１つは、団地の南側のほうに非常に区道のほうに法面からお水がずっと湧き出ていて、しみ出ていて、ずっと流れ込んでいるという状況がもう１年以上にわたってありますので、そういう状況もこの際やっぱりきちんと点検して、改修する、具体的に生活の続いているところですから、衛生面だとか。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"その次の地区計画という点で、道路、公共施設の地盤沈下等の件、ご指摘ありがとうあります。地区計画というのは都市計画制度ですので、具体的な施設の維持補修ということの観点では検討から外れております。改めて申し上げたいと思うんですが、区側としましても、地域からいただいた提言、これを最大限尊重する、これは当然のことでありますが、先ほど申し上げました全体的な視点というのは、繰り返しになりますけれども。","voiceIndex":52,"id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"八潮地区のまちづくりについて、先ほどの最後に企画財政課長から地域の声は最大限というお話がありましたけれども、説明の中で、これで行くと１０ページの今後の流れの中で、東京都との調整みたいな話が出たので、東京都は何を考えているのかなというのが聞いていてよくわからなかったんですけれども、何か区と違うのか、同じなのか、それともまだオブラートなものなのか、ちょっと都が何を考えているのか。","respondent":"青木都市開発課長","answer":"私どもとしては、いろいろな区民の皆様の声、地元の声、区議会のご意見をちょうだいしながら施設の用途を定めていかなければならないので、現段階ではあまり具体的に何をします、何をつくりますということは申し上げられないんだけれども、東京都としては。","voiceIndex":55,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明で居住環境を守ります、その機能を維持しますというお話だと思うんですけれども、今日の資料の世論調査を見ても、八潮の住んでいる方の８割を超える人が、住み続けたいとか、愛着を感じていると読み取れるんですよね。高齢者にとっては生活的にも、近隣のコミュニティーにとってもすごい負担なんですよね。そういうところをどんなふうに思っているのか、基本的な姿勢を改めて伺いたいなと思います。","respondent":"青木都市開発課長","answer":"今、委員のほうからご質問ありました住宅事業者としての、都営住宅を管理する立場としての東京都の考え方ですけれども、昭和５０年代に建設された都営住宅については、現在のところ、全く建て替え等は想定していないというふうに今回のおつき合いの中で確認しております。","voiceIndex":57,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一方の、安全・安心まちづくりのところですけれども、先ほど南委員からもありましたけれども、区の基本的な考えを伺えたらと思うんですけれども、住宅建築物の耐震化支援について促進計画をつくって掲げていますけれども、私自身は、品川区をはじめ都も含めて行政というのは、災害から住民の命を守る責任が課せられていると思っているんですけれども。","respondent":"片田建築課長","answer":"ただ、耐震化を進めるに当たっては、基本的には自分の命、あるいは自分の財産というものは自分の力で守るというところが基本となってございまして、それができない部分について、共助あるいは公助といったような考え方で進めるものと考えていますので、区としては。","voiceIndex":59,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"それなので、先ほど行政の責任とは何なのかと、私は住民の命と暮らしを守る責任が行政にあると思うんです。行政はどう考えているのか、どうも後退しているなというふうにも、今の説明だけだと感じるので、そこをもうちょっと教えていただきたいのと、あと、逆に、自助というならば、区有施設の耐震化というのは、それこそ区の責任ですよね。そこはどう思っているんですか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"今回は計画の前段の概要の事務事業概要に沿って、今、こういうところになっていますというスタンスで説明させていただいてありますので、改めて概要版をお示ししながら、区の考え方についてご説明させていただきたいと考えています。費用も助成をする。ですから、老朽化した木造住宅については、今回、先ほどちょっと説明がありましたけれども、あるエリア、木造密集エリアについては、建て替えをお願いしている。","voiceIndex":61,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"国や都も含めてありますけれども、自分たちで目標を定めたわけじゃないですか。それに対して達成する責任、それをどう考えているか、そこを聞いたので、後半ちょっと違ったので、そこの考えを教えてください。１つだけ、個別訪問のことをちょっと説明ありましたけれども、２月ぐらいに終わるという話だったのでしょうか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"個別訪問の件ですけれども、基本的には先ほど申し上げましたように、８町丁目行ったところがありますので、その状況等については、次回以降の当委員会のほうにご報告をさせていただきたいと思います。ホームページでもやりました。でも、まだほとんどの方に行き渡っているとは限りません。ですから、１軒１軒今、まず木造密集地域の一番危険なところからまず１軒１軒お訪ねして説明をし、協力をお願いしている、こういうことです。","voiceIndex":64,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ確認させてください。この文言が入っていると、おそらく若者たちがいたら、私たちは、と意見が出そうな感じがしたんですけれども、この８回にわたっての会合の中でそういう意見はなかったのか、メンバーがどういう構成になっていたのかというところがちょっと気になるんです。確認をさせていただきたいと思います。","respondent":"日下部企画財政課長","answer":"今のご質問ですけれども、確かに高齢者が安心して元気に暮らし続けることができるということで、検討委員会の構成を見ますと、確かに比較的高齢の方が多かったことは事実です。","voiceIndex":67,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな議論があったのだろうというふうに予想はしているんですが、まとめの段階でこういう形になったというところがかなり今回クローズアップされてしまうということもあるので、これは１つの参考資料という形になるのでしょうけれども、全体的に見て、要は若者たちにも八潮地区の魅力を感じてもらえるような形にしていきたいなという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"１つは、八潮地区のまちづくりについてという、いただいた資料の２枚目のところで、商業施設の空洞化ということで、区のほうはそういう認識をされていて、基本的な考え方の中で商業施設の再構築について検討を進めてまいりたいということで、こういう文言が入っておりますけれども、この商業施設、このまちづくりについて区はどのような位置づけを考えていらっしゃるのか、それとまた。","respondent":"日下部企画財政課長","answer":"最後のご質問のほうからお答え申し上げますと、この資料全体、つまり、今回４月にご提言をいただく、それに至る一連の過程、今の八潮の現状がどうなっているのか、それに対して区がどういうふうにこれを受けとめて。","voiceIndex":70,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"今、パトリアを私企業が経営している、私企業ですから、行政が入り込むというのは、これは非常に難しいこと。誘致を提言するという、区のスタンスで、パトリア経営をしている会社に対して、例えば何かの施設の誘致を提言するというようなスタンスはとれるものなのでしょうか。","respondent":"日下部企画財政課長","answer":"誘致について、行政側としてというのはなかなか難しい面がありますが、ただ、やはり地元の声としてそういうものを受けとめて、誘致という形で直接できるかどうかはわかりませんが、いろいろその辺また工夫の余地もあるのかなと、そのようには考えております。","voiceIndex":72,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"そういう中でやっぱり活性化、魅力ある商店街づくりという点で品川区が援助をしていきたいというのは、今のご答弁等々のところで承知しているんですけれども、なかなかちょっと難しい問題が出てきたなというのは１つあるんですけれども、それは、何日か前の総務委員会で勝島のところに大型の商業施設ができるという、こういう計画があって、総務委員会で報告されていますので。","respondent":"岩田まちづくり事業部長","answer":"ただ、いろいろな条件があって、大手ではなくて個別の店舗に対して空いたところをいろいろ声をかけているんですけれども埋まらない。こういう状況ですから、商業のプロがやってもなかなかうまくいかないのが現状ですから、行政が物を申すにしても、なかなか難しいだろうと。","voiceIndex":74,"id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"冒頭に委員長の説明から安全・安心のまちづくりに関することで説明がありましたけれども、地域危険度測定調査とか、ハード面とか、耐震化計画という話がありましたけれども、実際に地震が起きる前の対策と、今日は避難道路のこともちょっと報告があったり、防災課長から資料はなかったけれども報告があったり、地震は起きてからの対応も、起きてからを想定して今のうちから準備するものも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"わかりました。いわゆる世界で初めて成熟した大都市部で起きた地震から学ぶべきものというのはあるし、風化させてはいけないわけですから、そこも一定報告を受けながら委員同士の議論ができると、所管から説明がある促進計画も進むのかなというように感じるんです。阪神・淡路大震災、まずそこへ立ち戻って進められたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"街づくり特別委員会ですから、１つの視点だけではなくて、大所高所に立っていろいろな角度から検討していく質疑や意見交換が大事だというように思うんです。したがって、委員会運営でぜひ委員長にはお願いしたいと思うんですけれども、制限をすることなくいろいろな角度から質問できる機会を確保して提供していただきたいというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"特別委員会ですので、八潮の問題は、私は２０年議員をやっていますけれども、ほとんど荏原なものですから、詳しいことは本当によくわからないんです。そんなもので、やはり現地を見ると同時に、聞くだけではなくて、この中でいろいろ議論したい、こうあるべきではないのと、そういう席なら、南委員もいろいろ発言して、違うよと言えるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"ですから、ここはちょっとほかの、これは別の所管委員会ですよとか、きちっと仕切りをしていただいたほうが、やっぱりいろいろなところに横道にずれていってしまうので、そうなると、目的に合った議論はたくさんしていきましょうということは必要かと思うんですが、やっぱりずれないような形の仕切りをぜひお願いしたいと思いますし、事前に他の所管との調整をお願いして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"西本委員のご意見に反論するつもりはないんですけれども、松澤委員がおっしゃったように、１つのテーマでディスカッションをして議論を深める際には、それはいろいろなそれぞれの委員の得意分野、不得意分野も含めて、視点があっていいと思うんですよ。報告事項に対する質問ではなくて、せっかく特別委員会を開いた意味を生かしていけたらなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"それはわかりますが、いろいろな委員会があるわけですよ。その委員会の中で役割分担がされていて、そこの中でいろいろな議論をしていくわけです。ここの部分はこういう理由でほかの所管と重なるけれども、こういう議論をしていきましょうということの前提でやっていきましょうというだけですので、いろいろな方向に行くときは調整してくださいというだけですから、よろしく仕切りをお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"いろいろな方向に行かないように自分はきちんとやりましょうと、そういうことでいいと思うんです。それは西本委員がそういうふうに思ってこの委員会に臨んで質問すればいいことだと思うんです。そこを気にしながら発言したら十分な質疑なんかできないと思うんです。言いたいことは言い切れないと思うんです。だから、改めてそういう整理をする必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-020"},{"speaker":"川西副委員長","kind":"質問・要望","question":"私、副委員長の立場ですけれども、伺っていまして、それぞれのご意見もっともだと思いますので、委員会運営の中で生かさせていただきたい。委員長、それでいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":34344,"voices":89}},{"id":"h20-20080623-6","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"区民委員会","time":"午前１０時０２分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"今回の改正、条令の廃止においては、戸籍法と住民基本台帳法のほうで網羅しているというようなニュアンスだったんですが、改めて今回、廃止される条例がなくなることによって、これまで区で行ってきたものがすべて網羅されているのかという確認と、新たにそれ以上に今回の法改正で網がかかっていくのか、加えられたものを教えていただきたいと思います。","respondent":"上川内戸籍住民課長","answer":"件数なんですが、これは平成１５年、１６年ぐらいからこういう状況になったということが言われていますが、全国の戸籍の実務者でつくっている組織の調査によりますと、平成１６年から１７年の約１年半の間に、９３６件があったというふうなアンケート調査の結果も出ております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっとなりすましの目的のほうの後段の行政書士云々というのは、本人確認と関係あるのかないのかちょっと意味がわからなかったので、もう１回ご説明いただきたいということ。それから、ＤＶ関係です。これはどうなんでしょうか。課長のほうで、所管のほうでわかれば、実態がどうだったかということをお聞かせいただきたいと思います。ここら辺、私たちはどういうふうに区民としてとらえたらいいのか。","respondent":"上川内戸籍住民課長","answer":"本人にはデメリットはないんですが、今度、刑罰にすることによって刑法が適用されますので前科がつくという、そういう抑止力をねらって刑罰化をしたというものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"若林委員","kind":"質問・要望","question":"最後、ＤＶのほうで、裁判所云々というのがあれば、加害者とみられる人でも取得できるというニュアンスで今おっしゃったんですけれども、ちょっと違うかなと思いましたので、もう１回ご説明をいただきたいと思います。では、そこだけ確認します。","respondent":"上川内戸籍住民課長","answer":"ですから、全然公証をする証明書を全然出さないというわけではなくて、加害者には触れないような形で公証の証明書の運用はしておりますという意味です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"戸籍法および住民基本台帳のほうの改正内容のほうで確認したいんですけれども、今までの何人から限定ということで、これは不正な交付請求を防止するためということで、非常にいい改正だなと考えていますが、この限定ということなんですけれども、例えば本人が行けなくて委任状とかで請求したりするのだと思うんですが、その限定というところを確認させていただきたい。","respondent":"上川内戸籍住民課長","answer":"何人でもという精神はあるんですが、それがプライバシーの侵害とか犯罪に結びつくような、そういうなりすましとかを防ぐために、本人については、本人確認をするということで今までとほとんど同じなんですが、第三者の場合には、その目的とか、何に使うとか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"確認","question":"本人確認というのを、先ほど質疑のほうにも聴聞なども行うみたいな話もあったんですが、具体的には窓口ではどのような本人確認が行われるのでしょうか。","respondent":"上川内戸籍住民課長","answer":"本人であると推定されるものの提示を求めます。それで、ちょっとそれでは弱いかなと窓口で判断をしたら、家族構成とか、ご本人の生年月日とか、そういう聴聞をして本人確認をしています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"写真がないやつだと、顔で確認できませんから、次に保険証とか、キャッシュカードとか、そういうものを出すことになるんですけれども、ただ、家族構成などは聴聞という場合はこちらでその方が名前を名乗ったときに、どういう方だという情報をある程度お調べ、生年月日は何日ですねとか、わかった上で生年月日は何日ですかと聞くということが必要になる。","respondent":"上川内戸籍住民課長","answer":"ですから、今までよりも受付には、ちょっと区民の方、住民の方、時間をとられていろいろ聞き取りとかされて大変だろうと思いますけれども、そのような形で全国的に流れていて、今のところはスムーズに動いているということで、トラブルも聞いておりません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"もう本当に基本的なことをお伺いしたいと思っているんですが、代理人申請についてなんですけれども、例えば、僕の妻が住民票が必要だからということでもらう場合、代理人になってもらうわけです。子どもとか。これ、全く代理人は、赤の他人が何かの関係であればとることはできるんですか。住民票で。","respondent":"上川内戸籍住民課長","answer":"代理人の書類というのは、委任状を持ってきて、それで代理人申請という形で、代理に来られた方の本人確認をしますから、何かトラブルがあったときには、来た方の、本人確認していますからこっちに追いかけられるというふうな方向性になるわけです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"その代理人の範囲というのは、もうすべて赤の他人、例えば稲川委員におれの住民票をとってくれと、委任状が、要するに、この人に対して僕の住民票を渡してくれというような記載のものがあれば、それは出せるわけですか。","respondent":"上川内戸籍住民課長","answer":"委任状があれば出せます。","voiceIndex":19,"id":"exchange-008"},{"speaker":"渡部委員","kind":"確認","question":"要は何が聞きたかったかといいますと、結局、それでにせの委任状が仮につくられてしまっていて、ちゃんと委任状もあって、取りに来た本人確認もあれば、いわゆる僕が委任していない、委任状を書いていないのに住民票は出てしまうということなんですけれども、これはもう出てしまうということになってしまうんですか。","respondent":"上川内戸籍住民課長","answer":"そういう場合、その事件が明らかになった時点で、さっきの刑罰というところに行く。それからもう１つは、来た人は必ず本人確認していますから、この人が来てとっていったという証拠も残るということで、犯罪を担保しようという。","voiceIndex":21,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２点聞きたいんですけれども、品川区が同様の条例をやってきて、今回の法律の中でまたなんですけれども、品川区の場合、これまでこの条例で窓口で断ったケースというのはどのぐらいあるのか、どんな事例があったのかというのをわかったら教えていただきたいと思います。","respondent":"上川内戸籍住民課長","answer":"事例といいましても、例えば説明する中でトラブルになったことはありますけれども、個人情報を守るためにやっているんですよと説明するしかないですよね。件数はカウントしていないですね。それが日々の仕事で山ほどありますので、それほどのこれについてのトラブルはないです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"意見","question":"今の場合に、結局そういう相談というのはあるんですよね。ちゃんとしたお金の貸し借りではなくて、友達同士でのいわゆる何も、領収書もないし、借用書もないし、何もないので口約束で貸した、それが相手がいなくなってしまって調べたいという。そうすると、今のケースだと、全くそれは対応できないということになるんですね。","respondent":"上川内戸籍住民課長","answer":"もしそれが例えばストーカーとか、そういうものに紛れている場合もありますので、ただ親切心だけで、一面だけでやってしまうと、ちょっと危ない部分もありますので、それはよく話を伺って判断をさせていただいているところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、今みたいなケースは、一律にだめというふうにはなっていないというふうに理解すればよろしいでしょうか。","respondent":"上川内戸籍住民課長","answer":"ただ、それだけの話でしたら、多分だめでしょうね。何かお話を聞いている中でこれだけではないですかとか、ここは残っていないですかとか、そういう中で判断しますが、今のその話だったらちょっと難しいかと思います。","voiceIndex":27,"id":"exchange-012"}]},{"id":"topic-02","title":"第４４号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４４号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"確認は、そうしますと、差し引き８０万円が商店街みずからの負担という理解でよろしいかどうか。これをお聞きします。それともう１つ、商店街連合会ということですが、商店街振興組合連合会というのはまた違うものなのか確認させていただきたいと思います。要するに、お金の流れとしてどういうふうになるのかということを確認いただきたいと思います。","respondent":"金子産業振興課長","answer":"４点ほどのご質問かと思いますが、まず１点目の区の申請の経緯ですけれども、私どもとしましては、この事業の概要が東京都から説明があったときに、単に加入促進ということだけではなくて、特に４番目にあります商店街の規約であるとか、あるいは定款、あるいは経費等々。","voiceIndex":36,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"一番最初の定款の見直し等について、区のほうは注目をされたと。そもそも自分でやることではないんですか。というふうに私、感じる。いいのかなと単純に思いましたので、日常的に商店街振興組合と連携をとれるんでしょうか。実態、組織的に大丈夫でしょうか。どういう実態になっているでしょうか。ちょっとご商売されているほうから見ると、何か違うような気がするんですけれども。","respondent":"金子産業振興課長","answer":"そういう意味で、そういったこれから新たに加入をどんどん勧誘していこうというような場合には、やはりそういったところの整備をきちっとしておかなければならない、こういった認識は持っているわけですけれども、なかなか進んでいない現状がありますので。","voiceIndex":38,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"ちょっと違うような気がするんですが、じゃあ、例えば、２の事業内容の（１）から（５）までありますが、この４８０万円が、例えばどういうふうに配分されて、それはあくまでも商店街のほうで全部割り振るのでしょうか。それとも一定程度、区のほうで、これにはこのぐらい使いましょうと、講師にはこのぐらいかかるからこうしましょうとかという、ある程度の方向性を相談しながらやるのでしょうか。","respondent":"金子産業振興課長","answer":"この規約改定等々に関しましては、専門家に見ていただいて助言をいただくということから、単価としては、予定としては３万円程度を考えているところであります。","voiceIndex":40,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"それからもう１つは、品川区商店街連合会のホームページを品川ポータルサイトというのでしょうか、この中には今のとちょっと同じニュアンスになると大変申しわけないんですが、品川区商連の紹介があります。この日付が２００４年になっているんですね。そこには商店街の単会総数、これが加盟数が違うのかどうか僕はわかりませんけれども、６８商店街（商店会）となっているんです。","respondent":"金子産業振興課長","answer":"２００４年の日付でホームページ上は載っているというお話でしたけれども、申しわけありませんけれども、その部分は私もまだ確認しておりませんが、おそらく修正というか、カウントの仕方がちょっと違っている部分があって修正もし切れていないのかなと思います。","voiceIndex":42,"id":"exchange-016"},{"speaker":"若林委員","kind":"意見","question":"要するに、年に１回、２回、総会をやられて、大変盛大にやられているご様子を。ここら辺をしっかりやらなければ、いくら表にイベント等をやっても、それはやっぱり花が咲いていかないのではないかなという意味で申し上げましたので、ぜひ、これは直接区商連に言うことなのかもしれませんが、今回こういう補正予算が出てまいりましたので、ご指導いただければなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"年度が新しくなって、まだこの第１四半期にこのような補正が出るということは、どうしてなのかなと本当に思いますけれども、理由については、もう今の答弁でわかりましたのでいいんですけれども、この先、今、第１四半期なんですけれども、今年度中、第４四半期まである中で、ないとは思うんですが、例えば都の補助金が区商連の事業費の２分の１ということで歳入があるんですけれども、その補助金。","respondent":"金子産業振興課長","answer":"今、ここ近年、私が経験した中では、東京都の対応というよりも、例えば４月に２３区あるいは市のほうから全部申請が上がってくるわけですね。","voiceIndex":45,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"大きなところで言うと、やっぱり商店街の役割を区がどうとらえるかというところがすごく大枠なところで大事な認識だと思うんですけれども、商店街というのは、やっぱりかけがえのないものがあると思っているんですが、区はどうとらえているから、やる気があれば支援するというお話もありましたけれども、支援していこうと考えているのか、その商店街の役割に対する区の認識をちょっとお伺いしたいのと、あと。","respondent":"金子産業振興課長","answer":"今回の対象は１０商店街を予定しているということなんですけれども、そういう意味では、予定としては、固有名詞も上がっているんですけれども、ただ、詳細に決めていく中で明らかにしたいということですので、どこの商店街ということは。","voiceIndex":47,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"今回の新事業ということで、加入、読んで字のごとく商店街に加入を促進していこうということを支援するですけれども、それでパンフレットなどをつくるということなんですが、例えば、商店街に加入する際には加入料がかかると思うんですが、会費、経営が大変で加入できないお店ですとか、あるいはチェーン店というのはやっぱり何度も問題になっていると思うんですけれども。","respondent":"金子産業振興課長","answer":"チェーン店等の対策のお話しですけれども、もちろんこういったところで加入していないところがあれば加入について勧誘していくわけですけれども、あまり芳しくない結果があるものが、実は、うろ覚えで恐縮ですけれども、３年ほど前に東京商工会議所。","voiceIndex":49,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの質問のあれなんですけれども、今のでよくわかりました。","respondent":"金子産業振興課長","answer":"ですので、今回の事業というのは、そういったところをきちっとしていこう、きちっとさせていこうというのが非常に、先ほどちょっとご意見をいただきましたけれども、大きな事業の要素として考えているところです。","voiceIndex":51,"id":"exchange-021"},{"speaker":"渡部委員","kind":"確認","question":"１つ確認なのは、あくまでもこれは助成対象者が品川区商店街連合会なので、１つ１つの商店街に出すべきものではないわけですね。というのをまず１つ確認させて……。大きく２点です。","respondent":"金子産業振興課長","answer":"対象のお話しですけれども、事業の実施主体は確かに商店街連合会ですけれども、対象としましては、希望がある限り、予定は１０商店街となっていますけれども、商店街連合会に加盟していないところも対象にしていきたいと考えています。","voiceIndex":53,"id":"exchange-022"},{"speaker":"井桁委員","kind":"質問","question":"１つ質問なんですけれども、事業内容の３番のセミナー等専門家派遣の謝礼とあるんですが、この専門家というのは、商店街に対してということでしょうか。商店街に対して、商店に対してというセミナーではなく、商店街に対しての専門家を派遣するという考えでよろしいのでしょうか。","respondent":"金子産業振興課長","answer":"セミナーの開き方なんですけれども、商店街連合会として全体に声をかけるやり方もあるでしょうし、それぞれの各地域の単位商店街、あるいはその近辺の幾つかの商店街を対象として各商店の方に来ていただく、そういったこともあり得ると思いますけれども。","voiceIndex":55,"id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"その場合なんですけれども、足元をつくっていく土台を固めていって、これから商店街のますますの発展を願うということでは、このセミナー等専門家の派遣というのは、今後、大切なことになってくると思うので、ぜひそういったものの継続であったりとか、これが１回で終わるとか、単発で終わらないようにやっていっていただきたいなと思っているんですが、そういった方向性はお考えなのでしょうか。","respondent":"金子産業振興課長","answer":"今回はたまたまこの商店街組織力強化支援事業の中で講師の派遣についても予算が認められているのでここに載せておりますけれども、今後ともそういった商店街が勉強会をしていきたいというようなことがありましたら。","voiceIndex":57,"id":"exchange-024"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと細かいところで聞きたいんですけれども、先ほど、区商連に入っていなくても対象にしていきたいということで、私もそれは当然だと思うんですけれども、そうすると、今回、１０商店街となっているんですけれども、この予算と１０との関係はどういうふうに考えているのかということを聞きたいのと、あともう１つ、今回、助成額が４００万円で助成対象者は区商連となっているんですけれども。","respondent":"金子産業振興課長","answer":"商店街連合会に加盟していないところを対象にするという話なんですけれども、そういう意味では、本来的な商店街連合会の活動では、それは難しい部分もあるのかもしれませんが、この事業は商店街連合会に対して、区あるいは都として補助していくという事業ですので。","voiceIndex":59,"id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"質問","question":"今の区商連自体に加盟するというのが増えていくという、それはそれで必要なことだと思うんですけれども、そうすると、今回は区商連に助成する。そうすると、例えばこの事業を受けようとすると、今、加盟していない商店というのは加盟が条件になるということになるのか、そこら辺はどうなんでしょうか。","respondent":"金子産業振興課長","answer":"今、商店街連合会に加盟していない商店街が商店街連合会に加盟するのが条件になるかどうかというお尋ねだと思いますけれども、それを条件にするのは、ちょっと区としては難しいかなというふうには思っております。","voiceIndex":61,"id":"exchange-026"},{"speaker":"宮崎副委員長","kind":"質問","question":"けれども、もう１つは、やっぱり今、商店のところでいろいろ聞くと、商売自体が大変で、商店街に加入するという、その会費を払うということが大変だというところもあるので、何かもうちょっとそういうところの工夫もしていかないと、何か難しいかなという感じもして、これはこれで事業は大事だと思うんですけれども、非常に後、地盤沈下というか、そんなことを感じるものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"}]},{"id":"topic-03","title":"専決処分の報告について、報告第１４号","agenda":"専決処分の報告について、報告第１４号","exchanges":[{"speaker":"稲川委員","kind":"質問・要望","question":"報告事項なので確認だけさせていただきたいんですが、これ、消火栓に標識にぶつかったということでの損害賠償額なんですが、ぶつかったということは、パッカー車も、パッカー車なのかトラックなのかちょっとわからないですけれども、それも傷ついているわけですけれども、そういうのは、多分、いつも報告でパッカー車とかトラックがぶつかったという報告をいただくんですが。","respondent":"島袋品川区清掃事務所長","answer":"ぶつかっただけです。うちのほうには損傷はありませんでした。消火栓の標識は壊れましたけれども、プレス車のほうは今回なかった。実は、特殊塗装で、もともとごみをギュッと詰めるものなので、相当強くしているんです。それと、プレスの場合は、私共には整備工場があるんです。","voiceIndex":70,"id":"exchange-028"},{"speaker":"本間委員長","kind":"質問","question":"私のほうから、今定例会の一般質問にかかる所管質問について、ご案内申し上げます。本件は、委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問にかかる当該委員会の所管質問を行うというものです。質問をなさりたい委員がいらっしゃいましたら、委員長に通告し、翌日、理事者に答弁していただくこととしております。所管質問がございましたら、ご発言をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのことについて聞きたい。もう１つは、浅野議員のほうの特定健康審査のことについて質問があったんですが、健保の扶養家族の健康診断がどうなるのかということで、区民の方からもちょっと不安の声も寄せられておりますので、そこら辺についてお伺いしたいなと。そこの項目について、より伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"今まで特定健診の健康診査についての浅野議員のほうから、これまでと変わった、これまでは４０歳以上の区民であれば、健診を受けられたわけですけれども、それが今年の４月から変わって、とりわけ、特定健康診査というものが変わったんですよね。そこに関しての現状がどうなっているのかということを深められればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":24880,"voices":82}},{"id":"h20-20080623-7","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"厚生委員会","time":"午前１０時０５分～午後５時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を126件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"第１７条で、「第３条第３号および第４号に規定する業務の運営に関すること」って中身に踏み込んだところが、省略されて載っていないんですよね。よろしくお願いします。では、中身に入ります。内容は下に書いてあるんですけれども、具体的にどういったところが変わってくるのかということを、まずお伺いしたいと思います。","respondent":"山岡健康課長","answer":"その後、事業運営の中で、我々もモニタリング、あるいは評価といったことを、事業の開始以降はしていくつもりですので、その辺で、しっかりとした住民サービスの向上をみずから図っていかないと、なかなか継続的に事業運営をやっていけないのではないか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"そういった中身で、十分できるのではないかなと思うんです、モニタリングとかもありますけれども。その辺、委託と指定管理者と、具体的にどう違うのか、もう１回、その辺を聞きたい。それから、現在、委託料がありますよね。それが、指定管理者になっていくと、区から指定された事業所に行くお金が、どういうふうに変わっていくのか。その辺も教えてください。","respondent":"山岡健康課長","answer":"委託でも、かなり指定管理者に近いような形の運営ができるのではないかというご質問です。ただし、かなり事前に契約内容を打ち合わせをして、業務委託をするということも考えられなくはないんですけれども、一度契約をしてしまいますと、１年間それでやっていただく。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"今のところが、ちょっとよくわからなかったんですけれども、業務に係る経費、この辺は大体わかりますよね。その辺はどうなんでしょうか。","respondent":"山岡健康課長","answer":"ただ、それはもちろん副次的に、区の経費の節減になろうかと思うんですけれども、それは副次的ということで考えておりまして、現在のところ、基本的には区民サービスの向上をまず第一に図るというところにポイントを置いて、それでなおかつ経費が抑制できることがあれば。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次に、４番目に業務の範囲というのがあるんですけれども、まず初めに、健康センターの設置の目的を、ちょっと明確に答えていただきたい。それから、業務の内容のところで、健康づくりに関する事業等の運営と書いてあるんですけれども、事業計画自体は、どこでどう立てられるのか、事業計画について教えてください。","respondent":"山岡健康課長","answer":"事業計画は当然、こちらの今後の予定の中で申し上げますと、協定をするために事業計画書を出していただくということになろうかと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"第１６条の事業計画について、業者まかせになるのでしょうか。第１７条の施設の維持と修繕に関することについて、設備機器の設置や更新時の負担はどうなるのでしょうか。","respondent":"山岡健康課長","answer":"もう一つは、施設の維持、修繕の関係です。これにつきましては、例えば、設備、機器の関係も含めて、指定管理者にお願いしたいと考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"設備、機器も含めてということは、リニューアルをするときには、指定管理者がみずから負担をするという考えでいいのか、どうか。それから、選考基準の中には、経営の努力なんかも求められていくと思うんですけれども、そこで働く職員の労働条件とか、そういった部分についての把握というか、その辺はどういうふうになっているのか、教えてください。","respondent":"山岡健康課長","answer":"ただ、どういう機器を導入するか等々は、区と協議しながらやっていく部分は、当然あろうかと思います。それから、そこで働く方たちの労働条件等々ですけれども、私どもも、指定管理者の運営全体の中で、社員、職員の労働条件も、当然把握してまいりたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですけれども、指定管理者が管理する施設というのは、健康づくり施設と貸出施設だけではなくて、健康診断室や健康指導室も指定管理者が管理すると読めるんですけれども、それでよろしいんでしょうか。","respondent":"山岡健康課長","answer":"この範囲の中で、先ほど申しました、設備等も含めて指定管理者に任せたいです。ですから、１階、２階の保健センターでやっている業務については、指定管理の対象になりません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"その二つの業務が対象にならないというのは、先ほど来出ていたと思うんですけれども、要は、ここで施設に関することということで、箱としてのセンター全体ですけれども、そちらはどうなんでしょうか。","respondent":"山岡健康課長","answer":"施設の管理につきましても、保健所業務をやっている、１階、２階、３階の保健センター部分は、その対象になりませんので、３階にも一部ありますけれども、基本的には４階から上の施設管理について、指定管理者のほうにお願いしたいと考えているです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"それを聞いて妥当かなと思ったんですけれども、すみません、この条例から、そう読めるんでしょうかね。あくまでも健康づくりの施設についての管理と明記。それを悪用して、ということはないかもしれないですけれども、一応、条例ですので、その辺ははっきりしておいたほうがいいんじゃないかなと思うんですが、いかがでしょうか。","respondent":"山岡健康課長、古川児童保健事業部長","answer":"この条例ですけれども、保健センター条例、これは施設全体の条例でございまして、このうちの健康づくり部分だけということで、今、考えているところです。基本的には、現行条例に対する指定管理者制度を導入するに当たっての一部条例改正ということを、まずはご理解いただきたいということと、今、健康課長のほうからお答えしたとおりなんですが、条文の中でも。","voiceIndex":21,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"丁寧なご説明をありがとうございました。私もそこまでじっくり読んだわけではないので、問題ないということなんでしょう。第５条のセンターの休館日を、指定管理者が別表第１にかかわらず決めることができるという中には、健康診断室や指導室も入っているんですけれども、何かちょっとそれも少々違和感があったものですから、伺ってみました。もし、それについて何かあれば、細かいことですみません。","respondent":"山岡健康課長","answer":"改めて、第１７条の指定管理者の行う業務の範囲の中でですので、先ほど申し上げた健康診断室、指導室の関係は入ってきませんので、ご理解いただけるのではないかと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"細かい話はこのぐらいにして、要は、一つの建物の中で、指定管理者が入る部分と、従来どおり健康診断や健康指導をする部分と、どこか連携が必要になってくるような部分というのもいろいろ出てくるかと思うんですけれども、それについては、どのような対応、対策を考えていらっしゃいますでしょうか。","respondent":"山岡健康課長","answer":"今、お尋ねの件は、当然予想できることだと思いますけれども、とりあえずは、今回は条例改正をさせていただいて、その次の段階で、いろいろそういうふうな調整が必要なものについては検討していきたいと考えています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"指定管理者制度と、これまでの委託と、似たようで、やっぱりだれに決定権があるのかというところが、特に日常、随分変わってくる部分でもあると思いますので、ぜひ、そこのところはしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"施設管理のところで、さっき、第１７条(5)の部分で、「施設等の維持および修繕に関すること」という限定をされているんですよね。もう１回ちょっと、今度、指定管理者制度はわかるんですけれども、ちょっと何かそこが、今度の指定管理者の契約に基づいたところの施設の管理とかというのならわかるんですけれども、ここがちょっと気になるんですけれども、もう１回、よろしいですか。","respondent":"山岡健康課長","answer":"第１７条の第２号の関係ですけれども、第４条第１項の第３号および第４号に規定する施設の運営に関すること、ということで、まずここで、第４条をごらんいただくとおわかりのように、第３号で健康づくり施設、第４号で一般貸出施設。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あれは、現在、こんなコースをやりますよというのは、区と調整はしていらっしゃるんでしょうか。逆に今度は、指定管理を受ければご自分でできるから、今以上のやりやすい形でできるから、指定管理の効果、利用者にとっていい方向だなと思うけれども、現状を教えていただきたい。それから、今度は指定管理者になったときに、この部分はどうなるのか、一緒に教えてください。","respondent":"山岡健康課長","answer":"ですから、まるっきり白紙委任ということではなくて、１０年間の実績がありますので、ある程度区と話し合いをしながら、中身を詰めていきたいとは考えております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前より大分よくなっていると聞いているので、ぜひ生かしていただきたいという意味のお願いです。それから、レストラン部分に関して、第４条で、センターの施設の中のどこに含まれるのかわからなかったので、この指定管理者に含まれるのかどうかというのを確認したんです。レストランではなくて、健康づくりの部分で生かしていくということでしたら、それで結構ですけれども、効果的な活用をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"今回、指定管理者制度にする理由としましては、区民のニーズに合ったりとか、事業者のノウハウ活用をしたりとか、さまざまなメリットを、今、挙げられていると思うんですけれども、指定管理者制度は平成１７年７月に基本方針を策定されていまして、こうやってリストを見ると、結構古く平成１８年からやっているところが結構多いのに、これだけメリットがあるのに。","respondent":"山岡健康課長","answer":"始めて何か、５年じゃない形のほうがいいという状況がありましたら検討してまいりますけれども、基本的には、５年ということで考えてまいりたいと思います。それから、現在、コナミスポーツ＆ライフが運営していますけれども、その間に何か事があったのかどうかです。","voiceIndex":34,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"わかりました、後でお願いします。それから、これが通りますと、具体的に要求仕様書ですとかを作成をされると思うんですけれども、先ほど、阿部委員も言われていました他の施設との連携ですとか、そういう気になる部分につきましては、ぜひとも要求仕様書の中に織り込んでいただきたいと思うんです。","respondent":"山岡健康課長","answer":"先ほどのコナミスポーツ＆ライフに業務委託したのはいつからかですけれども、品川健康センターのほうは平成１４年４月からお願いしているものです。それから、荏原健康センターのほうは、平成１２年から業務委託しているものです。","voiceIndex":36,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"指定管理者の情報公開が、この条例の中でどうなっているのかというのをお聞かせいただきたい。安全性のチェックがどのように担保されるのか、その辺も聞かせてください。","respondent":"山岡健康課長","answer":"情報公開につきましては、基本的には、区のほうで定めてあります指定管理者制度活用に係る基本方針の中に書いてある表現に沿って、ちょっと読みますと、「情報公開につきましては、指定管理者が保有する当該指定管理業務に関する情報について、情報公開の申請があった場合。","voiceIndex":38,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"意見","question":"情報公開もそうなんですけれども、指定事業者自体が、さらにその先に委託をしていたり、下請けというか、仕事を出している部分においても、情報が取れるのかどうか。安全性や何かの管理についても、やっぱりそういうところが影響すると思うので、確保ができるかどうかが１点です。私は、基本的には、公共の施設ってそんなに収益が上がるものでないと考えています。","respondent":"山岡健康課長","answer":"事業者をこれから選定するということですので、現段階で、その先がどうなるかということについて、ちょっとお答えのしようがございません。先ほど、情報公開については、基本的な考え方を申し上げたとおりです。指定管理者のほうで十分な対応ができるものと考えております。","voiceIndex":40,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"その辺が、やはり利用料によったり、希望のコースなんかによって利用料金が変わってきたり、日割りではなくて、月額でどうのこうのとか、いろいろなノウハウがあると思うんですけれども、その辺の公平性というのがどういうふうに担保されるのかというのが、ちょっと心配なんです。","respondent":"山岡健康課長","answer":"事前評価、あるいは事後評価を含めてですけれども、私どもがポイントとしていますので、ご心配になるような点は少ないのではないかと考えています。","voiceIndex":42,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つは、第１５条第３項で、利用料の額は使用料の額を超えない範囲内で、指定管理者があらかじめ区長の承認を得て定める額ということで、かなり指定管理者が定められるという感じで受けとめられるんですけれども、そういうところで、区民にとっては負担増になっていかないかということ、その点を一つお聞かせいただきたいと思います。","respondent":"山岡健康課長、古川児童保健事業部長","answer":"ですから、基本的には、それほど利用料を増やすということではなくてやっていただきたいと考えていますけれども、例えばこういうコースでやる場合には、これだけ必要だということであれば、プラスアルファの部分があれば。それは、先ほど、理由についてはご説明申し上げました。","voiceIndex":44,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"利用料は上げない。だから、そういうところで、コナミスポーツ＆ライフの職員が、必要な部署に必要な専門職員をということだけじゃなくて、やっぱりどういうふうに配置されていて、どんな中身になっているのかということはしっかりと把握をすることが必要だと思いますし、区民の健康づくりのところで、区がかかわる施設にというところが、とても求められていると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託から指定管理者に変わるところにおいては、いろいろなメニューが増えたり、開館の時間が長くなったり、喜ばれることもあるかとは思うんですけれども、私たちはちょっと視点を変えて、今、区民の健康増進、生活習慣病とか増えている中で、また特定健診とか、特定健康指導とか、すごく期待が高まっている中で、ぜひ健康づくりについては、ふさわしい場所の拠点になってほしいという意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"態度表明という形になっていますけれども、健康センター自体の健康づくり部分が、業務委託の内容が大分拡大していったことによって、かなりよくなっていったと、区民の方の評判を聞いております。ですから、どこが指定管理を受けるかわかりませんけれども、これからも同じような形で継続してやっていただきたいということで、私ども自民党としては、この条例に対して賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"この条例につきましては、私たちとしても賛成ということです。あるいは、区民が利用する面からいけば、より満足度の高いサービスを提供できるというお話ですから、そうであったという、後で検証するときに、結果としてよかったとなるようにしていただきたいということを申し添えて、この件については賛成と申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問・要望","question":"もともとが公的なところですので、広く皆さんに使っていただける、それは料金だけはなくて、むしろそういった体力的な意味で、皆さんによりよく使っていただける、そしてほんとうの意味での健康増進の施設になるような点を、忘れないで運営していただきたいと、そういった意見をつけた上で、この条例に賛成をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"コンセプトのところに、「低所得者層のうち生活の安定に向けて支援を真に必要とする者を対象」とありますが、その辺の真に必要というあたりの判断はどうするのかと思います。それから、幾つものメニューがありますけれども、これで、どのぐらいの方に支援が行くのかというところをお伺いします。","respondent":"志村生活福祉課長","answer":"どのぐらいの人に、ですけれども、すみません、私の説明で、ちょっと落としてしまいましたけれども、実は東京都がこの事業で対象として予定しております方が１７万人と考えていますと、このようなことです。","voiceIndex":58,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"石原東京都知事の選挙前の公約からすると、かなり規模が小さくなって、都民、区民の重税感の軽減にはなかなかならないのではないかなと思います。ここに幾つもメニューがあるんですが、都のほうで低所得者対策といって、これ以外に何か出してるものがありましたら、教えてください。","respondent":"志村生活福祉課長","answer":"例えば一人世帯の場合ですと、これから言いますと、大体１７０万円ぐらいの収入の方ではないかなということで、低所得者向けのいろいろな貸付金等がございまして、このときに用いられたものと大体同じような算定式を持っておるものですから、私どもとしては、これで。","voiceIndex":60,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、都の広報の仕方と、それから品川区においても、窓口に置いておかれるということなんですが、なるべく大勢の方に伝えられる方法と、生活福祉課長のセクションでは、パンフレットとか、身近にわかりやすく紹介をしていただきたいと思います。それから、住居喪失不安定就労者のことなんですが、ここの中身をちょっと具体的に教えていただけたらと思います。","respondent":"志村生活福祉課長","answer":"ですので、この事業につきましては、まだまだ始まったばかりでございまして、今のところ、２人１チームになりまして、それぞれネットカフェに行ってというようなことを予定しておりますけれども、今、新宿、池袋、渋谷から始めておりますというような報告を受けております。","voiceIndex":62,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何点か、ちょっと教えてください。いただいたこのＡ３版の資料は、東京都がつくられた資料を、そのまま区が使ったということでよろしいんですか。","respondent":"志村生活福祉課長","answer":"課長会で配られました資料そのままと、私どもで加えましたのは、厚生委員会資料ということで、わかりやすいように、東京都福祉保健局・産業労働局、それを加えました。","voiceIndex":64,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと確認したかったのは、実施したときに、先ほど、７月１日に東京都が発表して、区が窓口の体制を今、つくっているわけですけれども、その発表と同時に、区がもう相談業務を受ける形になっちゃうのか。先ほど、区で、窓口の相談員２人が専従するというお話でしたけれども、新たな人が入るというのならお金がかかるんですけれども、現在の区の職員が相談員になるということでよろしいんですか。","respondent":"志村生活福祉課長","answer":"すみません、予算の中身について説明しませんでしたけれども、２,３３３万４,０００円につきましては、東京都から全額委託料がまいります。","voiceIndex":66,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"人が入るということですね。その辺がちょっと気になってはいたんですけれども、それを教えてください。東京都に書類を出すときには、確認してからあっ旋しなきゃいけないわけですよね。そこの段階で、かなり時間がかかっちゃうんじゃないかなという気がするんですけれども、そこら辺はどうでしょうか。","respondent":"志村生活福祉課長","answer":"ですので、今回の相談員２人につきましても、私どもが今相談業務をやっています面接相談員と同じ係に置いて、横の連携といいますか、この事業で来たんだけれども、途中からは生活保護のほうになっていくかもしれませんので、その辺の連携も含め、それから。","voiceIndex":68,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは東京都の話になると思うんですけれども、生活資金の無利子貸付６０万円、それから、就職等一時金の無利子貸付５０万円と出てきますけれども、区は、数字的に関係ないかもしれませんけれども、どのぐらいの人数、予算化しているのかちょっと気になったんですが、その辺、区のほうでおわかりになりますか。","respondent":"志村生活福祉課長","answer":"ただし、これは３年間の事業で、景気の動向等によって変動があるかと思いますけれども、現在予定されているのはこの数字と聞いております。","voiceIndex":70,"id":"exchange-033"},{"speaker":"渡辺委員","kind":"確認","question":"ちょっと確認なんですが、このプリントの中で、黄色の色分けをされているところが、品川区にも窓口を置かれるという中で、先ほど、対象者のところで、都の算定式によりますと、品川区の対象者は５,０００人弱ということで想定している中で、その黄色二つの中で、生活安定応援事業と、下のチャレンジ支援貸付事業ということで、こちらのほうは、今このプリントではないんですが、諸条件があるのかということ。","respondent":"志村生活福祉課長","answer":"この基準というか、この要件は、公共職業訓練のこれにつきましても同じ基準になってまいりますので、この事業のいろいろ貸付金等々につきましては、この条件が全部入ってくるというように予定をしています。","voiceIndex":72,"id":"exchange-034"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認させていただきたいんですが、まず、補正予算書２,３００万円の経費の内訳は、今、ご説明いただいたところによると、専門相談員が常時２名なので、その方の８月から来年３月までの８カ月間の経費という理解でいいんですか。ちょっとその辺、確認させてください。","respondent":"志村生活福祉課長","answer":"それで、年間７００万円が上限でございまして、そのうち６５０万円は人件費に充ててくださいという東京都の説明でございました。ですので、事務費は５０万円まで。","voiceIndex":74,"id":"exchange-035"},{"speaker":"堺委員","kind":"提案","question":"実は東京都議会におきまして、６月１８日の本会議で、この件に絡めて我が党の議員が、受験を控えた中高校生のいる低所得者世帯に塾の費用など無利子で融資するチャレンジ支援貸付事業について取り上げまして、生徒に意欲がある場合の、返済、免除についての条件緩和をしていただきたいと、その席上に提案をいたしました際に、安藤さんという福祉保健局長が、「高校や大学に入学するなど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-036"},{"speaker":"阿部委員","kind":"確認","question":"幾つか教えてください。開設時間が、平日の９時から５時ということなんですけれども、対象の方が平日フルで働いていらっしゃらないことを念頭に、こういう時間になっているんでしょうか。最後に３点目、一たん相談を受けられて、要件を確認しながら、都につないでいくということなんですけれども、都の窓口につなげた後というのは、区としてはケース終了みたいな形で終わりなのか。その辺を教えてください。","respondent":"志村生活福祉課長","answer":"面接相談員２人を予定しておりますというのは、常時２人いてくださいというのを最低要件でいこうかと考えております。ご質問にありましたとおり、この事業についての中身も当然ですけれども、その他の福祉施策についても熟知していないと、なかなかこれは難しいだろうと思います。","voiceIndex":77,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"提案","question":"初めに、提案理由です。更に今年４月からは、７５歳という年齢で高齢者を差別する後期高齢者医療制度が導入されました。本来ならば高齢化の進展と共に、社会保障の充実が求められるところです。自治体としてできる「高齢者の安心」のしくみとして今回品川区高齢者医療入院時負担軽減支援金の支給に関する条例を提案します。目的、第１条です。対象者、第２条です。第３条と第４条に記してあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-038"},{"speaker":"渡辺委員","kind":"提案","question":"プリントに沿って、お伺いします。これはこれまでの後期高齢者医療の制度を認めた上での話、あるいは、ほかにお考えがあるなら、いろいろな表現の仕方もあるかと思うんですが、この辺の提案理由の中で、あえて明記されているところを、ちょっと確認させてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"意見","question":"私たちは、後期高齢者医療制度は廃止しかないという立場なので、条例の中には、後期高齢者という名称は使っていません。７５歳以上、なぜなのかというところにおきましては、現在の老人保健医療制度が７５歳からとなっていますので、７５歳といたしました。ここから支援をして、段階的に７０歳、６５歳と引き下げて支援を広げていきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-040"},{"speaker":"阿部委員","kind":"質問","question":"数字はうろ覚えなんですけれども、たしか、日本の個人資産って３兆円ぐらいあるんでしたっけ。その中で所得制限なし、さらには、資産という発想もあるかと思うんですけれども、そういった経済的なバックグラウンドを全く勘案しないで、ただ入院したら支給するというのは、ちょっと何かバランスに欠けるような気がするんですけれども、その辺のお考えはどうなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"所得の差、多い人も少ない人もいるというところで、その差をどう考えていくのかという、バランスのご質問でしたけれども、本来、所得の開きというのは、累進課税のところで応分の負担を求めていくのが基本であると思っています。社会保障というのは公平であるべきと考えてています。所得制限がないというのは、先ほど、説明したように、医療費は無料化の方向でいきたいという思いからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-042"},{"speaker":"阿部委員","kind":"確認","question":"後半おっしゃっていたのは、高齢者にもいろいろな資産状況があるということを、むしろおっしゃってくださったのかなという気がいたします。医療費と同列に考えるのは、少し性格が違うのではないだろうか。全体として、バランスとしてどうなのかなということ。そういう人件費という見えないコストのことも考えると、果たして、ちょっとどうかなという気がしますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"意見","question":"その辺あたりで、大体１万円ぐらいにはなるであろうという、こういう大まかな考えでいるんです。申請のコストということにおいては、やり方はいろいろあると思うんです。それから、高齢者と子どもと同列ではないと。私たちは、命を守る医療に関しては、社会保障で人権を守るという立場で等しく保障していくという基本的なところがありますので、そういった面で、所得制限は取り払うと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"多分、これは終わらないと思うので、このぐらいにしておきますが、いちいちそれはちょっとどうかな思う点もいろいろあります。天から降ってきたお金なら使ってもらってもいいんですけれども、やはりこれは税金から出ることですから、そんなに１万円もらったってありがたくないという、くれるならくれるかという層まで合わせて税金を注ぎ込んでいく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"確認","question":"何点か、確認だけします。予算上で、今年度、５,７５０万円組んでいますが、これの財源がどうなっていくのかが１点。先ほど、阿部委員からもお話があったように、うちのほうの渡辺委員からも出ているように、７５歳で切っているのは、そこら辺との絡みの公平性という点でどうなのかなというところを、先に教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"提案","question":"財源なんですけれども、今回は条例の提案をさせていただきましたけれども、地方自治法第１１２条、表のところに書いてありますけれども、「議員は議会に議案を提出することができる。ただし、予算についてはこの限りではない」ということで、今回は、予算の修正は出していないんですけれども、品川区の現在の財源からすると、５,７５０万円は十分やっていけると思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-047"},{"speaker":"浅野委員","kind":"質問","question":"予算の中で、年間入院件数が２万３,０００件で、年間予算総額２億３,０００万円で、入院１件につき１万円という予算を組まれているんですけれども、ここら辺の目安というんでしょうか、どのような形で、このような予算を書かれたのか、ちょっとお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"意見","question":"入院のある月ということで、いつ入院されるのかによって費用は違うと思うんです。それから、予算の出し方、２万３,０００件というのは、１カ月に１件というカウントの仕方なので、１カ月１万円ということで、２億３,０００万円というのはマックスの金額になるんです。老人保健のほうのレセプトの数で出してあるので、マックスの数字となります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-049"},{"speaker":"浅野委員","kind":"意見","question":"ちょっと、第４条のところが理解できなかったんです。入院した日のある月、１月当たりということなんですけれども、入院した日が、例えば６月３０日でも結構なんですけれども、６月３０日に入院して、例えば２日で７月１日に退院した場合、３０日の領収書がマックス１万円ですよね。ちょっとここら辺の言い回しがわからなかったんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-050"},{"speaker":"堺委員","kind":"確認","question":"私、聞き漏らしていたらごめんなさい。支援金の対象と額のところで、入院中に生じた費用としてあって、その後に、医療費と併せ云々となっていますけれども、先ほどもご指摘があった、要するに入院中の身の回りの費用と医療費両方にこの支援金は使えますよというふうに、我々理解をするのかどうか、ちょっとその辺、確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-051"},{"speaker":"堺委員","kind":"確認","question":"両方ということは、今、確認できたんですけれども、例えば医療費については、たしか、生活福祉課だったでしょうか、高額療養費の貸付制度というのがありましたよね。場合によっては、請求書を窓口に提出すれば、それなりの制度の中で、たしか対応できたかなと思うんですけれども、その辺ちょっと教えていただけますか。","respondent":"永尾高齢事業課長","answer":"それ以上かかった部分については、本人の負担はないんですけれども、今の貸付金のお話ですけれども、最初、普通に、高額療養費を請求するんですけれども、実際にお金が本人に戻るまでに４カ月ぐらいかかってしまうので、その間。","voiceIndex":105,"id":"exchange-052"},{"speaker":"堺委員","kind":"確認","question":"さっき、子どもの医療費についても、お話がでておりましたけれども、私の記憶に間違えがなければ、子ども医療費の無料は、入院、通院を問わず、保険診療分に係わる費用の自己負担分を助成するという制度だったような気がするんですが、ちょっとその辺、確認させてくれますか。","respondent":"諸岡児童課長","answer":"ご質問にございましたように、子どもの医療費に関しましては、入院、通院問わず、保険診療分のかかった医療費の自己負担分について助成をするというものです。","voiceIndex":107,"id":"exchange-053"},{"speaker":"堺委員","kind":"提案","question":"それからもう一つは、どうしても私個人的な見解ということでお話ししますが、提案理由の中に非常に気に入らない表現がある。これは共産党独特の言い回しなので、そこまで私がとやかく言うものではないのかもしれませんが、言論の自由、表現の自由ですから、こういうお言葉をお使いになるのかもしれませんが、どうも私としては気に入らないんです。これは党としてじゃなくて、私の個人的な見解であります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"提案","question":"二度目で申しわけありません、簡単に１個だけ。この支給がされると、月々１万円が、例えば１年間入院なさっている方は１２万円という形になると思うんです。そうすると、別の考え方で、申告をした段階で、医療費控除というのがありますよね。この１２万円を、提案者側はどういうふうに考えているのか、教えてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それは、所得になるんですよね。控除は控除で引くんだけれども、そんなことも考えると、入ってくるところがちょっと違うとは言え、例えば１００万円かかった方が、今度は１２万円を落として申告しなきゃいけなくなるんじゃないかと、私は考えたんです。今ここで、法的なことははっきりわからないけれども、そこら辺はどこまで考えているのかなと急に思ったんで、お答えをいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"提案者として一言だけ。それが、住民税非課税世帯の最低の方でも、月１万５,０００円ということになっておりますので、１カ月入院した場合には、少なくともそれだけは負担がかかるということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-057"},{"speaker":"堺委員","kind":"意見","question":"先ほども個人的な見解という前提で申し上げましたが、重ねて、この医療費については、先ほど、副委員長もおっしゃっておられましたが、例えば確定申告のときの医療費控除とか、幾つかの救済措置はある。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-058"},{"speaker":"阿部委員","kind":"提案","question":"ただ、今回のご提案については、趣旨というか、何とかしたいというお気持ちは伝わってくるんですけれども、ちょっと制度としての公平性とか、ほかのいろいろなさまざまな仕組みとのつながりですとか、あるいは、さっきもちょっと出ましたけれども、入院がそうだったら、施設にいる方はどうなんだとか、在宅の方はどうなんだとか、７５歳はどうなのかとか、いろいろと制度設計の上で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-059"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"だれに伺う形になるのか、一番詳しい方というか、ご本人というか、紹介議員の方なのか。ちょっと読み取れなかったのが、区に家族から直接派遣してほしいという内容なんでしょうかね。つまり、医療機関に対して派遣してほしいということは、現行でもできるということなんでしょうか。もし、その法律について何か検討の動きがあるとか、そういうことがあれば、あわせて教えていただきたいんですが。","respondent":"高橋障害者福祉課長","answer":"看護師とか、理学療法士につきましては、単独の開業はできなくて、現在、日本の場合は、やはり医師の指示の中で診療の補助というような形で行われているのが現状です。見直しは、今のところつかんでいません。","voiceIndex":126,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"重度の障害者（児）で、在宅生活をされていらっしゃるということなんですけれども、こういった方が区内にどのぐらいいらっしゃるのか、多分、生活の困難さとかつかんでいらっしゃると思うんですが、まずその辺をお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"重度で人工呼吸器をつけている方であれば、現在、在宅で７名ということでつかんでおります。","voiceIndex":128,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この請願を素直に読んで見ますと、家族の急な用事のために、家族以外に、というところで、例えば緊急にどこかに宿泊で親が行かなくちゃいけないような場合で、連れて行かれないときとか、通院通学の移動というのは、多分、ふだんは家族がされていらっしゃる、でも、急なけがとか、病気で、親ができない場合、現状においてはどういう手だてがあるのか、まずそこのところを聞かせていただきたい。","respondent":"高橋障害者福祉課長","answer":"私どもで行っているのは、医者に見ていただいた上で、ご家族、もしくはご本人に対して訓練とか、生活指導ということで、どうしたら生活がしやすいのか、どうしたら痛みが押さえられるのかということの指導を、月１回程度、行っているものです。","voiceIndex":130,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"リハビリのところは、私もちょっとよくわからないんですが、痛みを極力押さえていきたいというところで、これを読んだ限りでは、こういう願いはあるのかなという思いもするんです。もう１回そこのところ。その辺で、どのぐらいの利用が、ショートステイができるのか、教えていただきたい。その辺をちょっと、あまりよくわからないので、教えてください。","respondent":"高橋障害者福祉課長","answer":"訪問看護師につきましては、訪問看護という制度がありますので、医療制度の中の健康保険法、それから、介護保険法によりまして、医療機関からの派遣ということで、あくまでも、これは医師の指示書に基づいて行われているものと考えられますので。","voiceIndex":132,"id":"exchange-063"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと推定に次ぐ推定の質問になっちゃうんですけれども、いらっしゃるけれども、急なときに訪問看護が受けられないというのは、容態が変わったとか、何か健康上の問題じゃないときていただけないということなんでしょうか。在宅でリハビリ可能な理学療法士の派遣という対策はできないのでしょうか。ちょっとすみません、雑な質問で申しわけないんですけれども。","respondent":"高橋障害者福祉課長","answer":"在宅である程度安定しているということを前提に、緊急の場合につきましては、週３回までだからだめというような訪問看護ではないかと思うので、その辺につきましては、訪問看護のところについては、私は直接調査をしておりませんが、多分。","voiceIndex":134,"id":"exchange-064"},{"speaker":"阿部委員","kind":"質問","question":"私、聞き方がちょっとわかりにくかったかもしれないんですけれども、緊急時には、救急車などで搬送してって、それはわかりました。受け入れの問題もそうかもしれませんし、そこまで行くのは、逆に大事になってしまって大変ということもあるかもしれないんですけれども、そういうときに、何かしてもらえるとしたら、やっぱり医師から看護師を派遣してもらうという選択肢だけなんでしょうかね、現行制度では。","respondent":"高橋障害者福祉課長","answer":"その辺は、ちょっと、私は訪問看護制度の中身をすべて知っているわけではありませんので、その辺については、柔軟に対応している方もいらっしゃるのかどうかは、ちょっとつかんでおりませんが、今、私が考える中では、ご家族が外に出るという状況だけを踏まえて。","voiceIndex":136,"id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それとも、介護支援的な部分になるのか、どういう判断をとったらいいのか、ちょっとその辺、教えていただければと思います。","respondent":"高橋障害者福祉課長","answer":"基本的に、通学になりますと、安定しているからこそ通学できるということなので、ここの辺につきましては、多分バスとかいろいろな形でご家族が送っていくとかということで、看護師がいなくても十分に対応できているのかなと、私は思っているところです。","voiceIndex":138,"id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"質問","question":"看護師はわかったんですけれども、そういう場合の対応として、支援方法というと、さっき質問とちょっと重なってくるんですけれども、今の状況で、何か対応方法はないのかなと。","respondent":"木下福祉高齢事業部長","answer":"現実に、ショートステイで対応できないときには、どうなのかとなってまいりますと、現状では、おそらく家族、あるいは親戚、同じ疾病を持っている方々の応援、そういうネットワークの中で対応されているんだろうと思います。","voiceIndex":140,"id":"exchange-067"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３回目だと思うんですけれども、去年とか、その前であれば、いやこれは制度としても無理なんじゃないかと思うようなもので、去年は、緊急一時看護師派遣制度の新設という請願だったので、それはちょっと無理なんじゃないかなと思ったんですけれども、今回の部分で見ると、こういう場合の訪問看護師の派遣ということなので、それは区がどうのというのはなかなか難しいというのはわかるんですけれども、例えば。","respondent":"高橋障害者福祉課長","answer":"先ほど、ヘルパーのたん吸引の問題ですが、現在、厚生労働省のほうが検討しているというのは、いろいろなところでニュースみたいなところで流れてきているんですが、実際上やってもいいということになると、ヘルパーは。","voiceIndex":142,"id":"exchange-068"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ただ、区として制度をつくるというところでは、なかなか難しいのかもしれないんですけれども、今ある制度の拡充なり、さらにまた新たにそういう医療ショートやデイサービスの拡充なり、リハビリも含めてだと思うんですけれども、そういう現実のところから出発しての重度障害者の支援の拡充というのは必要なのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-069"},{"speaker":"堺委員","kind":"質問・要望","question":"それにはやっぱりいろいろな壁がある。今回で３回目ですか。ですから、何らかの方法で、こういう困っている方を救済という言葉が適切かどうかわかりませんが、しないと、家族全員が共倒れになってしまうような気もしますので、その辺についても、何か別の行政側として対応可能なことについて研究、検討していただければ大変ありがたいなと思います。ちょっと参考までに教えていただけますか。","respondent":"吉田品川区保健所保健サービス課長","answer":"脊柱側わんについてお答えしますが、先天性の筋疾患の場合、寝たきりということで、脊柱が変形してくるということが多くあります。","voiceIndex":145,"id":"exchange-070"},{"speaker":"堺委員","kind":"質問","question":"今、教えていただいた脊柱側わんの予防というんですか、それは、現段階で何か方法があるんですか。","respondent":"吉田品川区保健所保健サービス課長","answer":"ですので、年齢が進むにつれて側わんは進みます。ただ、なるべく進まないようにということで、理学療法等をしたほうがよろしいですし、必要な時期に正しい車いすを使っていただく、車いすのタイプを変えていただくとかいうことが必要になってまいります。","voiceIndex":147,"id":"exchange-071"},{"speaker":"堺委員","kind":"質問・要望","question":"今日の請願の本来のテーマではありませんので、この辺について、あまりしつこくやるつもりはありませんが、要請させていただきたいんですが、たまたま１８日の新聞に出ていたんです。この脊柱側わんについて、大阪市では、小学校５年生と中学校１年生の女性を対象に、体の凹凸を映し出すモアレ写真というんですか、それによる脊柱側わん症の検査を始めたそうですね。","respondent":"吉田品川区保健所保健サービス課長","answer":"この請願にあります脊柱側わんに関しましては、病気に伴うもので非常に激しい側わんが出てまいります。","voiceIndex":149,"id":"exchange-072"},{"speaker":"堺委員","kind":"意見","question":"終わろうと思ったんですけれども、確かにそういう検査はやっているんです。だけれども、それでは見落としがあるということで、ここではモアレ写真による検査の導入を始めたということなので、参考にしてください。今、お答えはいりません。何かのときに、またそういったことも検討項目の中に加えていただいて、必要だと思う結論が出れば、そういう検査も導入していただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-073"},{"speaker":"鈴木（真）委員","kind":"意見","question":"昨年の第２回定例会、第３回定例会と請願が出て、今回、３回目だと思うんです。私ども自民党としては、気持ちもわかる部分はあるんですが、今までの質疑の理事者の答えの中でも、現在の区の状況で、この部分に対応し切れないということで、願意には沿いがたい、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":160,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"意見","question":"結論としては、趣旨採択でお願いしたいと思います。医療ショートステイとか、医療デイサービスとか、特に緊急時の対応が何らか必要ではないかなと思って、看護師のところはなかなか難しいのかもしれませんが、親にかわるサポートの要請とか、そういった意味で何か工夫ができないかというところで、趣旨を理解するということで、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-075"},{"speaker":"阿部委員","kind":"質問・要望","question":"その仕組みの上で、区が直接何かサービスを提供できないのであれば、例えば、先ほど、障害者福祉課長が言われた、同じような状況にある方同士のネットワークで助け合うというやり方なら可能であるならば、そのようなネットワークづくりを支援するとか、何か考えていって、少しでも状況を改善するような方向というのは、引き続き探っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"請願趣旨にありますところを何点か、ちょっと実態をお伺いしたいんです。３行目の介護報酬の削減によるパート派遣労働者の増大というところでは、介護報酬の削減の実態と、派遣労働者の拡大というあたりを、品川区内において把握をされているかどうか。それから、離職率は上がり人材不足とあるんですが、区内の離職率についても、どう把握されているか教えてください。","respondent":"冨岡高齢福祉課長","answer":"介護報酬ですが、介護保険施設は平成１８年で４％の減となっております。それから、区内の派遣労働については、正確なところは、数値では把握しておりませんが、大体２割ぐらいであるかなと考えているところです。","voiceIndex":170,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"確認","question":"今、離職率が１２％ということだったんですが、全国で見ると、５人に１人、２０％ちょっと超えるぐらいの離職率なんですが、品川区はそんなにないということで確認していいのでしょうか。ちょっとその辺。それから、パート派遣の割合が２割ということだったんですが、２割ぐらいにとどまっているんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"区内の数値につきましては、たしか全体の数値は特別養護老人ホームで調べたものです。それで１２％という数値です。それから、パートにつきましては、正確な数値ではありませんが、押しなべて２割ぐらいであろうと理解しております。","voiceIndex":172,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"意見","question":"介護報酬の引き下げが、どういう影響を及ぼしているか、把握していらっしゃるか。それから、給与面とかに。","respondent":"木下福祉高齢事業部長","answer":"厚生労働省が全国調査を行いますと、この辺はまだ、３％ぐらいの数値が出ていたかと思うんですけれども、それよりは低い状況にあるということで、そういう意味では、前回の見直しが、法人の事業運営には結構影響を与えているということは事実かと思います。","voiceIndex":174,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど、ここに書いてある基本給の７万５,８００円と、職能給と経験給を上乗せをすると１６万円ぐらいになるというご説明がありましたけれども、普通に考えると、基本給というのは、例えばボーナスとか、退職金とか、年金とか、いろいろなものに影響をしていくわけで、ここの場合、何か特別な給料立てだなと思うんですけれども、この辺はどういうふうに把握をされているのか、教えてください。","respondent":"冨岡高齢福祉課長","answer":"本俸と同じく、職能給といいましても、それぞれスタッフになって、主任になったりすると上がっていくというようなことで、何年かほかの施設を経験して入った方は、同じ給料ではなくて、やっぱり７割とか、８割とか見ていくという形で、経験給というのを合算して。","voiceIndex":176,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問","question":"経験給も入って基本給という考え方ですか、今のは。そこが一つ。それから、請願項目の１なんですが、国会で出されたと言います、福祉人材確保指針が５項目あったということなんですけれども、特に給与のところと、職員配置のところで、どう評価して、どう受けとめていらっしゃるのか。これを生かしてほしいという請願なんですが、区として、どういうふうにこの辺を評価されているのか、お聞かせください。","respondent":"冨岡高齢福祉課長","answer":"先ほどのは、基本給の中に本俸と職能給、それから、ほかの施設で例えば１０年働いていれば、何号俸か加算するという形で、それを調整給と言っているそうですが、そういうものが含まれているという話です。","voiceIndex":178,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと品川区の状況がなかなか見えないんですけれども、国のところにおいて、国会で、共産党の高橋衆議院議員が厚生労働大臣に質問しているところで、「希望に燃えて介護、福祉の現場に入った青年たちが早くやめていくのはなぜでしょうか、どう改善を図っていくのですか」ということと、この福祉人材確保指針の実効ある対策を政府に要求したわけですけれども、このときに、舛添厚生労働大臣が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"この中で、人材不足のために長時間労働が進んで、精神疾患や病気により休職者が増加していることが深刻な問題になっているとあるんですけれども、先ほどの基本的な指針の中に、労働環境整備の推進等で、労働環境の改善で、３番目に労働時間とあるんですけれども、週４０時間労働制が適用されていない小規模な事業所における週４０時間労働制の導入、完全週休２日制の普及など云々ということで。","respondent":"冨岡高齢福祉課長","answer":"法令遵守でやっていただいておりますので、そのところはないと把握をしています。","voiceIndex":182,"id":"exchange-083"},{"speaker":"浅野委員","kind":"質問","question":"私も自分自身で実態を調べていないので、今の言葉を信じたいなと思います。それとも、今回の請願と同じように、都とか国とかしていくものなのか、そこら辺の区別というんでしょうか。今回、こういう形で請願が出ていますけれども、そのほかの項目については、どのような関係になっているのかということを、細かいと、私も聞き取れませんので、概略を教えていただければと思います。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では、区ができるところと、介護報酬の見直しでやるべきところなどが、それぞれ分かれておりまして、区でできることについては、今後とも適切に進めていきたいと考えているところであります。","voiceIndex":184,"id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"先日の本会議の質問の中でも、少し申し上げましたけれども、やはり介護労働の方々の報酬、特に前回の改正以来、大変厳しいものになっていると考えています。そういう意味では、ここに同感するところもあります。その辺、どうなんでしょう。多分区も、あの事件以来、いろいろと制度を整えたり、書類を増やしたりということがあったかと思うんですけれども、今はどういう状況なんでしょう。どうなんでしょうか。","respondent":"木下福祉高齢事業部長","answer":"きちんとケアプラン等で必要性が示されていれば、説明できれば、うちはオーケーとしているわけですけれども、やはり事業所とすれば、それで説明できないときに、お金を返せというような形が、現実にコムスンを契機にあったわけでありまして、そういう点では。","voiceIndex":186,"id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"福祉高齢事業部長からも、今、ちょっとお話が出たので、つけ加えますけれども、やっぱり、在宅に行くと、それこそ処遇困難家庭みたいな、同じ１時間、２時間働くのでも、大変なところというのはあると思います。ちょっとその仕組みについて、もし何かあれば教えてください。","respondent":"冨岡高齢福祉課長","answer":"高齢者で困難なケースがありますと、在宅介護支援センターを中心に地区ケア会議というのを開きまして、職員も入りまして、さまざまな専門家にもきていただいて、その方たちがどういうふうに対応していったらいいのかという形で連携をとりながら。","voiceIndex":188,"id":"exchange-086"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど、意見を言われたので、意見の前に先に確認なんですけれども、今回の請願が出されたのは、東京介護福祉労働組合ということなんですけれども、紹介議員とかあったら、会派の方にお聞きしようと思ったんですけれども、これは個人ではなくて組合として出している請願ということで考えてよろしいわけですね。どのぐらいの組織というか、どういう内容なのか、教えてもらえればと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-087"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう１点、この請願自体全体的な流れの中で、本会議の質問であった部分で、福祉高齢事業部長がご答弁なさっていたと思うんですけれども、先ほど、都からの緊急提言が出されたというようなお答えがあったと思うんですが、その辺、さっき高齢福祉課長の説明があったということで、同じ答えということで考えてよろしいわけですか。その辺、もう一度、ちょっと教えていただければと思います。","respondent":"木下福祉高齢事業部長","answer":"今、委員がお話しされたとおりで、かなり幅広い提言をしております。区が今まで言っていたことも入っていますので、そういう点では、必要な意見を国に言うという部分については、直近でされていると言うことができようかと思います。","voiceIndex":192,"id":"exchange-088"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、介護保険の関係の施設ですとか、事業所とかに、この間、経年的にずっとお伺いして、お話をお伺いしてきました。それも合わせると８.２％になるのかなと思うんですけれども、ちょっとそこの点を確認したい。この８.２％というのは１割に近いわけですから、これはほんとうに施設にとっても、事業所にとっても大変な状況があると思うんです。とりあえず、お願いします。","respondent":"冨岡高齢福祉課長","answer":"介護報酬の率の話ですけれども、制度発足以来は、８.０％という形でとらえております。経営実態については、先ほど申し上げましたように、把握しているということと、減収につきましては、ちょっと今手元に数字を持っておりません、申しわけございません。","voiceIndex":194,"id":"exchange-089"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"それは、全国市町村長会でも、ずっと提案を続けていると思うんですけれども、２０％が国の丸々負担、あとは５％は調整金となっていますけれども、それを、２５％は丸々国の負担にして、その調整金を足して、国の負担を３０％まで引き上げるということを、全国市町村長会で求めているそれこそが、この介護労働者の労働条件を改善するところで必要なんじゃないかと思うんですけれども。","respondent":"木下福祉高齢事業部長","answer":"それから３対１の部分について、これに手をつけるのは意外と難しいと思うんです。例えば２.５対１で基準をつくった場合には、場合によっては、全国ベースで見ますと、減算対象になるところも出てくると思いますので、なかなか合意するのは難しいと思います。","voiceIndex":196,"id":"exchange-090"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"こういうところで、こういうふうな状況になっていると思うんです。それからもう一つお聞かせいただきたいのが、特別養護老人ホームにお伺いしたときに、いろいろなところから言われたのが、区が指定管理者をしているところもありますけれども、社会福祉法人立というところもありますけれども、多くのところが、特別養護老人ホームの社会福祉法人から、さらに給食のところを委託をしていると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-091"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護の現場で働くというところで、あわせてちょっとお聞かせいただきたいというところで、お願いしているところです。よろしくお願いします。","respondent":"冨岡高齢福祉課長","answer":"ただ、具体的にどういう食材を使われて、それが問題があるものなのかどうかということについては、問題はないと考えていますが、冷凍食品なのか、今日の食事は何なのかまでは、申しわけありませんが、ちょっと把握いたしておりません。","voiceIndex":200,"id":"exchange-092"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現場から、ここのところが何とかならないかという声もたくさんいただいていますので、ぜひ、実態をつかんでいただいて、区としてできる対応も検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-093"},{"speaker":"堺委員","kind":"質問","question":"先ほど、福祉高齢事業部長のご答弁の中で、２０％、５％の質問があったときに、特別区長会としても要請しているけれども、実現しないんだという趣旨のお話でしたよね。これは、現状と見通しはどうなんですかね。","respondent":"冨岡高齢福祉課長","answer":"調整金の部分については、旧年来やっているということで、いまだに実現をしてないことを見ると、かなり困難な見通しかなとは認識しておりますけれども、あわせてまた、出し続けるです。","voiceIndex":203,"id":"exchange-094"},{"speaker":"堺委員","kind":"質問・要望","question":"かといって、また別の面から見ると、何でもかんでも国にやらせる、国から持ってくる、これも介護保険だけやっているわけじゃないから、いつだかできた後期高齢者の医療制度にしたって、国で５割、現役世代が４割、直接対象になる人が１割で、国から５割といっても負担増なんだというわけですから、どこまで行っても、際限なく、限りなく、反対する人は何だかんだ理由をつけて反対するわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは請願なので、委員同士でもやりとりを活発にやっていこうということが、委員会で確認をされていますので、今の堺委員の発言に対して、ちょっと一言言わせていただきたいと思います。介護保険制度は２０００年から出発したわけですけれども、それまでは、すべて税金で賄っていたわけです。それが、新たに５０％は介護保険料で賄うという制度になったわけです。そこに税金としても優先して入れていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"財源ということを言ったので、私は言っているわけですけれども、この介護保険をみんなで充実をさせて、安心できる仕組みをつくるということこそ必要であって、今のままだったら、老後が安心できないですよ、大変な状況になっちゃいますよ。そこのところを意見を言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-097"},{"speaker":"鈴木（真）委員","kind":"質問","question":"介護従事者、事業従事者、また団体の方からもいろいろお話を伺っておりますので、内容としては理解する部分があります。１番の部分に関しましても、先ほど、福祉高齢事業部長からもご答弁いただきましたし、高齢福祉課長からもありましたが、都からの緊急提言が国へ出されたという、その動向を見守っていきたいということで、今回、この請願に関しましては、不採択ということでいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-098"},{"speaker":"堺委員","kind":"意見","question":"先ほどもお願いしました、調整金の５％のアップについても、いろいろ困難はつきまとうかもしれませんが、ぜひひとつ努力を、引き続きお願いをしたいと思います。結論としては、この請願項目の２番目は、先ほど自民党もおっしゃっておられましたように、これについては、全く願意に沿いがたいということも踏まえまして、この請願書については賛成できない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成します。私たちは、大変に危機感を持っています。ほんとうに手遅れにしてはいけないといった意味で、せっかくこのような福祉人材確保指針というのができたんですから、ぜひ実行を求めるという意味では、できる限りの応援をしていくという意味では、ほんとうに今、大事な、タイムリーな請願であると思っていますので、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-100"},{"speaker":"阿部委員","kind":"質問・要望","question":"請願項目１番は、もういろいろな方からお話が出ましたけれども、今、ちょうどこの指針の実行をしようと、各機関いろいろ動いている最中だと認識しておりますので、つくってから放置しているとか、つくったけれども、だれも関心を持っていないということであれば、実行を求める意見書ということになるのかもしれないんですけれども、国は国レベルで、都は都レベルで、区は区レベルで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-101"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、後期高齢者医療制度の廃止や見直しを求める署名では６００万筆、国会に届けられたということとか、５８１もの自治体から廃止、見直し意見書などが届いている。それから、参議院では、６月６日に、廃止すべきであるという法案が可決をされたということでは、国民の民意が後期高齢者医療制度の廃止を求めていると受けとめています。中曽根元首相も、５月２５日の民放のテレビで、「名前が実に冷たい。","respondent":"永尾高齢事業課長","answer":"以上の経緯から、品川区では、後期高齢者医療制度について、運用上の改善は検討すべきでありますが、この制度自体は必要なものと判断いたしまして、廃止を求める意見書を政府に提出する考えはございません。","voiceIndex":227,"id":"exchange-102"},{"speaker":"飯沼委員","kind":"質問・要望","question":"しかし、人間は生れてから死ぬまで同じ命、同じ人間ですやん、７５歳で線を引くことは全くおかしい、根本的な部分が間違っています。制度を早く取りやめていただきたい」。医療のプロがこうおっしゃっているんですけれども、こういった声を聞いても、制度が必要というか、運用の改善って一体どのぐらいを考えていらっしゃるのか、その辺も含めて、お答えいただきたいと思います。","respondent":"永尾高齢事業課長","answer":"７５歳で区切るということですけれども、もともと後期高齢者医療制度は老人保健法の趣旨を連続させて発展的に継承しようという目的の制度ですので、そういう意味から、７５歳という区切りになっております。","voiceIndex":232,"id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問","question":"その高い負担にもかかわらず、中身は、先ほど読み上げたところにもありましたけれども、後期高齢者の診療料の組み立ての仕方からしても、明らかに、７４歳が７５歳になった途端に差別をされるというところでは、憲法第２５条の生存権とか、第１４条の法のもとでの平等というこれが、７４歳から７５歳にいった途端にこういう扱いをされてしまうということは、ほんとうにあってはならない。","respondent":"永尾高齢事業課長","answer":"どこかで区切るという意味では、７５歳で区切っているんですけれども、現実としては、医療費について、７５歳未満の方と、７５歳以上の方では約５倍ほどの差があるということ。","voiceIndex":234,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"どこかで線を引くって、先ほど、７４歳以下より７５歳以上が５倍の差とか、認定も６倍あるって、これは差があるから何なのかと。差があることをどう評価して、線を引くのかというところは、ちょっと難しい質問かもしれませんけれども、どうとらえたらいいんでしょう。","respondent":"木下福祉高齢事業部長","answer":"７５歳で区切るということの問題、一つは、老人保健制度のことは、高齢事業課長が申し上げましたけれども、もともと、これは突然出てきたわけじゃなくて、このアイデアというのは、もう十数年前からあったと思うんです。全国市長会とか町村会は、統一保険にしろと。","voiceIndex":236,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"７５歳の前と後では違って、統一をしてスケールメリットをそろえて追求していくということなんですが、７５歳以上を統一して一本化していくことで、７５歳以上の方が、今までより、よい医療がうけられるのか、どうなのか。その辺を、ぜひお伺いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そういうようなことも含めて考えていきますと、高齢者の身体状況に応じた新制度だというふうに考えるべきだと思います。そういう今後の在宅医療とか、福祉と医療の連携のためのいろいろな仕組みが準備されていると、私どもは考えているところです。","voiceIndex":238,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"私はとても安心できません。ちょっとここを読んでみたいと思いますけれども、朝日健二さんという方が書いているんですが、「後期高齢者医療制度診療料、月１回６００点、１点１０円は、医学管理等検査、画像診断、処置を包括した点数です。でも、制度自体がどうなっているのかと見たときに、これはほんとうにお医者さんたちが否定をするのは当然であると思うんですが、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"高齢者診療料の件ですけれども、一つのお医者さんのみにかからなければいけないというような規定はございません。選択できますので、ご本人の意思により追加の診療も受けることは可能です。","voiceIndex":240,"id":"exchange-107"},{"speaker":"阿部委員","kind":"質問","question":"年齢で切れば、そういう解釈もできるでしょうけれども、それよりも、その年齢になったからというより、やはり終末期の直前の部分に、いきなり大きなお金がかかるという部分、それはやっぱり７５歳以降で亡くなる方が多いからお金がかかるわけで、個別に見れば、やっぱり７５歳よりもっと若い方だって、終末に近い方は大きなお金がかかっているわけですから、それは統計上のマジックみたいなところもある。","respondent":"木下福祉高齢事業部長","answer":"保険料を決めるときに、基本的に個人単位なんですけれども、保険料段階４以上になると、急に世帯概念が入ってきたり。この背景というのは、多分、いわゆる世帯連体責任的な部分があるんだと思います。","voiceIndex":242,"id":"exchange-108"},{"speaker":"阿部委員","kind":"質問","question":"そういった意味では、課題意識を持ちながらも、そこはとりあえず本質ではないというのが、区のお考えかと、今、伺いました。私は、ここは多分に本質的なもので、もちろん介護保険のほうも制度設計上の大きな問題がたくさんあると考えています。もろちん日本は法治国家ですから、国会で一たん通ってしまった以上、とりあえず、品川区として粛々とそれに対応していくというのは理解できます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-109"},{"speaker":"浅野委員","kind":"質問・要望","question":"老人保健制度が続いた場合、品川区の国民健康保険に影響が出るというふうに考えられるんですけれども、まだ品川区は財政はいいのかもしれないんですけれども、将来的にどういうことが危惧されていくのかということを、１点お伺いしたい。","respondent":"永尾高齢事業課長","answer":"そういう今後の高齢者の増と、医療費の増を考えると、老人保険制度に戻すというのは、かなり厳しいと考えております。","voiceIndex":245,"id":"exchange-110"},{"speaker":"浅野委員","kind":"質問","question":"こちらのほうも、医療保険者にそういう責任を課すような形で、少しでも予防に努めて、病気になりにくい、また生活習慣病に陥らないような形で、ある意味では、健康で生活できるようにしていくという効果があるかと思うんですけれども、こちらの効果の予測というのは難しいかと思うんですけれども、やはりいい意味での医療費削減に効果があるものなのか、どうか、見解を教えていただければと思います。","respondent":"永尾高齢事業課長","answer":"最初に、ご説明申し上げました老人医療費が１１.１兆円から３０兆円になるということですけれども、これは今の状態が続いた場合に、３０兆円になるという推計です。したがいまして、特定健診等で予防医療に努めることによって、医療費を削減することは可能ではないかと思います。","voiceIndex":247,"id":"exchange-111"},{"speaker":"阿部委員","kind":"質問・要望","question":"すみません、ちょっとメタボリックの話が出たものですから。やせている方のほうが、どちらかというと先が細いというような傾向にあるとか。多分、この傾向も、何年かしたら揺り戻しが来るだろうなということを考えると、あまりそこにお金をつぎ込むのもどうかなと、個人的には考えています。あえてコメントは求めません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-112"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"後期高齢者医療制度が、安心して医療を受けられるための国民皆保険制度を維持するためだということなんですけれども、そういうところで、区としては医療費を抑制するということが必要だと考えているのか。先ほど、高齢福祉事業部長は、後期高齢者医療制度でよくなりますと言われていましたけれども、後期高齢者医療制度で抑制するという中身はどういうものなのか、教えてください。","respondent":"永尾高齢事業課長","answer":"医療費を減らすということなんですけれども、中身としましては、むだな医療をなくすということで、適正化です。","voiceIndex":250,"id":"exchange-113"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その無駄というのが、どういう中身なのかということを聞かせていただきたい。医療費を、総額として減らすことが必要と考えているということで、いいんでしょうか。","respondent":"永尾高齢事業課長","answer":"医療費の総額を減らすという方針ですけれども、結果的に減らすということで、お医者さんにかからないで我慢するとか、そういう意味ではなく、健康でいられた上で、医療費自体を減らすという考え方です。","voiceIndex":252,"id":"exchange-114"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど部長が言われたように、７５歳以上の方に、７５歳で病気がたくさんあるんですから、ほんとうに充実をさせますよという制度であれば、こんな怒りにならないと思うんですよ。そういうところが怒りになっているというところに対してどう考えているかということを、一つ、区のほうからもお聞かせいただきたいと思うんです。そこのところについては、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"当初の目的としましては、普通徴収でお支払いするということになりますと、徴収の人件費等いろいろ経費がかかってきまして、それが保険料のほうに逆に響いてしまうということでしたけれども、実際に制度が始まって以来、皆様のご意見を聞いて、政府のほうでも、今。","voiceIndex":254,"id":"exchange-115"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"なぜ、こういう状況になっているのかということは、一つは、多分これは１９８４年だったかと思うんですけれども、国の負担割合を引き下げましたよね。ここのところからほんとうに大変になっているということで、やっぱり、先ほどの国の税金をどう使うかということにも関連してきますけれども、国が医療費にしっかりとお金をかけるというのが、今、ほんとうに必要なんじゃないかと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-116"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"後期高齢者医療制度が、そういうふうな方向に行くんじゃないかと思うんですけれども、そこの点に関してはいかがでしょうか。","respondent":"永尾高齢事業課長","answer":"かなり大きい問題で、後期高齢者医療制度以外の社会保障全般の問題かと考えています。政府のほうでもプロジェクトチーム等をつくって、その辺の議論を、今進めているところですので、それを待って対応していきたいと考えております。","voiceIndex":258,"id":"exchange-117"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからもう一つ最後にお伺いしたいのが、健診の問題なんですけれども、後期高齢者医療制度が健診を義務から外したということで、この間、品川区のピンクの高齢者実態アンケート調査のまとめがありましたよね。あの中で、健康をどういうふうにして守っていくのかというところで、高齢者の７５歳以上の方も健康診査というのをトップに挙げている人が、たしか四十何パーセントいたような感じがしているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-118"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めて、高血圧や高脂血症、糖尿病という方に健診を受けさせないという制度に、これからなっていくと思うんですけれども、ここのところでは、ぜひ、引き続き全員が受けられるという制度にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":262,"id":"exchange-119"},{"speaker":"堺委員","kind":"意見","question":"本日、結論を出すという扱いでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":267,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問","question":"「４月からの制度の施行状況等を踏まえ、市町村、広域連合等の意見も聞いて、実務にも配慮しつつ、精力的に議論を重ねた結果、制度の円滑な運営を図るため、高齢者の置かれている状況を十分に配慮し、きめ細やかな対応を行うべきとの結論を出している」という資料が、私どもの手元にきております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-121"},{"speaker":"堺委員","kind":"質問・要望","question":"結論から、この廃止を求める意見書につきましては、願意に沿いがたいということを申し上げておきたいと思います。ですから、その意見は意見で、一つの法案が出された以上、それが廃止とするなら、私個人的には、やっぱりそれにかわる対案を出すべきではなかったのかなという気もします。ですから、ここでも、廃止とおっしゃるならば、廃止した後、どういうふうにすべきだということが書いてありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問","question":"一つ質問がしたかったんですが、とても残念です。健康診断も、外来も、入院も終末期までも、あらゆる段階で、私たちは安上がりな差別医療が押しつけられると考えています。撤廃しかないし、もとの老人保健制度に戻しながら、国民の総意の中でよりよい方向を探していくべきであると思いますので、この請願については採択をし、賛成をし、応援していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-123"},{"speaker":"阿部委員","kind":"意見","question":"冒頭に言ったことと似ているんですけれども、結局、３０兆円と予想されるような膨大な医療費を、じゃあ、どうやって負担していくかという話だと思うんです。仕組みを変えただけでは、３０兆円なんて、結局、だれも負担し切れない、どんな制度だって負担し切れない。結局は、どう医療のむだを省いていくかということが本質的な議論になるべきだったと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-124"},{"speaker":"阿部委員","kind":"質問・要望","question":"次に請願項目なんですけれども、意見書を提出してくださいとありますが、意見書って全会一致でないと出ないということで、既に意見が分かれているところで、私がここで意見を言っても、結果を左右しないのは大変残念なところなんですが、しかし、請願要旨はともかく、この廃止を求める意見書を政府に提出するということ、これは今の状況では、議会から意見書が出るということはどうもなさそうではありますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":277,"id":"exchange-125"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般質問の中で、阿部議員と菊地議員から保育のところで質問があって、その中の待機児解消の問題でフォロー質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-126"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":95606,"voices":283}},{"id":"h20-20080623-8","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"建設委員会","time":"午前１０時０３分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"最初に報告があった西小山駅についてお聞きしたいんですけれども、ここは完全に区営の駐輪場をなくすということで、そもそも設置をした理由というのをお聞かせ願いたいと思います。","respondent":"諸石交通安全担当課長","answer":"それと、駅利用者の駐輪場という意味合いがありますので、これについては鉄道事業者がその責任において駐輪場を設置する必要があるということで、区のほうでは西小山駅につき、東急電鉄のほうへ駐輪場の設置を働きかけてきたわけですが、今回それが設置をされて。","voiceIndex":8,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"東急電鉄が鉄道利用者のために駐輪場を設置するというのは、それはわかります。現実に今東急電鉄が開設をして、月極などが始まっていますけれども、周辺の商店が並んでいる道路なんかを見ますと、まだまだ平日に、道路に自転車が、買い物客の方たちなのかどうかわかりませんけれども、置いてあったりしている。","respondent":"諸石交通安全担当課長","answer":"これを適正に管理すればよろしいではないかというお話なんですが、どれがきちんと必要があって止めている自転車なのか、あるいは捨てられている自転車なのか、なかなかこれを現場で判別することが難しいというのが実態です。","voiceIndex":10,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"特にあそこの場合、あの駅を中心にして狭い道路の中で商店が並んでいる地域ですから、区がきちんとした設定をし、管理をしていくということが、私は絶対に必要な話ではないかと思うんですね。先ほど、私が言ったわけではなくて、課長があふれていたから有料という話をしたんですよ。改めてもう一度お聞きします。","respondent":"岩田まちづくり事業部長","answer":"繰り返しになるかもしれませんけれども、６年前ですか、品川区は駅前駐輪場は原則有料化をするということで議会にもご説明し、ご承認を得たところです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"だから、私、やっぱり区が責任を持つ無料駐輪場というのは、一定規模絶対必要なものだというふうに考えていますから、それは別に西小山だけの話ではなくて、商店街、駅と離れた商店街にしてもそうですよね、そういうところでの対策というのは、私はとっていくべき話だろうなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"二つなんですけれども、東急電鉄が、鉄道事業者として駐輪場を設置するというのは大変望むところではないかと思うんですが、この８２９台の自転車等の定期利用と当日利用の内訳をちょっと教えていただきたいということと、あと西小山のほうの無料のところが廃止になって、その跡地はこれからどのようにされるのか、ちょっとその辺、教えてください。","respondent":"浜脇街路事業担当課長、諸石交通安全担当課長","answer":"２点目の跡地利用ですけれども、目黒線につながる駅前広場ということで、西小山の地域は昨年度、電線共同溝、地下の関係の工事を行いまして、間もなく平成２０年度の予算で舗装、植栽、それから屋根とか。失礼いたしました。８２９台とご説明申し上げましたのは、自転車の定期利用分でございまして、そのほか原付バイクの２０台、それから当日利用の２６台の分があるということで聞いております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"そうだとすると、今委員の発言にもあったんですが、交通機関を利用する方たちは定期利用ということでご利用されると思うんですけど、鉄道事業者は当日の利用についてはそういった近隣の人たちへの配慮はないという、この２６台というのはそのようにとれるんですが、そのことも含めて、品川区は区営を廃止することについてどういう働きかけをしたのか、あるいは協定。","respondent":"諸石交通安全担当課長、浜脇街路事業担当課長、岩田まちづくり事業部長","answer":"先ほど来から商店街等にお買い物に来られる方の自転車の利用のお話が出ておりますが。私のほうのこれまでの東急電鉄への指導といいますか協議の中でも、駅利用の方と商店街を利用されている方というのはあるだろうということがございまして。これはいわゆる使う方、お客様のほうの動向もやはりそういうふうにはどうもなっていないということですので、そこら辺はどうするかということは。","voiceIndex":18,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"それをそのやり方として５０台というのがよくわからないんですけど、区としてそこの５０台を定期に利用させてほしいとか、そういう働きかけというか、無料の６００台のところの商店とか近隣の人たちや利用していた方たちへの配慮というのは、もう少し考えていただいたほうがいいのではないかと思うんですけど、その辺のご意見はいかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"具体的にどれぐらいの需要があるかというのはよくわかりませんので、８００台の中で空きスペースがまだ大分あると思いますので、こういった中で商店街もみずから自分たちの自転車利用のお客様を囲い込むような当然お気持ちはあるでしょうし。","voiceIndex":22,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"区としては放置自転車対策を念頭に置いてされているので、こちらとしては駐輪場対策という考えでいますので、ちょっとかみ合わない部分があるかなというのはいつものところなんですけど、有料駐輪場のほうは４月８日から供用開始ですので、定期利用のところは結構はっきりしているのではないかと思うんですけど、実績というのは把握されていますでしょうか。","respondent":"諸石交通安全担当課長","answer":"現在までの駐輪実績について、西小山駅のほうについては数字を持っておりません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"ここの資料として、今こっちを廃止するという根拠になると思うので、先ほど埋まっていなかったら５０台を当日にもしていいと聞いているというところで、ここはちょっと根拠を示していただきたいなと思うんです。定期利用のほうで結構ですけれども。","respondent":"浜脇街路事業担当課長","answer":"これは東急電鉄からの情報ですが、６月１８日時点のものですが、４３０台ぐらいが月極というふうに聞いています。","voiceIndex":26,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"当日利用が結構利用させていただいているという、今のは４３０台が定期利用で、全体で５８５台ということで、その差が当日利用として利用されているという理解でよろしいんですか。","respondent":"浜脇街路事業担当課長","answer":"申しわけございません。一般は、８５台というふうに聞いております。ですから、月極が４３０台、それから一般が８５台、それ以外にもオートバイとか、駅ビルのほうの部分もあるんですが、それらを入れて５８５台ですので、よろしくお願いします。","voiceIndex":28,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"これからここのエリアがどういうふうに、住民の方たちとかが、人口動向が変化していくかわからないんですけど、そういうことであれば、現在も先ほどだと最大で７６台は確保してもいいよというお話でしたけども、既に８５台という一般当日利用の方がいらっしゃるということでいえば、もう少し、埋まったら排除されてしまうわけですから、その辺は少し協議をしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"なぜかというと、ほかの大崎駅東口と、大崎駅西口のほうの自転車等駐車場は、当日利用に約半数確保されている中、新しく移設した大崎駅西口第２自転車等駐車場は、いわゆる月極だと思うんですが、月極というか定期利用ということなんですが、これにした理由というのがありましたら教えていただきたいと思います。","respondent":"諸石交通安全担当課長","answer":"なぜこれを定期利用にしているかというご質問についてでありますが、バイクの場合は通勤、最寄りの駅ということでお使いになる方もいらっしゃると思いますが、そのほかに近くのオフィスビル等に通勤で直接使っている方もいらっしゃるということで、当日利用にするよりも。","voiceIndex":31,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"まだ２カ月ということで７０％台ということなので、今後ある程度の数字が出た中でぜひともそういった思いをくんでいただきながら、定期利用のみならず当日利用も考えていただければなと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"こういうような基準的なものというのは、どういうふうに整合性というのは考えていらっしゃるんでしょうか。武蔵小山は先ほど見ませんでしたけれども、奥のほうには有料駐輪場があって、そこは１日時間貸しで１００円なんですよね、ワンコインパーキングで。目黒区側というのは、そうではないわけです。その中で、どういうふうに取り組んでいくかと。とりあえずちょっとお伺いしておきたい。","respondent":"諸石交通安全担当課長、岩田まちづくり事業部長","answer":"２点目の品川区と目黒区の駐輪場設置についての協力の体制ですが、現在武蔵小山駅の、これも同じく東急電鉄のほうで有料の駐輪場を設置するということで、今品川区のほうでも働きかけておりまして。補足ですけれども、先ほど西小山につきましては、今日の資料の赤いところですけれども、自転車の収容台数８２９台、原付２０台というふうにご説明しましたけれども、今年の夏ごろ。","voiceIndex":34,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういう点について、今日の条例案の中ではありませんけれども、一つ一つやっぱりそういう駅前広場を整備するに当たっての駐輪対策ということについては、この条例でいく以上は、どこの地域であったって、そういうようなことが準備としてきちっとしたことをされていかないと、おかしな話になってしまうということになりかねないわけですから。","respondent":"浜脇街路事業担当課長","answer":"当然今委員がおっしゃったとおり、駅前広場に９月ごろ着手したいものですから、それまでには今無料になっていますものを何とかそちらの新しいほうへということで、今やってありますが、とりあえず東急とすれば、暫定的な駐輪場をつくって。","voiceIndex":37,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"部長がお話しされた南側に１２０台分というのは、これは東急電鉄が設置をするということで解釈していいんですか。","respondent":"浜脇街路事業担当課長","answer":"それで、着手がおくれていますけれども、私どもとすれば、今の８２９台だけじゃなくて、早急に反対側のほうにもつくるようにと。残りが１２０台で合計１,０００台分ということで、今早急に着手するように言っているところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"第４８号議案に反対をします。ただ、生活の中で自転車そのものを活用されるという道がとざされていますし、駅前を中心にして商店そのものも変わっているわけですし、先ほどの部長の答弁だと商店街が望むのかどうかという問題よりも、やはり本当に早急に自転車対策を進めるのであれば、区が責任を持つべき部分が区営の駐輪場であろうというふうに思います。以上の理由で反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"でも、今まで品川区が駅前の放置対策ということでやっていた部分について、鉄道事業者についても先ほど要望しました近隣の方たちの当日利用というところは、今まで区が担ってきた部分を配慮すれば、当然そういった問題も要望できることではないかというふうに思いますので、ぜひ区民の利用の状況を把握した上で、積極的に働きかけていただきたいということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-018"},{"speaker":"石田（慎）委員","kind":"質問","question":"そういった方にいくらＰＲしても、なかなか、「いや、おれはまだ大丈夫だ」というようなことが非常に多くて事故につながってしまうのかなと。そんな中で、ＰＲの仕方なんですが、６５歳以上の区民の方を対象にするのか、それともご家族、そういったところまで幅を広げていかないと、なかなか自主返納に結びつかないのではないかなと思うんですが、その点はどのように区は考えていらっしゃるんでしょうか。","respondent":"諸石交通安全担当課長","answer":"９月１日から実施の予定にしておりますので、８月中には町会を対象にチラシ、回覧板を使ってお知らせをしたり、それから、リーフレットもつくりまして、地域センターあるいは区内の各警察署、消防署、そういった出先のところにお願いをして、できるだけ置かせていただいて。","voiceIndex":55,"id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひ、その方向で進めていただきたいと思います。例えばこういったさまざまな加盟企業がある中で、そういう若い人がこういったサービスを受けられる。そうすると、おじいちゃんを呼んで食事に行こうとか、このサービスをフル活用しようというような、そういったコミュニケーションに少しでもつながればなと思うので、ぜひ幅広い周知をしていただきたい。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"今回新聞でも報道になっているんですけれども、２３区初ということなんですが、全国的に見て、ほかの自治体での状況がどのようになっているか、ちょっとお知らせいただきたいと思います。","respondent":"諸石交通安全担当課長","answer":"当区で把握しております他の自治体での実施状況ですけれども、東京都内におきましては、あきる野市が６５歳以上の方を対象にコミュニティバスの無料のサービスを実施しているようであります。これはホームページで確認をしております。","voiceIndex":58,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"東京都も基本的に高齢者の免許返納の政策は推進しているんですけれども、ここで今あきる野市というお話がありましたけれども、２３区でほかの自治体では今回そういった話にはなっていないんですけれども、そこで品川区が特に高齢者のそういう事故が多くて、補正にかけるということなのか、返納が緊急に対応が必要だったという判断なのかどうか、そのところはどのような見解でしょうか。","respondent":"諸石交通安全担当課長","answer":"一方、高齢運転者による事故、これを見てみますと、平成１４年が５,７８３件、これは年々増加傾向にありまして、平成１９年になりますと７,０３６件ということで、これもまた大幅に増加をしているという現状にあるところから、この高齢運転者による交通事故防止。","voiceIndex":60,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"今の道路交通法改正で７５歳以上の方にもみじマークの表示が義務づけられたかと思うんですけれども、そういう中で、品川区が６５歳以上ということにしたということは、今の高齢者の事故というところでは、６５歳以上に限って言えばどうなのかというところの、６５歳以上が事故が多いというふうにしているのか、高齢者のトータルでその辺の推移のデータなんかをお持ちだったら示していただきたいんですけども。","respondent":"諸石交通安全担当課長","answer":"私が今高齢運転者の事故件数ということで報告しましたのは、６５歳以上の運転者の方の事故の件数ですので、今回支援制度の対象になります６５歳以上の運転者の方の事故については、品川区内においては増えておりますということで、ご報告をさせていただきました。","voiceIndex":62,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"改めてお伺いしますが、６５歳以上というふうにされた根拠が何なのかということと、もう一つは、エコライフ宣言をした方にこういった贈呈品をされるということで言えば、区民の方からもそういう意見をいただいているんですけれども、今まで免許を持たずに公共交通を利用してきた方のほうがエコライフには貢献していると。","respondent":"諸石交通安全担当課長","answer":"今回の支援制度の目的は、先ほどからお話をさせていただいているとおりでございまして、一つは高齢運転者の方による事故を防止していこう、これが一つでありますけれども、またそのほかに、ＣＯ２の排出削減、環境の保護ということでやらせていただいております。","voiceIndex":64,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"交通事故対策として高齢者の運転免許証の返納というのは必要なことだというふうに思っていますので、そういうことがあるのであれば、本来これは東京都、警視庁が予算をつけて進めるべきことだというふうに思うんです。ＰＲに関してですね、公として必要であると、啓発についての予算をそういった今ある既存の交通安全対策とか、そのような予算から流用することはできないものなんでしょうか。","respondent":"諸石交通安全担当課長","answer":"ただ、交通安全への取り組みというものが国は国レベルで、東京都は東京都レベルでということで、これはそれぞれ実施してきているところではありますけれども、品川区としてやはり交通事故防止、区民の皆様の安全安心につながりますので。","voiceIndex":66,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"今お話にありましたように、民間企業に協力をいただいて、この自主返納サポート協議会というところに３７団体が既に協力してこういう事業をされているというのを読みましたけれども、こういうふうに民間が既に進めていることに対して、行政が税金を、補正をかけてプレゼントするということの意義というか、それはどのように判断をされているんでしょうか。","respondent":"岩田まちづくり事業部長","answer":"したがって、当初予算では品川区の実施事業としてやる予定はなかったわけですけれども、やはり緊急の取り組みとしてこの事業を側面から推進していこうと、こういうことで区長が判断をしまして、補正予算でということになりました。","voiceIndex":68,"id":"exchange-026"},{"speaker":"三上委員","kind":"確認","question":"私どもはこの件に関しては積極的にやっていってもらいたいなという思いでおりますが、その中で、説明の中でも、もう少し運転免許証の返納という部分について、運転経歴証明書を持っているとこういう恩典がありますよとか、それから、公的機関にあっても、こういうことは有効に個人を確認できるものにもなっていますよとかという部分についても積極的にＰＲしていかないと、今部長がおっしゃったとおり。","respondent":"諸石交通安全担当課長","answer":"運転経歴証明書を持っていった場合の特典の関係ですけれども、都内におきましては、委員の皆様のお手元にある警視庁、東京都で立ち上げた民間企業のサポート制度のものがありますが、そのほかに全国的にも運転経歴証明書を持っていれば。","voiceIndex":70,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、それこそある意味で大きな事故を起こせば免許証取り上げということにもなる、そういうことを回避させるための一つの方法としても、これはやはり何らかの形でそれに代わるものということであれば、それは積極的に進めていっていただきたい。起きてから嘆くようなことではなくということで、ぜひしっかり取り組んでいっていただきたいなと私はお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"どうもこの数字を見ていると、６５歳以上の方の事故の件数が多いというふうに思えない。１８歳で通常は免許を取って、２０代、３０代、４０代、５０代と考えたときに、当然６０歳前であれば現役で車を運転することを仕事としている皆さんもいらっしゃるから単純ではないんでしょうけれども、それぞれの年代での事故件数というのはわかるんですか。","respondent":"諸石交通安全担当課長","answer":"ただ、６５歳以上の方が今委員のほうから特に総件数の中では多く感じないというような内容のお話がございましたけれども、当然交通安全対策は年齢にかかわらず幼児から高齢者の方まですべてを対象に事故を減らしていこうということでやっている対策でございまして、その中で。","voiceIndex":73,"id":"exchange-029"},{"speaker":"菊地委員","kind":"意見","question":"わかるんですけど、ただ、６５歳以上の方というのは、高齢化社会の中で年代的には増えていくのは当然で、免許証所持者も当然それにつれて増えていくわけですし、その中で実際に運転をすることがある方もいらっしゃるわけで、単純に今の話だけで、要するに６５歳以上の方の事故の比率がものすごく高いんだよというのはどうもちょっとその辺は納得しがたい部分があるんですけれど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-030"},{"speaker":"藤原副委員長","kind":"確認","question":"１点まず確認なんですが、品川区が２３区の中で、聞き間違いだったら申しわけないんですけど、品川区が初めてというか、やっている施策というお話だったと思うんですけれども、たぶん警視庁としては２３区全部に、品川区だけではないと思うんですけど、それはちょうど日程的に委員会とかが重なっていたと思うんですけれども。","respondent":"岩田まちづくり事業部長","answer":"そういう中で、何とか軌道に乗せたいということで、我々もこの返納制度の支援というのは全く考えていなかったわけではありませんので、警視庁と調整をした結果、きちっとした文書をいただけるのであれば、我々も側面から検討しましょうと。","voiceIndex":76,"id":"exchange-031"},{"speaker":"藤原副委員長","kind":"質問","question":"もっとストレートに返納した申請を持ってくれば何か特典をというならわかるんですけれども、エコにという形にしているというのが何か私の個人的な考えなんですけど、何かに結びつけないと通らないのではないかという思いがあったのではないかと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"いわゆる高齢者になれば、高齢者と言われるのを嫌うんですけれども、身体機能は明らかに弱くなっていくんですね。３年に１回、５年に１回の運転免許証の更新時期の身体チェックとか、それでは発見できないことが多いんです。","voiceIndex":78,"id":"exchange-032"},{"speaker":"藤原副委員長","kind":"質問","question":"最後にお伺いしますが、補正予算を組んでまでやるこの新規事業ですが、この事業というのは、自信があり、補正予算まで組んでやるすばらしい施策の一つなんですよね。","respondent":"岩田まちづくり事業部長","answer":"今回予算を出しています町会の回覧板とか、それからホームページ、各種団体を通じてのＰＲをよほど入念に徹底して行わないと、この２００名というのはかなりきつい高い目標ですけども、何とかきちっと行えるように努力をしてまいりたいと考えています。","voiceIndex":80,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問","question":"今の答弁で、２月に住民基本台帳カードは難しいということで、今回はエコライフの特典以外に住民基本台帳カードを希望者にはということなんですが、これは何かこういうものをセットにしないと現在でも住民基本台帳カードの発行は難しいということでしょうか。","respondent":"岩田まちづくり事業部長","answer":"要するに無料で住民基本台帳カードが発行されます。免許証の代わりに身分証明書が手に入ります。あわせて、ご希望があれば、５,０００円の品々をどれか１品プレゼントします。エコライフも一緒にこれからやっていきましょう、こういう３点セットで考えております。","voiceIndex":82,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"住民基本台帳カードと５,０００円ということは、１人当たり６,０００円相当ということでいいのかということと、あとこの中の万歩計、あとに職員が宅配とありますが、職員の方がわざわざお届けになるということなんでしょうか。なぜこういう状況なんでしょうか。","respondent":"諸石交通安全担当課長、岩田まちづくり事業部長","answer":"前段の住民基本台帳カードと特典の両方でというご質問のところですが、ご説明したとおり、住民基本台帳カードについては、身分証明書がなくなってしまうので、免許証がなくなるということで、身分証明書がなくなってしまうので。全員が希望されれば５,０００円の種々のプレゼントの物と１,０００円の住民基本台帳カード発行代をうちが全部見ましょうということです。","voiceIndex":84,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどすごく積極的にこれから進められる、補正予算をかけてでも進める政策だというお話でしたけれども、やはり公に税金の配分をしていくという意味では、もう少しバランスをしっかりと把握していただきたいなということで、この部分については見直しの検討を要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-036"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問","question":"平成２０年２月１９日、次のとおり和解および損害賠償額が決定し専決処分したと。今の時期ですよね。これは第１回定例会のときでも、専決処分というのは時期的に既に行われていたのではないかと思うんです。そこらあたりの処理の経過について、今日までおそくなってきた理由というのは、どうなんでしょうか。","respondent":"岩田まちづくり事業部長","answer":"日程的なものがちょっとはっきり今手元にないんですが、第１回定例会の議案案件の締め切りが当然これ以前だったと思われますので、したがって第１回定例会に間に合わず第２回定例会にずれ込んだというふうに私は理解しておりますので。","voiceIndex":99,"id":"exchange-037"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"菊地委員","kind":"確認","question":"７５０名からの方が署名を寄せておられる。これは実際に住民の中に起きている被害を全く考えていない今の説明になると思うんですけれども、実際に区としてもこの辺の被害について確認はしていないということなんですけれども、今お話の中で、実際にこういう被害、確認するつもりは区としてあるんですか。事業主のほうには指導していると言うんだけれども、区としてはどうなのか、それをお願いします。","respondent":"吉川住環境整備担当課長","answer":"私どものほうといたしましても、地域のほうに出かけて、いろいろな方にお話を伺ったりはしております。","voiceIndex":108,"id":"exchange-038"},{"speaker":"菊地委員","kind":"確認","question":"私ね、確認しているんですよ、自転車で転んだ方の話。そこはやはり区としてしっかりとらえるべきだろうなというふうに思うんですよね。だから、現実の被害に対する見方と、それから事業者に対する指導の仕方というのをもう一度見直すべきだと思いますし、その辺のところをどうやってとらえるかというのをちょっともう少しまた詳しくお話しを願えればなと思います。","respondent":"吉川住環境整備担当課長","answer":"何点かご質問があったかと思うんですが、まず、住民の方にわかりやすい説明をという点ですが、当然わかりやすい説明をするように行っていますが、風の調査の資料というのはかなり専門的、学術的なもので、おそらくそのまま出すと逆に非常にわかりづらいものになるということで。","voiceIndex":110,"id":"exchange-039"},{"speaker":"菊地委員","kind":"質問","question":"実際にビル風被害というのは定義されていますよね。剥離流だの、吹き降ろしだの、逆流だのといろんな形で定義をされていて、実際に吹き降ろした風や剥離流が合体すると風速どれぐらいの強さになっていくか、その辺もある程度定義をされているわけですよね。同じことが起こっているのではないでしょうか。そこをもう少し。","respondent":"齋藤住宅課長","answer":"そういうことで、前向きに今後風圧比、風速比については調べる方向で社内で検討する、そういう話もしておりましたし、ちょっとこれはやや言い過ぎになるかもしれませんけれども、今、担当課長より説明させていただいたように。","voiceIndex":112,"id":"exchange-040"},{"speaker":"菊地委員","kind":"質問・要望","question":"本来、建物が建つ前の１年間だったら１年間のその地域の風環境をきちんと調査して、建設中や建設後にそれも改めて調査をしていれば十分どういうものかというのがわかるわけですから、その辺の指導というのは、やっぱり今後もこういう建築物については私は必要なんだというふうに思いますし、まして、これだけの、ここで出されている被害、これだけのものが出されているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"今回、風速計とかそういう設置を求める指導をということだったので、それはぜひ進めていただきたいんですが、同じように青物横丁の駅のところだったんですが、いろいろな指導があったときに、地域の住民の方が風速計をつけていただくということで実現をしているんですが、そういう中では、その中に専門家の方とか地域の方にそういう詳しい方がいれば、そういう強力なこともできて。","respondent":"岩田まちづくり事業部長","answer":"一般的にここのビルはそうなんですけども、オフィスビルと違いまして、こういった共同住宅の場合、ベランダが大体出ておりますので、前にもご説明いたしましたが、風が至る方向から季節によって来るわけですけれども、風が直進方向に来た場合、高層建物にぶつかりますと。","voiceIndex":115,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"それはすごい広いエリアのところで、あるいは風に対して国の基準が設けられていなくて指導の限界だというお話があって、今のところできる一般的な行政の対応は限りなく進めているということだったんですけれども、そろそろそこを一歩品川区はいろいろな特別な先進的なことをしているので、一般化させるためのそういう品川区の地域性を考えれば。","respondent":"齋藤住宅課長","answer":"風のことですけれども、公害は八つあります。大気汚染、水質汚染、騒音、振動、ただ、風につきましては、公害という定義になかなかなじまないところがありまして、人力でもって支配したり、予測したりということがなかなか難しい。","voiceIndex":117,"id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"もう一点だけお願いします。さっき部長からも植栽の話がありましたよね。その前に課長がシミュレーションと同じになるには時間がかかりますよという話があったけれども、一体その範疇をどういうふうに見ればいいんですか。今されていた植栽が育ち上がる、それで、シミュレーションとほぼ同じになるとか、そういう時点まで一体どれぐらいかかるという話なのか。","respondent":"岩田まちづくり事業部長","answer":"ただ、ビル街においては、巻く風、直線的な風だけではなくて、巻く風が複合的に作用しますので、場合によっては局地的に悪さをするかもしれませんので、そういうのが出れば、事後植栽で対応するというのが今の技術的な部分での限界ですのでご理解をお願いします。","voiceIndex":119,"id":"exchange-044"},{"speaker":"三上委員","kind":"質問","question":"今いろいろな質疑を伺っていく中から受けとめさせていただいた話は、この請願項目については十分今行っている、今日までも行っている、話し合い等について指導するという部分についても行ってきている。継続していくと、こういうことは受けとめられるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-045"},{"speaker":"菊地委員","kind":"質問","question":"私はここで出されているように、質疑でも聞きましたけれども、実際の被害がこれだけ起きていて、今それぞれ区の答弁でもあったように、実際こういうことが起きているでしょうという中で、この住民の思いをきっちりとらえるべきだと思いますし、７５０名からの皆さんがこうした被害があるんだよということを認定しているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"しかし、住民の方々はまだまだもう少し頑張ってほしいという応援も込めて、あとやっぱり私は先ほど言いましたように、この請願も含めていろいろな高層の住宅が品川区、住宅だけではなくて、そういったビル被害というのが確実に増えていますので、ここのところは本当に区が地方分権で独自でもぜひ研究を進めていただきたいというふうに強く思いますので、そのことを要望しながら、この請願には賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-047"},{"speaker":"藤原副委員長","kind":"質問","question":"１点だけなんですけれども、井上議員の質問で、障害者の方の点字ブロックの質問があったと思うんですけれども、具体的に場所はどこなのかということと、それとその場所はなぜそのようになったのかということと、あといわゆる障害者の団体等の方がいらっしゃると思うんですが、その方たちのリクエスト等によってその場所が決められたのか、その３点についてまずお知らせをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-048"},{"speaker":"三上委員","kind":"意見","question":"そういう事実はわかりました。何か先ほど聞いて、昨年の事故でありながら、そしてまた決定してから、それこそ４カ月以上もたっている。それはやはりもう少し報告というのは早い時期にされていたほうがいいのではないか。専決は専決でいいでしょうけれども、そういうことです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":45871,"voices":144}},{"id":"h20-20080623-9","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"文教委員会","time":"午前１０時０３分～午後２時１７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第４９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"の第４９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"少しご説明いただきたいんですけれども、今ご説明があったところで、基準の政令の一部変更の施行に伴いということですけれども、政令が改正された理由というのがどんな理由なのか、ちょっと教えていただきたいのと、あと公務災害補償って、よく過去には実例がないと言われるんですけれども、実際どういうことを想定したものを指すものなのか、教えていただけますか。","respondent":"富田学務課長","answer":"この資料の改正理由の中にありますが、公立学校の学校医、学校歯科医等々の公務災害補償については、従前は都の条例でもって定めていたわけでありますけれども、平成１４年度より公務災害補償を市区町村が実施するということになった改正に伴いまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"改定は都立学校と同様にというのは必要なことなのかなと思うんですけれども、毎年この時期にこの条例が提案されるんですね。ちょっと疑問に思ったのが、ちょっとずつの差であっても、ずっと上がると大分変化があるのかなと思いまして、この間の経過を教えていただきたいなと思ったんです。例えば勤続２５年以上の方は何となくちょっとずつ上がっているのかなと。","respondent":"富田学務課長","answer":"平成１４年に区条例ができましたので、そのときとの比較ですけれども、学校医ならびに学校歯科医につきましては、５年未満の方、平成１４年には補償基礎額が６,７７４円でありましたが、これが今回の改正案では６,５８６円となっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"第５１号議案についてよろしいですか。給料表がありますので、わかりますけれども、今の説明の中でちょっと不思議だったところが、経験年数加算分というのがどういうふうに見ていくのか教えてください。例えば私立学校のほうのどこか行っていた先生が経験をしているという場合とか、民間会社のこういうのはゼロとか、いろいろありますよね。少し教えてください。","respondent":"河野指導課長","answer":"経験年数の加算につきましては、それぞれの経験によって場所が違いますが、勤務実績を考慮して、それに見合った俸給をその履歴等を参考にしながら、今後定めていくですので、それぞれちょっと細かい割合については、今、ご説明申し上げられませんが、加算されるです。","voiceIndex":21,"id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"わかりました。そうしますと、今決まっていないという点では、学校教職員経験とか、民間会社での経験とか、そういうものの細かい細則はなしということですか。","respondent":"河野指導課長","answer":"そういう細かい内容については、今後、規則、条例等でまた改めて定めていく予定です。","voiceIndex":23,"id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"冒頭の説明で、この第５０号議案と第５１号議案の提案の理由については、小中一貫教育を進めていきたい旨の説明がありましたけど、この条例自身は、いわゆる区が学校教育職員を採用するための条例だという理解でよいのかどうか、教えてください。","respondent":"河野指導課長","answer":"それに基づいて、品川区でも区独自の教員を採用するということで、委員ご指摘のとおり、区が採用するための条件ということで、条例を定めているものです。","voiceIndex":27,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が採用するための条例だというご説明でしたけれども、繰り返しにはなるかもしれませんけれども、その採用した教員について、品川区教育委員会はどういう教育の役割を担っていきたいと思っているのか、ここを一点教えていただきたいのと、あと初めての条例なので、ちょっと整理してご説明いただきたいと思っていたのは、教育委員会制度では。","respondent":"河野指導課長","answer":"なぜ区で独自に教員を採用しなければならないかですが、現在、品川区では小中一貫教育を全校展開していますが、どうしても県費負担教育職員の場合、その持ち時数との兼ね合いもございまして、学校間を異動して、小中連携、実際でも連携ということについては。","voiceIndex":29,"id":"exchange-006"},{"speaker":"中塚委員","kind":"提案","question":"私は、県費採用でない、加配の部分はしっかりこの３０人学級に充てるべきだと考えています。ちょっと伺いたかったのは、区長が提案した条例で教育内容、しかも小中一貫教育というふうに限定するというのは、区長の権限を超えていると思うんですね。繰り返しの話になるかもしれませんけど、その線引きの考えを教えていただけますか。","respondent":"河野指導課長、市川教育次長","answer":"それから学校のカリキュラムについては、当然当該の学校長が教育課程を編成するということで、権限を定められておりますので、カリキュラムの編成は学校ということになりますが、教育委員会といたしましては。その場では何のために、この条例が必要かということについては、先ほど指導課長が申し上げた、これからの教育委員会としての施策にとって必要だという教育委員の皆さんのお考えのもとで決定されたという背景がありますので。","voiceIndex":31,"id":"exchange-007"},{"speaker":"中塚委員","kind":"提案","question":"ちょっと具体的に第５１号議案の第２０条に超過勤務手当という項目がありますね。この超過勤務手当の項目を設けた理由をご説明いただきたいのと、だれに払うのか、何を想定しているのか、教えていただけますか。あわせて、この第３１条のほうの義務教育等教員特別手当も同じようにご提案の理由と、だれに何を想定しているものなのかご説明いただけますか。","respondent":"河野指導課長","answer":"第２０条の超過勤務手当ですが、現在、教職調整額が支給されている関係から、通常、教員に対して超過勤務手当が支給されるということはございません。","voiceIndex":34,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校の先生方にはいわゆる超過勤務手当はないけれども、学校外での活動があるから、こういう項目を設けているんだというご説明でよかったのでしょうか。もっと詳しく教えていただきたいと思ったんです。なぜ、超過勤務手当がないのか。逆に学校外というのはどういうことを想定しているのか。ここの条例には根拠的な法律もリンクされていないので、そこをご説明いただけますか。","respondent":"河野指導課長","answer":"教職調整額の件ですが、教育職員の職務と勤務態様の特殊性に基づいて、教育職員の勤務については勤務時間の内外を問わず、包括的に評価し、超過勤務手当および給与の制度は適用しないものとして、これにかえて給与相当の性格を有する給与として現在。","voiceIndex":36,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"ただ、命じることもできるという、超勤４項目という言い方をするんですか、それに当てはまるという考えでいいのか。つまり、これを素直に読むと残業代、残業代という言い方は変ですか、超過勤務手当が出るというふうに条例では読めるわけです。でも、いやいや、法律があるからこうなんだというのが、なぜ、超過勤務手当を設けたのか、そこを教えていただけますか。","respondent":"河野指導課長","answer":"教職調整額が設けられた折に、委員ご指摘のとおり、いわゆる超勤４項目ということで、学校長が教員に対して超過勤務を命ずることができる仕事の内容ということで、生徒の実習に関する業務、それから学校行事に関する業務、この学校行事というのは、宿泊を伴う行事、修学旅行とか。","voiceIndex":38,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"同じ説明になるのかなと思うんですけれども、第５０号議案のほうで、第８条にも超過勤務があるんですけれども、この第８条の教育委員会は公務のためやむを得ない場合というのが、先ほどの超勤４項目のことを指すのか、別の条例の形になるので、ここで言っている勤務時間の条例のほうの第８条の、ここで言っている「やむを得ない場合」というのは何を指すのか、確認だけさせてください。","respondent":"河野指導課長","answer":"勤務時間の条例のほうでうたっております「やむを得ない事情」というのは、先ほど申し上げたように、原則として、いわゆる超勤４項目に該当する場合です。","voiceIndex":40,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"ならば、この給与体系等々を含めて、まずメリットがあるようなほうが意欲というか、差別化ができるんじゃないかなと思うんですが、そういうお考えはないんでしょうか。","respondent":"河野指導課長","answer":"今、委員ご指摘のように品川区に今後、長く教員として、定年までかかわっていただける教員ですので、処遇面で優遇措置を講じるということも含めて、いろいろな角度から検討させていただきました。","voiceIndex":42,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"お考えはよくわかりました。今後、どういう動きになるのかなということはあるんですが、確かに現場の先生方は県費採用であろうが、区費採用であろうが、いろいろ頑張っているのはよくわかります。それで長く品川区にいて貢献していただくという仕組みを品川区でつくっていいんじゃないかなと私は思うんですけど、お考えはいかがでしょうか。","respondent":"河野指導課長","answer":"どちらかというと、今、県費負担教育職員を対象としたお話かと思います。私どもとしても、優秀な教員については、できる限り品川区外に異動することなく、１年でも２年でも長く品川区の学校に勤務していただきたいというのは、当然考えているところです。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"そういう意味では、品川区でやれるはずだと思うので、処遇の面、それから昇給の面もいろいろあると思いますので、今後、研究しながら、適切な評価ができるようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３０人ぐらいまでというお考えがあるとするならば、この３０人ぐらいは基本的には定数外ですよね。その定数外でも、品川区の財源で幾らかかるのかわからないですけれども、簡単に言えば３億円ぐらい人件費としてかかるのであれば、この３億円ぐらいは、常に定数外で考えるのか、その３億円の財源は東京都に求めたり、ほかの方向に求めることができるのか。","respondent":"河野指導課長","answer":"それから我々自身も、初めての採用選考になりますので、その採用選考そのものの制度といいますか、優秀な人材を見抜けるのかどうかということも含めて、今後のことも含めて十分検討しながら進めていくということも配慮して、必要最低限度の人数ということで、かなり絞った。","voiceIndex":50,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今はしようがない、定数外は独自で費用負担すればいいよというのはわかりますけれども、そういうものはトップでも何でも、今、トップをやっているのであれば、そういうところにもお金をつけて、ちゃんとそういう財源の手当てまで面倒を見てくれというぐらいのところは、しっかり訴えてほしいなと思いますので、これでちょっと緩むというか、もう定数外だから、あなた自由にやってよというので。","respondent":"若月教育長","answer":"そういったものの多々方面に目を配りながら、方向性としては先を常に見ながら、一つ一つの課題を解決して、区のほうに都も応分の負担をしつつ、区の人事権がこちらのほうに移るように努力してまいりたいと考えております。","voiceIndex":52,"id":"exchange-016"},{"speaker":"市川委員","kind":"質問","question":"先ほどの答弁の中で、優秀な人材の発掘ということで、区費教員とおっしゃったんですけど、採用の基準というのは、県費の教員の基準と区が独自で採用する時の基準と何か違いがあるのか、優秀な人材を発掘するので、当然、その辺の違いがあるのかなと思うんですけど、その辺はどうでしょうか。","respondent":"河野指導課長","answer":"これはどういう性格なのか、どういう職業に適しているのか。そういうことも含めた適正検査もあわせて採用選考の中で実施をしていくという方向で、現在、最終の調整を行っているところです。","voiceIndex":55,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校現場では先生が足りないというのが実態で、子どもたちにとっては、豊かな教育をつくるのは条件整備がまだまだ必要ですから、学校の先生はもっと増やすべきだと考えていますので、条例には賛成したいと思います。こういう問題点を指摘させていただきましたけれども、ぜひ豊かなすべての子どもたちの成長を保障する少人数学級のために充てるべきだと指摘はしておきます。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"}]},{"id":"topic-02","title":"の第４４号議案、平成２０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第４４号議案、平成２０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"文教委員になって浅いものですから、基本的なことがわかっていないんですが、この学校給食費の金額はどういう金額、どこで決められるのか、お恥ずかしいんですが、教えていただきたいです。それと今、就学援助費４,５４０人という対象、これは他の区に比べて多いんでしょうか、また少ないんでしょうか。その辺も比率というか、データがあれば教えていただければと思います。","respondent":"富田学務課長","answer":"私費会計でありますので、教育長決定ということで、決定しておりますが、決めるに当たっては各学校の給食運営の責任者であります、校長会にも十分な説明をした上で、決定をしているということになっております。","voiceIndex":70,"id":"exchange-019"},{"speaker":"山元委員","kind":"質問","question":"給食費を校長会で決めるということは、校長会で定めて、それをＰＴＡとかにお話をするというか、諮るということなんでしょうか。","respondent":"富田学務課長","answer":"給食費につきましては、教育委員会で統一して決めており、決めるに当たっては、校長会にも十分な説明をし、ご了解をいただいているということです。","voiceIndex":72,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"議題にそれたら指摘をしていただきたいですが、２１０円が２４０円という形になったわけですが、これ統一した金額ということですが、この食材の仕入れというのは、各学校によって仕入れをしていると思うんですね。増額するのは当然、これは問題ないと思っているんですけれども、今後、食材費の調達絡みのところでの不安がすごくあるんですが、現状はいかがでしょうか。","respondent":"富田学務課長","answer":"実はこの改定の金額を計算するに当たりましては、平成１９年度における金額でもって算出をしているところがあり、実際、現在も高騰をする、例えば小麦の政府売り渡し価格が１０月からまたアップする等々の報道の中では大変厳しい状況と思いますけれども、今１学期間。","voiceIndex":74,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"それから食材の質を落として安い物を買うというような現象になってくると、子どもたちの栄養なんかもありますので、やはりそれなりの物を提供するというようなものをつくっていただきたいと思いますし、そうなると、それなりに見合った金額というのはある程度納得するんじゃないかと思うんですが、そこら辺の兼ね合い、安いのは当然いいことは確かなんですけど。","respondent":"富田学務課長","answer":"一方、購入に当たっては、その時々で金額が変わるわけではなくて、何月まではこの金額で行きますよ。何月からはこの金額ですよといったことが業者からリストとして来るような場合が多いと聞いております。","voiceIndex":76,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"わかりました。ちょっとそこが気になったんですね。そうすると、それだけ高くなるわけで、そこのところをどういう決め方をしているのかなという、これは多分栄養士のほうがいろいろ考えていらっしゃると思うんですが、３０円よりもうちょっと高くても、いいものであれば保護者は納得するんじゃないですかというご意見を考えた形で設定とかはされないんでしょうか。","respondent":"富田学務課長","answer":"それは望ましい栄養摂取標準を１００％満たし、かつ価格の高騰をすべて見込んだとすれば、もっと上げ幅というのは大きくしなければ、当然のことながら倍では済まないぐらいの大きい金額を上げていかなければならないところでありますけれども。","voiceIndex":78,"id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"値上げについてやむを得ないと思う立場で質問をいたします。パンもそうですね。そういう窓口というのはどなたがおやりになっているか、伺いたいと思います。それから、もう１つは、栄養士部会というか、栄養士連絡会というか、そういうところにこの出席の問題ということで、どなたが月例的にお出になっているのか伺いたい。管理職の中で、栄養士連絡会等の指導はどの課長がされているのか伺いたい。","respondent":"富田学務課長","answer":"栄養職員会というのがございまして、こういったところでもって中学校、小学校ごとに一応毎月の統一献立というものは定め、それを参考にしながら、各学校の栄養士がメニュー変更しながら、毎日同じメニューを全校で食べているわけではありませんので。","voiceIndex":80,"id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"よくわかりました。それで、今のお米１つとれば、むしろ上がってはいないけど、下がってもいないようなご答弁のように思います。スーパー等でもいろいろな仕入れ先なんかでも、米の値段の急落というのは、非常に生産地を脅かすほどの勢いなんですよね。ですから、米の値下げ交渉というのはされた経緯はありますか。学校給食のお米の値段の値下げの交渉はされたことがあるのかどうか、伺います。","respondent":"富田学務課長","answer":"最近のことであれば、値下げという話は聞いておりません。","voiceIndex":82,"id":"exchange-025"},{"speaker":"中塚委員","kind":"提案","question":"教えていただきたいのが、これ、２学期からということで、それで１２８回ということなんでしょうか。１年間だと何回なのか、補正予算ですけど、これ、年間だとどういう規模になるのか、ちょっと教えてください。今回、補正という形で提案されているんですけれども、新年度予算でなかった理由というのが何かあるのか、教えていただけますか。","respondent":"富田学務課長","answer":"新年度予算でなかった、新年度で改定をしていないということについてでありますけれども、４月に向けての改定について検討しなかったというわけではありませんけれども、４月からということであれば、早い時期からの検討ということになってくるわけですけれども。","voiceIndex":85,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の改定の理由、先ほどから価格の高騰の説明があるんですけれども、一方で、栄養摂取標準の改訂というのが理解不足で申しわけないのですけど、よくわからないので、この改訂というのがどういう改訂なのか、いつなんですか。区として米の国庫補助の復活とか、あと小麦のほうもそうですけど、そういうふうに政府に対して補助のほうも求めていくという制度は行われてきたんでしょうか、教えてください。","respondent":"富田学務課長","answer":"栄養摂取標準の改訂についてでありますけれども、こちらは平成１６年度より東京都学校給食の栄養摂取標準が改訂をされていまして、児童生徒１人１回当たりの平均栄養所要量というものが若干改訂され、さらに学校給食の標準食品構成表という中での比較的単価の高い豆類。","voiceIndex":87,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"国庫補助のほうですけど、国の判断だという説明ですけど、その復活を求めるべきではないかということで質問したので、それについてご説明ください。この１食２０円、３０円、３５円の値上げというのはどういうふうに計算されたのか、材料分と標準分と、本当だったら、２倍ぐらい上げなきゃという話も先ほどあったので、もっとよくわからなくなってきたんですけど、ちょっとそこを教えていただけますか。","respondent":"富田学務課長","answer":"それと国庫補助についてですが、これにつきましてはさまざま給食が始まって以来、給食を普及するために国が導入してきた、そういった補助を要するにやめていく、そういったさまざまな経過の中でなされてきたものと考えております。","voiceIndex":89,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"それには理由があるわけですよね。これだけ区だって財政負担が伴うわけだから、なぜ財源の復活を求めないのか、ちょっと今の説明では質問の答えになっていないと思いますので、そこをちょっとご答弁ください。どうして、ほかの区の給食費の１食当たりの単価という言い方なんですか、その状況をちょっとお伺いしたいのと、何で高いのか、率直に疑問に思ったので、ご説明いただけますか。","respondent":"市川教育次長、富田学務課長","answer":"米の補助に関することで、品川区として言うべきことを言っていないんじゃないかというご質問の趣旨かと思うんですけれども、先ほど学務課長が申し上げましたように、平成１０年にこの補助が廃止された背景。ただ、他区の事情について、詳しく承知しているわけではありませんので、本区については本区の計算に基づき、必要な価格ぎりぎりのところで算定をしたという経緯になっています。","voiceIndex":91,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"その２０円から３５円の値上げで、時期的なものと、品川区の給食の特徴といいますか、説明でちょっとまだよくわからなかった部分もあります。そっちの家庭の負担の軽減、これが本来の補正では出ていない、考えていないということなんだけれども、なぜ考えなかったのか、そこは１点お伺いしたいと思います。","respondent":"富田学務課長","answer":"したがいまして、今回の改定につきましては、このようなやむを得ずの金額ということで改定をさせていただき、経済的理由のある方については就学援助での食材、給食費の負担ということで、基本の考え方としては。","voiceIndex":94,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明のままだと、これは６月１０日の教育委員会の資料ですけど、今後について、２年程度を定期的に物価動向を調査して、見直しを行うと宣言されていますね。国庫の補助は求めないわけですよね。これでいいのかなと思うんです。補正なのか、新年度の予算なのか、とにかくこの考えではどこまでも家計の負担が上がっていくという心配もするんですけれども、そこをどういうふうにお考えなんでしょうか。","respondent":"富田学務課長","answer":"わかりませんけれども、その時々の適正な価格というものを給食費の金額というものをもう少しタイムリーに算定をし、保護者の方にお示ししていく必要があるだろうと考えております。","voiceIndex":96,"id":"exchange-031"},{"speaker":"市川委員","kind":"質問","question":"この資料で見ると、小学校が３０円から３５円で、中学校が２０円値上げなんですけれども、たくさん食べるほうが値上げの幅が大きくて当たり前かなと思うんですが、この小学校より中学校のほうが低くなっているということの理由を伺いたいのと、それから、この値上げが決まったのは６月１０日の教育委員会で決定したと考えていいのか、そこのところを伺いたいです。","respondent":"富田学務課長","answer":"それと決定日についてですけれども、これは６月２日付で教育長決定をしております。５月の下旬、校長会に説明をし、ご了解をいただいた上で、教育委員会として教育長決定をしております。その内容につきまして、６月１０日の教育委員会でご報告を申し上げたということであります。","voiceIndex":98,"id":"exchange-032"},{"speaker":"市川委員","kind":"質問","question":"６月２日の教育長決定というのはどういう部分になるんですか。教育委員会で決まったということですか。教育長が決定をしたということですか。","respondent":"富田学務課長","answer":"すべて教育委員会での議決を経るということではなく、本件は私費会計である給食費の改定でありますので、教育長が決定をしたということであります。","voiceIndex":100,"id":"exchange-033"},{"speaker":"市川委員","kind":"質問","question":"今の説明でわかりました。それで、保護者に対しての説明というのは、２日に決定して、その間、何か保護者のほうには説明はしたんでしょうか。その辺を伺いたいです。","respondent":"富田学務課長","answer":"それを踏まえまして、教育長の決定を受け、教育委員会で報告を１０日にした後、先ほど申しましたように１１日に各保護者あてに改定のお知らせをしています。","voiceIndex":102,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ。それが９０％なのか。それで、あまりにそれがいろいろな議論になるなら、いろいろな政治判断もあるんだろうし、いろいろな判断もある中で、それだったら給食そのものは何だという議論に入っていくわけですから、この値上げの部分ではしっかりそれは、この中でも例えば３０円なり上げても、多分栄養士も学校側も必死になって、それでその中で、子どもたちにいい給食を出そうと思っていると思う。","respondent":"富田学務課長","answer":"いろいろ栄養標準の説明が複雑で申しわけないんですが、必要カロリーの９割ということではないのでありまして、エネルギーですとか、タンパク質、ナトリウム、カルシウム等々のこういった栄養量というのは満たしているのでありますが。","voiceIndex":104,"id":"exchange-035"},{"speaker":"山内副委員長","kind":"確認","question":"平成９年に１回ありまして、その翌年ですか、平成１０年にやはり微額ですけれども、値上げをされておりますけれども、先ほども申し上げましたように、先行き不透明な中、このような形で微額の値上げというものも今後の展開ではあり得るのかなと思っているんですが、その辺というものはやっぱり柔軟性を持って、今後も教育委員会も考えていくのかなと思うんですが、その辺の確認だけということでお願いします。","respondent":"富田学務課長","answer":"中には品川区のように１０年ぶりというところもあるわけですけれども、目安としては２年程度というふうに考えておりますけれども、物価の上昇の状況によりましては、そういった次年度もということもあるかないか、ちょっと今からは申し上げられないといいますか。","voiceIndex":106,"id":"exchange-036"},{"speaker":"山内副委員長","kind":"質問・要望","question":"子どもの栄養を一番に考えると、もう絶対にやむを得ないことだと思いますので、その辺は柔軟に考えていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、材料費の引き上げについてですけれども、学校現場で栄養士の苦労も聞いていますし、安全でおいしい給食、食育という観点からも、考えると材料費の高騰も事実ですから理解しますけれども、ちょっと先ほどの説明では、なぜ２０円、３０円、３５円のこの額がちょっとまだよくわからなかったので、そこは疑問を指摘しておきたいと思います。補正には賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-038"},{"speaker":"市川委員","kind":"質問・要望","question":"補正に対しては、就学援助の補助ということなので、これに対しては賛成をします。要望としては、７月にお知らせが保護者のほうに行くというところでは、少し丁寧な説明をして、学校がした努力というようなことはしっかり盛り込んで、誤解を与えないような説明をつけてお知らせをしていただきたいということを前提として賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-039"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この請願、つまり食材費の値上げをなぜ保護者に求めるのかというところがポイントなのかなと思うんですね。今回の値上げの理由は、先ほど補正のときにご説明がありましたけど、材料の高騰と、栄養標準の改訂ということですが、主には材料の高騰だろうと思っているんです。なぜ品川区はこうした検討を行わないのか。家庭の今の経済状況をどんなふうに見るのか、そこを教えていただけますか。","respondent":"富田学務課長","answer":"したがいまして、お子さんが食するその食材費の部分は保護者の方にご負担いただくのがその基本だろうと思います。補助をしている区が数区あるということは承知しておりますけれども、その区にはその区それぞれの判断があり、行っているものと考えております。","voiceIndex":120,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"１つ、数字的に聞きたいのは、今回の改定は２学期以降ということですけれども、保護者の負担というのは、トータルではお幾らぐらいになるのか、試算があると思うので、その金額を教えてください。なぜ公費で補てんしちゃいけないのか、もう少し詳しく教えてください。品川区は何でこういう保護者負担の回避を……。教育委員会はなぜそういう回避を検討しようとしないのか、ご説明ください。","respondent":"富田学務課長","answer":"給食費全体の９月に改定したうちの保護者の負担分のトータルは、１年間で約９億円ということになってまいります。","voiceIndex":122,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"品川区全体で９億円というのが、今回のこの２０円、３０円、３５円の値上げ分が幾らなのか。その値上げ分のところを品川区の小学校、中学校のトータルを教えていただけますか。","respondent":"富田学務課長","answer":"値上げ分のトータルは約６,１００万円です。","voiceIndex":124,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"６,０００万円という話ですよね。しかもこの考えだと、物価はどこまで上がるかわかりませんけど、最近アメリカの穀物がまたミシシッピ川のはんらんとか、オーストラリアの干ばつとか、いろいろな理由でどんどん上がっている中で、際限なく保護者へ負担を求める。それを保護者に求め続けると、際限もなくこの理屈では上がっていくことになるわけですよ。これでよいのかということを伺いたいんですね。","respondent":"市川教育次長","answer":"このことは果たして納税者である区民の皆様方の望むところかどうか。こういうことを考えての行政の判断だということで理解をしていただければと思います。","voiceIndex":126,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が全部かぶるのかと、それは１つあると思いますよ。だからこそ国にしっかり求める。今回、しかも６,０００万円ですよね。年度途中とかでの運用は改善すべき点があるのかと思うんです。私も詳しく知らないので、説明をいただきたいのは、所得制限が厳しいという話、どれぐらいの所得制限なのか、そこのところがわからない点なので、多子家庭のほうの所得制限、どういう範囲なのかご説明いただけますか。","respondent":"市川教育次長、富田学務課長","answer":"私から繰り返しになりますけど、この補助の考え方ということについては、金額の多寡で考えているわけじゃございません。多子家庭におきましては、該当する世帯、現在、特別区民税の所得割が、２１万６,７００円以下ということで、要綱を改正しておりまして、これが適用になりますことで、該当する世帯の方に直接郵送でご案内をし。","voiceIndex":128,"id":"exchange-044"},{"speaker":"中塚委員","kind":"確認","question":"就学援助のほうはわかりました。途中でもできると。多子家庭のほうは途中での申し込みはできないと聞いたので、ちょっとそこは私も確認していない。できるのであればできるで結構です。所得、経済的な負担はそこでやっているんだという説明ですから、苦しいところはね。所得制限の範囲、年収だとどのぐらいなんですか。今の説明ではよくわからないので、ご説明いただけますか。","respondent":"富田学務課長","answer":"所得が厳しいのではないかというご指摘ですけれども、対象を多子の方については困難であろうということで、昨年度改正をいたしまして、所得割の制限額を引き上げたところであります。","voiceIndex":131,"id":"exchange-045"},{"speaker":"中塚委員","kind":"意見","question":"最後にしますけれども、この食材費の高騰に連動した保護者負担の増、今のこの仕組みでは、本当に際限なく、どこかで何か手を入れなければ、今後の状況がどうなるか、もちろんわからないけれども、おそらく当分上がっていくということを今の仕組みで心配するわけですね。私はぜひ、「いや、上がった分は保護者負担にして当然なんだ」という姿勢を改めるべきところがあると指摘をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-046"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと給食の味が落ちたかな、なんて意見もあったんですが、それはそれといたしまして、ともあれ、１つお聞きしたいのは、そういうご父兄とか保護者の方から、今回、このプリントを配られてから、何か反応といいますか、ご意見といいますか、どうなのかなというのを教えていただきたいと思うのが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"給食費未納というのは、何かいろいろな委員会のところで確認をしてみて、あまり詳しいことはわからないという答弁もあったそうなんですけど、今、品川区において未納の割合はどのぐらいで、それによってどれだけ緊迫しているのか、緊迫していないのかという、その現状はどうですか。","respondent":"富田学務課長","answer":"未納の割合ですけれども、ちょっと小学校と中学校で若干違いまして、小学校が約０.１％、中学校が平均しますと、０.４％ということでございまして、一、二年ぐらい前ですか、大変未納の問題が新聞報道されまして、各区の状況等、新聞等にも掲載されましたけれども。","voiceIndex":138,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"ですから、未納者の考え方の中に、給食も食育を含めた学校教育の一環だろうというのがあるので、だから、それは公費で賄うべきではないかという考え方もあるわけですね。私たちは違うと思っていますけど、そういう考え方もあるし、今、食材費を実費払いしてもらいますよという考え方、これは品川区としてはどういうふうに考えているのかをお聞きしたいです。","respondent":"富田学務課長、若月教育長","answer":"ですので、未納の方々が出るということは、ほかのお子さんへの影響も出てまいりますので、今後、未納対策といいますか、司法手続も含めて、校長会等調整に入り、段取りをとっていくことになります。ちょっと補足をさせてください。時間のないところで申しわけありません。","voiceIndex":140,"id":"exchange-049"},{"speaker":"西本委員","kind":"意見","question":"説明、ありがとうあります。多分、さっき私が言ったような事例の考え方の人が、若干そういう考えがあって、公費ということを持ち出してくるのかなと思うわけですけれども、やはりそこのところは機会があったら、丁寧にご説明をして、意識を深めていただくということが今後必要かと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-050"},{"speaker":"市川委員","kind":"質問","question":"それで、こういった給食費に直接影響があるような問題が起きたときに、やはり努力として、調理の仕方で値上げをあまり負担のないような対策をとっているんだと、前回の文教委員会の中での答弁があったんですけれども、こういう場合に、民間委託になっている学校と、なっていない学校のそういう調理への指示というんですか、そういうものは何か違いというのがあるんでしょうか。その辺を教えてください。","respondent":"富田学務課長","answer":"直営校と委託校、全く違いがございません。","voiceIndex":144,"id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出してください。理由を言います。それで、先ほど来、今、子どもを学校に行かせているから家計が大変だから、それを負担で、先ほど教育長からもお話があったように、基本的には食材のみを負担していただいているわけで、それを何でも上がったから、区に求めるというのは私は非常に本末転倒の議論だと思っています。じゃ、全部お弁当でつくってみたらどうですか。だから、基本的にこの請願は不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-052"},{"speaker":"山元委員","kind":"質問・要望","question":"結論を出していただきたいと思います。理由は先ほど、先走りましたが、同調できません。不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-053"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すべきです。採択すべきだと思います。近年のこの物価上昇、穀物価格の値上げ、それによって食材費が上がった分を保護者にゆだねるというのはやめるべきだと思います。ぜひ公費を投入して、それを回避する努力が必要ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-054"},{"speaker":"川西委員","kind":"質問","question":"結論を出すことに賛成です。請願は不採択です。理由を申し上げます。手づくりを学校給食だけに頼って、朝晩の食をコンビニ弁当で間に合わせるような、食育教育というのは私はこれから、学校給食を守りながら進めたいと思っている１人ですから、そういう点では食材費がこの金額では少ないぐらいで、先ほどご意見にも出ていましたように、栄養士の努力というのは本当に感謝しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"今日、結論を出していただきたいと思います。不採択です。苦情がないということ。そういうことだから、関心も持つだろうし、一緒に考えていきましょうという動機づけにもなりますので、全部負担してしまうと、それはかかわるということを閉じてしまうと思いますので、適正な金額で取り組みのほうもしていただきたいと思いますけれども、いい食材、いい給食をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-056"},{"speaker":"市川委員","kind":"質問・要望","question":"結論を出すべきだと思います。生活者ネットワークとしては採択です。食材は各家庭が負担するという原理原則はわかるんですけれども、やはり家庭が負担するにも限界というのがあると思います。それで家計の中でのすべての物が値上がりしていく中で、給食費もというところでは、この請願に書いてある理由というのがよくわかりますので、補助というところは検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"両方一緒ということなので、先に京陽小学校に限って伺いますけれども、今のお話ですと、来年度以降、２１年度以降に耐震化工事を行うというか、そういうことでよろしいのかということが１点と、きっと庶務課長もごらんになったと思うんですけれども、６月２１日の朝日新聞、ほかの新聞にもありますけれども、２３区全体の耐震化が出まして、さっきの話ですと、ここで言う、耐震化率ということですと。","respondent":"田村庶務課長","answer":"数の中でカウントしてごらんいただきますと、うちの場合には校舎改築ということで、この中に本来子どもの安全を考えれば、校舎改築が一番ベストの選択ですから、そういうことを盛り込んで、校舎改築すれば、新しい基準にならなければ５０年、６０年もつ形ですから。","voiceIndex":162,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"陳情は平成２１年に延期されたという書き方をしているんですけれども、まず京陽小学校に限って言うならば、平成２１年にやるという計画なのか。どうもこの平成２１年度以降の計画がよくわからないので、そこをご説明いただきたいと思っているんです。パーセントで言うならば、仮に全部やったとして、小学校で８２％ですけど、その残りは１８％あるんですか。","respondent":"田村庶務課長","answer":"それと、全体の数ですが、先ほど口頭でお話ししましたが、全体５４でカウントしていますので、残り、ここに書いていない学校は、今後平成２１年度以降に計画なり耐震補強工事で実施する学校です。","voiceIndex":164,"id":"exchange-059"},{"speaker":"中塚委員","kind":"確認","question":"私がカラーペンでチェックしたら、京陽小学校を含めて小学校で７校、まだいつどうするという計画が発表されていないんですね。京陽小学校に限っては、先ほどの話ですと、そうじゃないというふうにとっていいのか確認をしたいんだけど、品川区は公表していないという報道だったので、とりわけ倒壊の危険度がある０.３未満の学校というのは、まずあるんですか。そこを確認させてください。","respondent":"田村庶務課長","answer":"ですから、数値の公表をするとか、あるいは数値をむやみに出せば大丈夫かなというような話になるんですね。やはり法律の改正の内容も含めて、慎重にどうするか検討していかなければならないと考えております。","voiceIndex":166,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"確かにつくった時期によっていろいろあるのはわかりますけれども、診断の結果、０.３未満の学校、小学校も中学校も、建物で幼稚園はないのかな。地震はいつ来るかわからない。子どもの安全と同時に、学校自身は避難場所としての役割もあるわけですから、でも今のお話ですと、建て替えか、補強かということですから、統廃合とは全く別の議論ということでよろしいのでしょうか。","respondent":"田村庶務課長","answer":"それと先ほどから、０.３以下があるかないかというご質問ですけど、ここでご答弁するのもやはり何校あります、あるいは何校ありませんという話が、先ほどの繰り返しになりますけれども、実質的に数字だけがひとり歩きして、文部科学省の言い方も危険性が高いとか、低いとか。","voiceIndex":168,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"この両方の陳情書の中の趣旨というのは、１３０周年記念行事があるために、延期になっているということだったと思うんですが、そういう話、先ほどご説明の中で、そもそも京陽小学校は平成２０年の計画にもなかったというお話なんですが、この違いというのはどこから来ているんですか。学校の事情のお話が聞ければと思うんですが。","respondent":"市川教育次長","answer":"ところが、実際には次年度の工事計画を立てるときには、どこの学校で耐震補強工事を実施しようというのは、前年の秋の予算編成のときからいろいろ取りかかるわけでございまして、そのときには当然、翌年のその学校の教育活動のさまざまな計画にも影響しますので。","voiceIndex":171,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"そうすると、何か勘違いされているのかなという感じだとは思うんですけれども、もう１つＰＴＡや保護者の方たちのとらえ方はどういうとらえ方をしているでしょうか。京陽小学校は平成２１年以降にいろいろ考えていくよという形なのか、どういうとらえ方をしていらっしゃるのか。","respondent":"市川教育次長","answer":"それで、平成２０年度の事業完了ということが、先ほど庶務課長のほうから申し上げたような事情で、平成２１年度以後に計画が延びましたと。しかしその一方で、耐震化の早期実現ということは念頭に置いていますということを、学校を通して説明をさせていただいています。","voiceIndex":173,"id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、委員長のご配慮で第６号からということだったんだけど、態度表明は両方一緒に合わせてします。陳情第６号も第１１号も結論を出すべきだと考えています。そういう意味から見てみると、この陳情項目については、非常に個人のお考えを行政側に、別に陳情権はあるわけですから、構わないと私は思っておりますけれども、その話を受け入れるということはできないと思っているので、不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-064"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり公明党としても不採択ということで、やはり生命の安全とかという思いはわかりますが、１つの学校のことにちょっと勘違いなさっているかなという思いもありますし、我が党も定例会で質問させていただいて、ご答弁で先ほどもありましたけれども、平成２１年度の早期完了を予定しているというご答弁をいただきましたので、そういう意味では不採択にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"両方とも結論を出すということで結構です。第６号のほうですけれども、私はこの趣旨は品川区全体の小学校、中学校の耐震補強を早く進めてほしいという趣旨は理解できますので、趣旨採択と。第１１号のほうは京陽小学校ということですけれども、それを早く耐震強化工事を実施してほしいという趣旨なので、どちらも趣旨採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-066"},{"speaker":"川西委員","kind":"質問","question":"結論を出すべきです。それから第６号、第１１号に対して、結論としては不採択です。しかし、今の説明を受けても、そのようにやらないというのではなくて、先送りということと、もう１つは比較的学校の中では、新しい学校に入るということがわかりますと、これは理解できるんじゃないでしょうか。もし直接お見えになるようなことがあったら、十分説明をしていただくということで、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"本日は両方とも結論を出したいと思います。第６号も第１１号も不採択でお願いします。しかし、品川区が平素から耐震ということについて配慮しているという事情等もありますので、それを十分理解していただいて、安全に過ごしていただくのは十分にやっていると思いますので、ご理解いただきたいと思いますので、結果、そういう形にいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"第６号、第１１号とも結果を出すということです。第６号、第１１号ともネットとしては不採択ということです。理由としては、請願の趣旨とか内容を読むと、そういうこともあるのかなと思ったんですけど、今、説明を聞いて、品川区の計画の中での耐震化の中には入っているということを伺いましたので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"先ほどの天窓があるのが五、六校あると聞きました。これ、新しくすべてつくったところですか。ということは、今後もそういう形が、光のあれがありますから、考えられていると思うんですが、安全対策は同じような体制という考えですか。","respondent":"田村庶務課長","answer":"今、西本委員ご指摘のとおり、新しい小中一貫校や改築校が天窓だとか、明かりとりなり、学校でこれ以外にございませんので、ですからやはり今後、新しく改築なりしていくときには、当然、この学校も、第二延山小学校もそうですけど、相当吹き抜けのところは塀を高くしたり。","voiceIndex":195,"id":"exchange-070"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは、先生もそういう指導をしっかり受けているかというのが１つ。それから、鍵というものは、例えば台場小学校だって、上には農園があったり、菜園があったり、そういう授業があって、それは必ず屋上に上がるわけだから、鍵という問題ではなくて、上がっても、そこには入っちゃだめだよという教育は、子どもたちにも何度もやるべきだと思うんですね。","respondent":"河野指導課長","answer":"したがいまして、今回の事故は我々も十分教訓として生かすべきところは生かす必要がありますが、この事故を受けて、すべて屋上に対して使用制限を設けるとかというようなことでは、特に考えてございません。","voiceIndex":197,"id":"exchange-071"},{"speaker":"中塚委員","kind":"意見","question":"東京じゃない、他の自治体になっているので、いろいろあるのかもしれないけど、横の連絡というのはどういう状況にあるのか、何か改善すべきものもあるのかなと、見ていたんですけれども、まだまだ私も知らない範囲が多いのであれですけど、ちょっとそこだけご説明いただけますか。","respondent":"市川教育次長、若月教育長","answer":"そんなこともありまして、これまで、私も新聞で知る限りは数例、この関東の中で痛ましい事故が起きたということは承知しておりますけれども、いわゆる関係者の中で。その時に例えば委員の方々がこう言ったら、「教育委員会がだめだと言うからまだ使えないんですよ」なんていうことがもし耳に入ったらば、その裏には今のようなことがあるということをひとつご理解をいただいて。","voiceIndex":199,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":53668,"voices":203}},{"id":"h20-20080623-5","meetingId":"h20-cm06","date":"2008年6月23日","dateIso":"2008-06-23","committee":"総務委員会","time":"午前１０時０３分～午後３時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１番目、第５２号議案、（仮称）品川区災害対策荏原職員待機寮改築工事請負契約","agenda":"１番目、第５２号議案、（仮称）品川区災害対策荏原職員待機寮改築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"すいません、ちょっと今、聞き漏らしたのかと思うんですが、もう一回確認なんですが、施設の老朽化ということで建て替えをすると。何年、建ててから３９年ということですか。それで一般論として、今後、鉄筋だと思うんですが、３９年ということはちょっと早いのかなという感は受けるんです。","respondent":"宍戸施設担当課長","answer":"ただ、コンクリート躯体の不具合が原因と思われる漏水、雨漏りですとか、あるいは構造関係の基礎資料や何かが買い取りなので少ないといったようなこともございまして、あとは、今日ご覧になっていただいたように、１戸当たりの面積や何かにつきましても。","voiceIndex":7,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"本来なら上に上げられると思うんですが、それは何か理由があるんでしょうか。実際、建てるなら、容積率がせっかくこれだけ余っていたら、まだ５０％、６０％は十分上にかさ上げできるような感じもしますし、それのほうが建築コスト的にも安いんじゃないかなと、もっと部屋も増やすことができるんじゃないかと思うんですが、その辺のご見解をお聞かせください。","respondent":"宍戸施設担当課長","answer":"あそこの建物につきましては、日影規制がございまして、その関係であまりストレートに４階とか５階というふうに容積率だけを考えてはできません。","voiceIndex":9,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"でも現実論は、中に住まわれる方が日が入るように南側をあけて、北側はややですか、狭いのか、広いのかわかりませんが、同じぐらいなのかもしれませんが、真ん中辺に置いていると思うんですが、せっかく建てるなら、待機寮というのは入れる人たちが多いほうがいいのではないかなとちょっと思ったので、ただ、近隣に対する配慮ということで、３階建てで持っていくということは理解はできますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"今の質疑も聞いて、なるほどと思ったんですけれども、この待機寮そのものは、単身者部分が１７戸とファミリーが３戸ということで、それなりの職員確保にはなっていくのかなと思うんですけれども、改めて、待機寮が今、どの程度、品川区として確保されているのか、それから、この契約そのものにはちょっとそれるんですけれども、ついでながら。","respondent":"榎本人事課長、宍戸施設担当課長","answer":"足りない部分につきましては、民間の住宅の借り上げ等も検討していく考え方でおります。太陽光パネルの設置についてですが、一応、基本計画の段階では、設置したらどのぐらいつけることができて、どういうふうな効果があるだろうかということは検討はいたしましたが、課題といいますか、高さ的にも。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"職員確保が一時期本当に採用がずっと抑えられていた時代があったんですけれども、ここ数年前から採用が高まってきている中で、地方からも呼び込んでいくという表現がいいかどうかあれですけれども、採用を地方からもということは当然あり得ることで、できるだけ品川区に長くとどまっていただくという上からも、災害がいろいろな意味で起こるという時代の中からも。","respondent":"榎本人事課長","answer":"寮の内訳ですけれども、実は今までで全部で品川区が寮として活用した個数は１１寮あります。そのうち３寮は、今、廃止されている状況です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"今の話も若干かぶるんですが、建設した後、職員を、つまり待機という名前のとおりですから、計画があると思うんですけれども、どのぐらいここに入っていただいて、それから入った方々に対しての、例えば義務、防災のための義務は当然あると思うんですけれども、それはどういったものかということ、これは課がもしかして違うかもしれませんけれども。","respondent":"榎本人事課長","answer":"それで、あとは防災訓練が毎月１回ありますので、待機寮に住んでいる方については必ず防災訓練に年１２回出まして、それぞれの防災対策の中身を熟知して、いざ職員がいっぱい集まったときにはリーダー的な役割を果たせるような形での訓練を積んでいるところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"待機寮という表現のとおりですから、職員の方に入っていただくことがまず第一でありますし、それから、入っていただいた方がそういう本当にそのときに動いてくださることが一番で、今の答弁を聞いて確認できた部分もあるんですけれども、毎月１回の訓練、それから震度４で待機というのはちょっとハードルが高い気もするんですけれども、でもそれはもう義務ですから仕方ないんですけれども、そうすると。","respondent":"榎本人事課長","answer":"ただし、今現在、新規採用者が多くなったということと、あと区内に職住近接で住もうとするときに、なかなかアパートを新規採用でいきなり区内に借りるというのは難しいということで、ちょっと離れたところに住む話になってしまうという形もありまして。","voiceIndex":19,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"そういう中での入寮の話は、今言ったようにそういう訓練もあるよということで、お値段幾らよと、ここよというスタイルで入寮されるんですけれども、退寮の話というのはどういう、要するに、組合との間、職員の皆さんとの間での取り決めみたいなものが何かあるのか、それとも就業規則的に何かつくっていらっしゃるのか、それはどうなっているんでしょうか。ちょっと教えてください。","respondent":"阿部経理課長、榎本人事課長","answer":"もう１つ、電気設備につきましては３,１１３万４,６００円です。機械設備工事につきましては、４,１０５万５,０００円です。総額で３億３,４６８万９,６００円です。世帯につきましてはそれほどまだ立て込んでおりませんので、それと、あとお子さんのいろいろな学校の関係がありますので、５年プラス更新１回の３年ということで８年という形で取り組みをしています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"中身のことに集中したんですけれども、当然、周辺の、工事になれば解体もしていきますよね。そういう関係で、近隣の方々に説明だとか、もちろん手続にのっとってされてきていると思うんですけれども、その中で、いろいろな意見とかがもし出ているものがあれば、大ざっぱでいいんですけれども、紹介していただきたいと思います。その辺の確認をしたいなと思ったんですけれども。","respondent":"榎本人事課長","answer":"計画説明会につきましては、昨年９月２８日に、荏原待機寮の改築計画の説明会を行いました。その中で、特に細かい点を除きまして大きなところでは異論等はなく、要は４階建てが３階建てになるということで、日照等の被害もないという形になりますのでありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"南委員","kind":"確認","question":"確認なんですけれども、そうすると、今までは実際にそういう火災のときに緊急的に短期間入っていただくお部屋はあったと、これからはここの施設はないけれども、よその待機寮でそういう対応ができるような部屋を１室、改築された後も含めて、ずっとそこの施設で対応していく分を確保するということなんですね。","respondent":"榎本人事課長","answer":"今まではこちらの荏原寮と、伊藤職員待機寮という２つでそれぞれ世帯用の部屋を２部屋用意しておりました。今回は伊藤の寮はそのまま継続しまして、荏原の分につきましては、従前居住者住宅のところに１部屋確保しておりますので、それを継続して使っていくという考えです。","voiceIndex":28,"id":"exchange-010"}]},{"id":"topic-02","title":"議案審査を続けます。先ほど休憩前にもご案内いたしましたとおり、４番目の第５５議案、土地の取得","agenda":"議案審査を続けます。先ほど休憩前にもご案内いたしましたとおり、４番目の第５５議案、土地の取得","exchanges":[{"speaker":"金野委員","kind":"質問・要望","question":"先ほど現地を視察させていただいて、暫定的なことでということで、公園として一部を開放するというお話がありましたけれども、ここは確か避難所にも今後なるというような、そんなお話もある中で、暫定的な公園の中身というのはこれからと伺ったんですけれども、池等も見せていただいて、今後どのようになるのかという、大ざっぱでいいんですが。","respondent":"松代管理工事課長","answer":"暫定整備の内容につきまして、私からご説明申し上げます。当該地、今回の議決で用地を購入された後、直ちに工事に入ってまいります。その工事内容も幾つか分かれておりまして、基本的には３つに分かれてあります。","voiceIndex":43,"id":"exchange-011"},{"speaker":"金野委員","kind":"質問・要望","question":"暫定的なというところなんですが、一応、区民の方に一般開放ということになると思うので、公園として使っていく、地域の方の要望なり、区民の方の要望というのは、どうなんでしょうか。","respondent":"松代管理工事課長","answer":"それを今回、暫定ではあるんですが、将来の本整備にあわせまして、先行してその辺を整備したいというものでございまして、あとの細かなところにつきましては、今後の本整備に向けて、広く区民の皆様の要望等を取り入れて整備をしていきたいと考えているところです。","voiceIndex":45,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問","question":"本整備に向けてということなので、二重投資というんでしょうか、あくまでも暫定だけでしないで、本整備に絡んでやっていくというふうにお考えを多分お持ちだとは思うんですが、その点はいかがですか。","respondent":"松代管理工事課長","answer":"昨年の決算特別委員会、また予算特別委員会等でもそのようなご指摘がございました。２年半ほど先の本整備に向けて、その辺は十分配慮した上で、二重投資にならないように考えてあります。","voiceIndex":47,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"あと２つ目の質問は、あの地域一帯が防災生活圏促進事業ということで網がかかっているんですけれども、今回、土地の取得をすることなんですが、この防災生活圏の促進事業との関係では、今回の土地の取得というのは品川区の独自財源で買うのか、その辺の確認から始まるんですけれども、それが１つと、それからさっき言った生活圏のところの関係で。","respondent":"松代管理工事課長","answer":"そういった中で、国の補助対象メニューがいろいろとありますので、そういったものもあわせて今後の事業展開の中の財源措置として十分検討して進めていきたいと考えているところです。","voiceIndex":49,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"それで、鮫洲大山線、都道との関係なんですが、先ほども申し上げたように、公開空地をつくって歩く方々の安全を守るという、そのことについては全く否定するつもりはないんですけれども、要するに、つくることによって、歩道空間が整備されることによって、今は狭いからこっちの道を行くのはやめようとか、こっちの道で行こうとかというドライバーの心理として働いて。","respondent":"松代管理工事課長","answer":"将来の計画等につきましては、委員の今のご心配の点も十分配慮して道路整備等はしていく考えですけれども、２６号線の完成時期と整備をする時期と両方が時期的にちょうど合いますので、そういったところでの交通量の将来的な予測と、そういったものも検討しながら。","voiceIndex":51,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"１つは、これは公園用地として取得をするということになっているんですけれども、相手方が今は大学共同利用機関法人という機構なんですね。実態としては、１１３１－４は道路になっているのではなかろうかと思うんですけれども、これは我々には関係ないということでよろしいんでしょうかということです。したがって、それはどういう関係になっているのかということをお聞かせください。","respondent":"冨久増用地担当課長","answer":"本件の土地を買収するにあたりまして、国との関係で用途の縛りが今後あるのではないのかという問題ですが、本件につきましてはあくまでもこちらの人間文化研究機構と区側との売買契約ですので、基本的に。","voiceIndex":53,"id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"ある程度わかりました。それで、国との関連ということでは、独立行政法人であるがゆえに、そことの話し合い、契約に基づいてこの代金が支払われると、そして独立行政法人は独立しているんですから、自分のところの経営上、最大限の値段で売りたいと、こうなると、これは当然の話ですね。経営上そうですね。","respondent":"冨久増用地担当課長","answer":"本件の土地はかなりお安くなっております。これは区が考えている行政目的等をるる機構にご説明し、お願いした結果、安くしていただいたと、かように思っておりますので、ひとつよろしくその点はご配慮いただきたいと思います。","voiceIndex":55,"id":"exchange-017"},{"speaker":"土井委員","kind":"確認","question":"この土地を買うにあたって、市価で普通なら契約をするところであるし、市価でやるということでこの法人と話し合いをした結果、結果として、いわゆる周辺の市価よりもお安い値段で区なら譲ってもよろしいですよと、こういうお話にまとまって譲っていただくんですよということが１つ、それからもう１つは、この用地は公園用地として取得するとここに書いてありますけれども、これは縛りではなくて。","respondent":"松代管理工事課長","answer":"しかしながら、別の意味での縛りといいますのは、ここは都市計画区域として都市計画決定をした、将来公園であるべき土地という形になっておりますので、その点だけが縛りといえば縛りだと考えています。土地を買う上での縛り等はないものと考えています。","voiceIndex":57,"id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"今、都市計画公園という縛りは、変な話、我々が決めたと言っては語弊があるかもしれないけれども、決めたわけですね。だからここでいろいろ議論もして、また区民の皆さんにお願いもして、変更することは可能だと考えていいですね。結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それで気になったのは、先ほど見てきた建物の耐震はどうなのかということ、調査された上で使っていると思うんですけれども、変な話、こちらの工事をしている最中に大きな地震があって、あそこがつぶれてしまったら、何のためなのかとなる可能性もありますので、そのことについての答弁をいただきたい。その２つをまずお願いします。","respondent":"日下部企画財政課長、宍戸施設担当課長","answer":"ですから用地を取得する、そうすると当該年度に５４億円ですか、その支払いが出てまいりまして、その年に都市計画交付金、４分の１から５分の１ということで入ってはまいりますけれども、それ以外の分は。実は学校等の工事が今年大分開始されまして、居室的な使用や何かについても要望があったところですが、今回、耐震診断結果に基づきまして、補強が必要だということで、居室的な使用は一切しない。","voiceIndex":60,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、必ず人の出入りが出てくるとなってくると、その辺はどうなんでしょうか。生命のことを考えていくと、必要最小限の耐震をした上で、品川区の職員の方が安全に、２年間の限定であったにせよ、使える環境にすることが必要なんじゃないでしょうかといった疑問がありますので、そのことを教えていただきたいのと、あわせて、将来は駐車場、区有車の駐車場をつくるという説明もいただきました。","respondent":"宍戸施設担当課長、阿部経理課長","answer":"駐車場ですけれども、青空駐車場ということもございまして、あと、それから管理、後ほど経理課長からご答弁申し上げると思いますが、暫定的に人員の配置があったとしても、建物内ではなくて、簡易な建物を建てて、そこで管理をすると。管理の人の配置ですけれども、１名ないし２名、今申し上げましたように配置する予定でございまして、庁舎から例えば倉庫に行く場合には、必ずそこの管理している者のところに行って、かぎを借りてやるという方式をとってまいります。","voiceIndex":63,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"それで１点だけ、庁有車、ここを駐車場として使うんですが、ここに駐車されると、自動的に今度はどなたか運転者がいて、区のほうに運ぶ、そういう車、運転手等々、迂回するというんじゃなくて、区に運ぶ、またこちらに戻ってくるというのは、そういう車が随時、配送車ですか、あるのかどうか、それも時間的にきちんと決められてやっているのか、そしてちょっとわからないんですが、これは予算科目のところに。","respondent":"阿部経理課長、日下部企画財政課長","answer":"あくまでも利用する課が行って、車を使って、また元に戻すという形にする予定です。公有財産購入費が３つ続いているということでありますけれども、これは予算上の整理の１つの技術的な問題でございまして、実は今回はここまで入れる必要はないのではないかと思いますけれども。","voiceIndex":66,"id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"先ほどの回送の話なんですが、車で行き来しないと、時間的には相当かかりますよね。今のお話だと、回送する車がないということは、自転車なり何なりで来て、またそれで運ぶのか、戻るのか、するとかなり時間的なロスというのは１日の間に相当つくと思うんです。その辺について、もしお考えがありましたら。","respondent":"阿部経理課長","answer":"一応、自転車を予定していますけれども、電動つき自転車というものもありますので、移動にはそんなに時間はかからないと考えています。","voiceIndex":69,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"それから駐車場を、一定程度あそこは見てきましたので広いというのはわかりましたけれども、でも、木立が結構、１本、２本立っていますけれども、できればそういう、あれだけの大きな成長した木を育てるというのは、これからも相当な年月がかかりますので、できれば切ってほしくないなと思うんですけれども、今後の公園の活用をする際にしても、その辺は多分、検討されているんじゃないかと思うんですが。","respondent":"阿部経理課長、松代管理工事課長","answer":"ですから持っていくものは、今申し上げた各課が所管しているものと、あと経理課が貸し出し用に持っているもの、それが主です。こちらの図面でいきますと、右肩に方位があります。こちらが北側になりますけれども、北側のほうの部分に、今回、庁有車の駐車場を整備する予定です。","voiceIndex":72,"id":"exchange-024"}]},{"id":"topic-03","title":"第５３号議案、品川区総合庁舎耐震改修工事請負契約","agenda":"第５３号議案、品川区総合庁舎耐震改修工事請負契約","exchanges":[{"speaker":"金野委員","kind":"質問","question":"１つ教えてください。免震装置、これはどのぐらいの震度に耐えられるものなんですか。","respondent":"宍戸施設担当課長","answer":"震度７という激震と言われる地震でも耐えられるというふうな構造になっています。","voiceIndex":87,"id":"exchange-025"},{"speaker":"土井委員","kind":"質問・要望","question":"それが１点。もう１点は、今回のこの工事について、最終的には、ここに記載されている限りにおいては、清水建設のみが落札といいますか、入札をされたと、あとは参加してくださいと言ったのかどうかわかりませんけれども、ご辞退されたという形になっていますけれども、この辺の経緯、経過等についてお聞かせください。","respondent":"阿部経理課長","answer":"それで、やり方としては、まず最初に区側からこういう工事の内容を説明いたしまして、その説明を受けて、５社が自分たちの価格、ここでいうと入札金額ですけれども、それと、あとはどういう技術を持っているかと、そういう審査対象になるようなもの、それを同時に私どもに。","voiceIndex":89,"id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"わかりました。だからすばらしい場合もあるわけですから、それは何とも言いかねるんだけれども、今回の場合は、その意味で、この免震技術とか、特に免震が大きな要素だと思うんですけれども、この辺はその意味ではこの５社はみんなお持ちなんでしょうか。どの程度の、特許とか何とかでいろいろやっておられまして、それぞれまた特徴があるんだろうとは思うんだけれども、そこら辺はどうだったんでしょうか。","respondent":"宍戸施設担当課長","answer":"免震工法も大分普及してまいりまして、少なくとも今回の設計につきましては、この５社とも十分参入できるような内容で設計いたしまして、工法的に特許や何か、特定の会社しか対応できないので、こういうふうな結果になったということは一切ございません。","voiceIndex":91,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"それと、価格点３５点というのは、これは以前の行財政改革特別委員会に出された資料の委託契約実施要綱というんですか、これの最後のところに価格点のパーセンテージによって価格が出てくるという、そこをならって出されたものだという理解でいいんでしょうか。それが２つ目です。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"要するに、価格が低いほうが価格点としては高くなる、予定価格に近づけば近づくほど価格点は低くなるというようなやり方です。ただ、大きい地震のたびに、そのもの、状況については検証はすると思います。その辺、大丈夫かどうかという確認はその都度、その都度すると思いますけれども、１回の地震で使えなくなるというふうなことは聞いてございません。","voiceIndex":93,"id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"それから技術点のところなんですけれども、私がちょっと聞き逃して不正確だったら申しわけないんですが、幾つかの事例の中で、既に５社ともマイナス６点でスタートをするんだというふうに聞いたんですけれども、そういう企業がこういう今回の工事に対して入札をしてくるということなのか、ちょっとどういうふうにその辺というのはとらえたらいいのかなというのが私としては判断しかねるんですけれども。","respondent":"阿部経理課長","answer":"そういうペナルティーを受けた会社につきましては、そういう減点項目を技術評価の中に入れているです。ただ、今現在、指名停止であれば、当然、今回参加できませんので、そういうことではなくて、過去にそういう事例があったということで減点になったというものです。","voiceIndex":96,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"今そういう状況であるならば言語道断ですから、当然だと思うんですけれども、しかし、過去のところをどこまで問うかというのは一定程度の配慮をしないといけないのかなと思いますけれども、何となく、そうですかと１００％納得して受けとめていくというのはなかなか難しい部分があるかなということだけ、これは私の意見なんですけれども、表明しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですからその辺が、今までにない知識と、それから評価する方法を求められていくわけですから、そのことについては、今回は試行だけれども、再度これからどういうふうにしてこの精度を高めていくのかということについては答弁をいただきたいなと考えています。それから改修工事をすると、当然、来庁される方々にいろいろな影響が出てくるわけですよね。","respondent":"阿部経理課長","answer":"なお詳細につきましては、区民の方への周知につきましては、来月の２１日の「広報しながわ」で、よりきめ細やかな動線等の説明を行いたいと考えています。","voiceIndex":99,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問・要望","question":"明日、しっかり報告を聞きたいと考えていますので、改めてよろしくお願いいたします。だけれども、Ａ社にはこういう技術があって、この品川区の仕事はこうだから、任せれば、ちゃんとできるということを区側が評価するということに踏み出したわけですから、工事評定だけじゃなくて、もう少し、何ていうかな、考えていただきたいなと思うんですが、いかがでしょうか。","respondent":"宍戸施設担当課長","answer":"それで、施行体制とか安全対策、騒音振動対策、それから品質確保、その他ということで、特に品質確保につきましては免震工法の専門家や何かの意見も取り入れたりなどして、項目や何かについてもどういう項目について聞くのがふさわしいかということについても研究した結果。","voiceIndex":101,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、これは特殊技術で、このような高度技術を必要とする場合に、今回、図らずも辞退者がこういうふうにあらわれたわけですが、特殊技術の場合に、こういう技術というのは日本でこの５社しかないのか、それとももっとあるのかわからないんですが、そういう特殊技術の場合には、逆に門戸を広げてもいいんじゃないかと思うんですけれども、今回に関しては、どうなんですか。","respondent":"阿部経理課長","answer":"今回の工事につきましては、先ほど申し上げましたとおり、制限付き一般競争入札ですので、格付はありますけれども、格付を受けている会社についてはどなたも、一定の制限はありますけれども、どなたでも参加できるということで、たまたまこの５社が申し込みをしたです。","voiceIndex":103,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ。今回、改修工事で、第二庁舎と第三庁舎に関しては、第三庁舎は耐震改修のみ、第二庁舎はいじらないということなんですが、議会棟と本庁舎は免震装置を、これは基礎の下に入れるわけですよね。そうすると、第二庁舎と第三庁舎とのバランスですか、それをとれるのかなと、はっきり言えば段差ができちゃうんじゃないでしょうかというふうな感じで受けるんですが、その辺はどうなんでしょうか。","respondent":"宍戸施設担当課長","answer":"今回、どういうふうなことをするかというと、くいの部分を一部切って、そこに免震装置をはめ込むんですけれども、ジャッキアップをいたしまして、１回くいの部分を切って、そこに免震装置をはめ込むんですが、その振動というか。","voiceIndex":105,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから大丈夫だと。ただ、そのとき本当に気をつけなきゃいけないのは、入れるときに地震でも起きたら、それこそどうするんだろうということと、ジャッキアップをするといっても、全体をおそらく平均に持ち上げるわけですから、大変な工事だと思いますので、ぜひ慎重の上にも慎重を重ねて、危険のない工事をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-035"},{"speaker":"山路副委員長","kind":"質問","question":"免震装置というのは、平成７年の阪神淡路大震災が起こったときに、西宮駅の周辺で、ちょっと離れていましたけれども、免震装置をしてあるところの建物はそのまま残っていました。何となくすっきりこないところが、説明を受けましたので、それはそれでいいんですけれども、今回の清水建設は、２３区でほかの区でどこか設置工事をしたところがあるかどうか、その辺がわかったら教えていただけますか。","respondent":"宍戸施設担当課長","answer":"ただ、実績についてもある程度聞いておりまして、いながらで官庁に関する工事は実績があると聞いてあります。２３区ではございませんけれども、ほかの官庁、国ですとか他県については相当数実績があると聞いてあります。","voiceIndex":108,"id":"exchange-036"}]},{"id":"topic-04","title":"３番目、第５４号議案、戸越幹線貯留管中流部整備工事請負契約","agenda":"３番目、第５４号議案、戸越幹線貯留管中流部整備工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"結果的に、この戸越幹線というのは、工事は先ほど午前中の視察で前後は既に終わっているという話で、ここだけが残っていると聞いたんですけれども、今回の工事が終われば全部終了するということなんでしょうかということが１つと、それから、今、鋼製セグメント、これをつくったものを圧入していくということなんですけれども、シールド工法で穴を、トンネルを掘ってから。","respondent":"家壽田下水道河川課長","answer":"２点のご質問についてお答えいたします。今回の戸越の中流部です。","voiceIndex":122,"id":"exchange-037"},{"speaker":"土井委員","kind":"質問","question":"もともと下水幹線があって、そこにあちこちから流れ込んでくるものがうまく入ってこられない、あるいはあふれちゃうという形で表面に浸水が起こるよと、これをここにため込むわけですよね。そうすると、ため込むということは、いつもは空っぽにしておかなきゃいけないわけですよね。ふだんは。ということは、ため込んだ後は吐き出さなきゃいけないわけですけれども、それはどこに何がつくられるんですか。","respondent":"家壽田下水道河川課長","answer":"委員がご指摘のとおり、洪水を防ぐためにこの６,０００トン近い貯留管にため込みます。","voiceIndex":125,"id":"exchange-038"},{"speaker":"土井委員","kind":"意見","question":"ということは、今ここにシールド工法でつくりました穴ぼこは最終的に埋まっちゃうのかどうかということと、そのポンプ場があそこにつくられるとなれば、どんな形になるのか、上なのか下なのか、地下に潜ったものができるのか、要するにあそこの公園の修復を含めた、形状的にどうなるのかなというのがちょっと気になったのと、ポンプというのはあまり静かなものじゃありませんので。","respondent":"家壽田下水道河川課長","answer":"それからコンクリートでしっかりつくりました構造の中にポンプを置きますので、基本的には気がつかないほどの音ということで、騒音上の心配もないような形で我々としては考えています。","voiceIndex":127,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"今回、入札でお聞きしたいんですが、会社名が２社、共同企業体ということで出ているんですが、実際、貯留管工事、これも専門性がかなり高いことと思いますよね。だって１社でやったほうが専門的に自分で管理できますし、独自にどんどん事業も進められるし、工期も早いと思うし、コスト的にも安いと思うんですが、その理由についてお聞かせください。","respondent":"阿部経理課長","answer":"説明がございましたけれども、今回の鋼製セグメント方式というのは区内で初めてやる工事です。","voiceIndex":129,"id":"exchange-040"},{"speaker":"須貝委員","kind":"意見","question":"そういう装置もおそらく持てないような会社が一緒に組んで、学んで、どうするのかなと、それだったら１社でやったほうが早く済むし、繰り返しますが、値段も安いんじゃないかなと。これに関して、何も一緒に組む必要は私はないと思うので、それはちょっと意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-041"}]},{"id":"topic-05","title":"２番目、品川区長期基本計画の策定状況","agenda":"２番目、品川区長期基本計画の策定状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"聞き違いがあったらあれなんですけれども、「１００円労働」とおっしゃいませんでしたか。１００円労働という意味がよくわからなかったので、教えていただきたいと思います。","respondent":"福島長期計画担当課長","answer":"「派遣労働」です。","voiceIndex":148,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"それがさらにパブリックコメントという形で区民の意見だとか、いろいろな方々の意見はいただく、そういうシステムにはなっているんですけれども、もっともっと、これに限らず、長期基本計画ですから、議論を深めていく必要があるんじゃないかなとも思っているんですけれども、その辺をどういうふうに考えておられるのかを伺いたいのと、出された意見で一定まとまったものをもって。","respondent":"福島長期計画担当課長","answer":"ですから、ほかの回にでも出ることはあるかと思います。全体で１回、一応、区切りながら議論いただいた後、さらにもう一度、全体についてご審議いただく機会も設けてありますので、そういった中でさらに深めていけるのではないかと考えております。","voiceIndex":150,"id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"そういう方たちにアンケート、たまにいろいろ品川区でもとっていると思うんですが、そういう方のアンケートをここにまた反映させるというチャンスというんですか、それはあるんでしょうか。要は、生の声というのは、話し合っている方もそれぞれのお立場はあると思うんですが、生の声もすごく大事なのかなと、まとまりがつく、つかないとしても、参考意見としてと思うんですが、その見解だけ。","respondent":"福島長期計画担当課長","answer":"ただ、実際、委員の中にもお子さんをお持ちの方が多数いらっしゃいますので、そういった中でご意見をいただいていきたいと考えています。","voiceIndex":152,"id":"exchange-044"}]},{"id":"topic-06","title":"区民と区との協働を進める懇話会","agenda":"区民と区との協働を進める懇話会","exchanges":[{"speaker":"南委員","kind":"意見","question":"それぞれＮＰＯ法人、それからボランティア団体の紹介があったんですけれども、大体どんな内容で活動しておられる団体なのか、おおよそでいいんですけれども、ちょっと知りたいなと思って、「おばちゃんち」というのは、以前、たしか区民委員会で視察に行きましたので大体はわかるんですけれども、こういうものかななんていうのはちょっとわかるけれども。","respondent":"久保田行財政改革担当課長","answer":"各団体の活動についてご説明いたします。一番最初、山中いきいき広場ですけれども、こちらは山中小学校の中に山中いきいき広場というものを設けまして、自主企画事業といたしまして、料理教室とか健康太極拳教室、絵手紙教室などを運営しております。","voiceIndex":159,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問","question":"これは検討の結果を区に提出するんですけれども、そこまではいいんですが、受け取った品川区が、それを例えば長期基本計画に生かしていくのか、それともそれを分析・評価をして、各課のセクションへ伝えて、新しい施策に生かしていくのか、そういうところまで計画はしていると思うんですけれども、ただこれだけをつくって終わりではないと思いますので、そのことについてご答弁をお願いします。","respondent":"久保田行財政改革担当課長","answer":"その中でこの懇話会で出されました意見を踏まえまして、実際に施策、活動団体への支援や協働の進め方、具体的な施策の検討を行って、一緒に仕組みづくりを同時並行という形で進めていく予定になっております。","voiceIndex":161,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"そこのところが実は一番大切でありますし、議論して、区民の感情に近い方々が、こういう問題だったらこういうものがあるよと指摘をする、それを品川区が受け取って検討していくんですけれども、もうちょっと踏み込んで、その具体的な品川区の政策、施策の検討をする中に、できればこういう方々も、できればですよ、参加していただいて。","respondent":"久保田行財政改革担当課長","answer":"委員がご指摘のように、施策の中に参加という形があるんですけれども、１回目の懇話会の中でも委員の方からちょっとお話が出たんですけれども、例えば品川区との共同提案みたいな、そういう制度みたいなものがあったらどうなんだろうかとか、そういうお話も出ていましたので。","voiceIndex":163,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"最後に傍聴について、場合によってはという、会場の都合という断りがあるんですけれども、できるだけ区民に開かれた、いろいろな方々が区と協働を探るためにこういう角度で検討しているというのは本当にいいことだと思いますので、できるだけ制限することなく、もし傍聴においでになる方が多数になるということが予想された場合には、会場の変更も含めて、いろいろな対応ってできなくないと思うので。","respondent":"久保田行財政改革担当課長","answer":"検討部会との関係ですけれども、同時並行という形で進めていきますが、実は区の関係で、私も含めまして、地域活動課長、産業振興課長が入っておりますけれども、こちらのメンバーも庁内の検討会議のメンバーになっておりますので、こちらの懇話会から出た意見を。","voiceIndex":165,"id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"そうすると、この懇話会で出た、例えば、どういうものが出るかわからないですけれども、何かの部署の１つのセクションの部課の所管のところの意見が出たとしたならば、それを庁内の検討部会のところで反映させていく、こちら側の議論が、それを受けて政策、方針の中でそしゃくして具体的な施策にあらわれていくという形になるんですか。","respondent":"久保田行財政改革担当課長","answer":"個別の事業についてのというあれではございませんので、協働の提案づくりという、区の全体的な中での仕組みづくりということですから、例えば懇話会の中で個別の施策という議論はしないようにというか、そういう確認もとってありますので、協働の仕組みづくりという形で。","voiceIndex":167,"id":"exchange-049"},{"speaker":"金野委員","kind":"質問","question":"基本的なことを教えてください。この懇話会での学識経験者ということで２名の方が座長、副座長というのに選ばれているんですが、どういった観点でこの方たちを選んだのかを教えてください。","respondent":"久保田行財政改革担当課長","answer":"品川区にゆかりのある方とか、地域コミュニティー、協働について全体を知っている方という方でいろいろありまして、それで直接お話も聞きまして、たまたま今回、中村先生と服部先生ということになったんですけれども、このご両人ともいろいろお話をしまして、品川区の事情等。","voiceIndex":169,"id":"exchange-050"},{"speaker":"金野委員","kind":"質問・要望","question":"この委員の方のＮＰＯ法人が６法人ですか、出ておりまして、いろいろな先ほど活動の内容を伺って、また学識経験者の方もＮＰＯ法人の関係者の方だということなので、非常にいろいろな角度からの意見が挙がってくる中、私のイメージが、これが区との協働となることで、これがどれだけ、要するに反映をされていくのかという、ほかの委員の方の質問もありましたけれども、庁内の検討部会も行われるということで。","respondent":"久保田行財政改革担当課長","answer":"そこは１回目の懇話会でもいろいろと委員の方からお話があったんですけれども、こちらの懇話会につきましては、あくまでも具体的な仕組みづくりということを目標に懇話会を進めていきたいという確認をとらせていただきまして、実際に活動している方が。","voiceIndex":171,"id":"exchange-051"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"提案","question":"基本的にいいんですけれども、１点目のところがよく聞き取れなかったので、もう一回教えてもらいたいんですけれども、国際平和都市としてのですか、そこを自民党から提案されたこの表現でいいということにしたいということですね。","respondent":"須藤委員長","answer":"それから都区制度については先ほど説明したとおりですので、大事な時期ですので、所管の委員会としては、できたら区長から生の声を聞いたほうがいいだろうというようなことで、理事者側にお願いいたしまして。そのように決めまして調査研究を進めてまいりますので、よろしくお願いいたします。なお、理事者の皆さんにもいろいろと資料等の要求もあると思いますので、お願いいたします。","voiceIndex":176,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1788#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":50137,"voices":181}},{"id":"h20-20080624-6","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"区民委員会","time":"午前１０時０３分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「結婚のサポートの事業内容について」","agenda":"の「結婚のサポートの事業内容について」","exchanges":[{"speaker":"稲川委員","kind":"確認","question":"確認の意味を含めていろいろお伺いをしたいのですが、まず、事業目的のところで、「結婚を支援することは、少子化対策」と書いてあるんですけれども、結婚イコール少子化対策になるかどうか、これはちょっと疑問が、個人的なのかもしれないんですけれども、要は、目的のところに少子化対策一つにしか絞られていないというのはちょっと疑問があるということと、あと、パートナーの紹介事業。","respondent":"小野区民課長","answer":"人と出会わないからという答えが約４０％、５０％近い回答がそういう形で来ておりまして、出会いというものがなかなか今の社会状況の中で難しくなっているということもあるというふうに認識をしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"稲川委員","kind":"質問","question":"報告が、２３日ですぐ議会中の委員会じゃないですか。それを取りまとめていただけるのかどうか。","respondent":"小野区民課長","answer":"できるだけそのように努力はしますけれども、日程の関係で十分というところまでいけるかどうか、その辺のところはご容赦をいただきたいと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの答弁の中で、今の社会状況の中で出会いの場が持てなくなっているというところで質問があったんですが、出会いの場が持てないという社会状況の中というのは、どういうふうに社会状況の変化を認識していて、結果、出会いの場がなくなっているのかなというお考えなのかなというのをお伺いしたいと思います。","respondent":"小野区民課長","answer":"以前であれば、まちの中で、あそこには年ごろの人がいるから、この人どうかしらというふうなお話を持ってこられるということだとか、あるいはお見合いだとか、そういうふうな、社会として婚姻を助けるような活動というのがかなりあったわけですけれども、だんだん。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"すみません、次の質問なんですが、１と２の事業なんですが、セミナーと相談事業、カウンセリングみたいな感じなんですけれども、ここに行政として、「品川区結婚サポート事業」ということで冠を打ってやるわけですけれども、どこまで区が事業の内容というか、かかわるのかなというか。それとどう違うのかなというのをお伺いしたいと思います。","respondent":"小野区民課長","answer":"セミナーについても、セミナーの中の企画であるとか、そういうものについては、これは民間のノウハウの中でやっていただくということが基本だと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"今回あえて結婚サポートということで始めるということなので、今まで民間、オーネットではやっていなかったような結婚セミナーとカウンセリングをやるのかなというところがわからないというか。前やっていたかどうかというのは、どう違うんだというのがちょっとよくわからないんです。","respondent":"小野区民課長","answer":"こういうふうなことをできるだけ敷居を低くして提供することによって、今までなかなか踏み出せなかったという方については、こういう結婚ということについて、自分で一歩踏み出していただく。そのためのバックアップをしたいというのが行政の考え方です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"区として、３番目の事業の位置づけというんですか、どう考えているのかということをお伺いしたいのと、あと、広報などでこれからこういう事業を、確かに結婚ができなくて悩んでいる人は多いので、こういう事業自体は否定するものではありませんけれども、これから広報するわけですけれども、３番目のところは理解を得られるのかなというのが不安なんですけれども。","respondent":"小野区民課長","answer":"したがって、例えば今回予定をしていますチラシや何かを作成いたしますけれども、このチラシの中に３番目の事業の案内は入っておりません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。オーネットの側から言うと、すごく、お墨付きもあるし、品川区も安心のブランドも得て、非常にプラスになることが多いと思うんですけれども。オーネットにとってはすごくいいことであるというふうに思うんですけれども、民間のノウハウを活用して、品川区としてはその対価といいますか、何ていうんですか、そこまでして利益があるという考えで今回の事業を進めているということなんですか。","respondent":"小野区民課長","answer":"区の利益は、当然区民の方がこの事業によって結婚に一歩踏み出せる何かのきっかけをつかんで、そういう方向に行くという、これが区の利益です。区民の方がこれを使って、できれば結婚まで進んでほしいです。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"のウェルカムセンター原「地域活動・交流拠点」","agenda":"のウェルカムセンター原「地域活動・交流拠点」","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それと、名称のこととかは、まだ仮称ですけれども、どういった形になるのか、方向性を教えてください。","respondent":"中山地域活動課長","answer":"３０日ですので、運営協議会のほうでも準備に入って、協定のありようについて検討に入っておりますが、ウェルカムセンター原の交流施設運営協議会というほとんど仮称に近い名称になる予定です。","voiceIndex":24,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"１点なんですが、防災のほうでちょっと教えていただきたいんですが、災害時の防災機能の強化ということで、この地域の、このウェルカムセンター原と伊藤学園と、両方、防災機能が強化されると思うので、この地域全体としては防災機能がさらに上がると思うんです。備蓄なんかも増やしたりしますけれども、その辺のところを、強化する内容について教えていただきたいんですけれども。","respondent":"中山地域活動課長","answer":"基本的な、まず、整備での体制強化のところですけれども、図にありますように、改めて敷地内の防災倉庫をきちんと設ける予定です。今まで、図面の黄色で囲っている左のずっと下の部分に、「防災倉庫設備スペース」と書いた隣のところにあろうかと思います。","voiceIndex":26,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"心配なのが、一部の方に過重な負担がかかって、結果としてなかなか継続的に運営できなくなるんじゃないか、そういう事態がちょっと心配だなというのがあるんですけれども、それには事務局の態勢がかぎなんじゃないかなとは思っているんですが、すみません、ちょっと私も勉強不足で申しわけないんですが、検討部会からという検討部会というのは何なのかというのと、あと。","respondent":"中山地域活動課長","answer":"実際の運営もなるべく地元の方を中心にお願いしたいということでお話しする中で、お二人の方については専念できる、専従できるという形でお話をいただいておりますので、事務局のほうに従事していただくという形を考えておりますけれども、実際に例えば経理に関すること。","voiceIndex":28,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"１,７００万円余という、大体その内訳についてですか、もしわかれば。","respondent":"中山地域活動課長","answer":"残りの約８００万円程度になると思いますが、これが事務局あるいは、実際には有償のボランティアによる受付であるとか、事業の協力もお願いしようと考えていますので、そういうものも含めたいわゆる人件費的なものが約８００万円と、こういうふうになっております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"端的にお答えいただきたいと思います。ハードとソフト、両方ごちゃ混ぜになりますが、グラウンドの使用時間、午前９時から午後７時ということで、当初幼保一体等の関係から、もうちょっと日程的には制限されるというふうに、予算特別委員会だったかな、お話を伺ったので、ここの詳しい意味を。同時に、グラウンドのサーフェイスというんでしょうか、どういう状態になるのかも一つお聞きしたいなと思います。","respondent":"中山地域活動課長、斉藤防災安全担当課長","answer":"平日については基本的には利用の予定が、今度、学校ではありませんので空いてきますから、この辺はまたルールを具体的に決めてというふうに考えておりますけれども、午前、午後、夕方はどうしても、本格的な照明ができないものですから。防災の関係について、私のほうから説明させていだたきます。今現在、こちら側の建物につきましては、地域防災計画におきまして学校避難所というふう位置づけになっております。約８００名からの避難所ということになっております。","voiceIndex":32,"id":"exchange-012"},{"speaker":"若林委員","kind":"確認","question":"漏れがあります。機能的に確認をさせてください。要するに、いわゆる通常の学校避難所と、強化を図るということなのでアップするのか、それとも。もう一つ、役員の人件費について、もう一言お願いします。","respondent":"斉藤防災安全担当課長、中山地域活動課長","answer":"さらには建物の耐震化ということになろうかと思います。役員会を開いたときの人件費というものについては予定してはおりません。基本的には無償というふうに考えております。","voiceIndex":35,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"それは土日は優先されるということなんですけれども、例えば平日空いているときとかにテニスがやりたいとかいう方が仮にいらっしゃるとした場合、ここはもともと学校だったので、そういう設備等はあったと思うんですが、そのような、例えばポールが立てられるよとか、そういうのは全部準備してあるよとか、ある程度住民の方々のニーズにこたえられるような。","respondent":"中山地域活動課長","answer":"それで、テニスなどをやる場合のポール等ですが、想定としては、体育館もそうですけれども、一定のスポーツ、今例示があったテニスなんかもできるようなポール、あるいはネット等の設備等についても考えていきたいと予定しております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問","question":"そこの地域のほうが例えば優先になるよということになっているのか、それとも、ある面、全区的に視野を持っていくのかということになってくるんですけれども。今、時給の話があったんですけれども、いわゆる休みだとか、そういうことがどういうふうになっているのか。役員会は当然夜ということになると思うんですけれども、そういうときの事務局の方々の扱いというのはどういうふうになっているんでしょうか。","respondent":"中山地域活動課長","answer":"具体的な施設の使い方のルールですけれども、大井第三地域センター管内を特に優先という予定は今のところございませんが、やはり区民と区民以外の利用については料金等を分けていくという案を基本に考えているところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"宮崎副委員長","kind":"確認","question":"そういうところなんかも、会長のところの判断になってくるのかということを確認しておきたいのと、あと、大井第三地区のいわゆる優先的使用ということじゃないんだということなんだけれども、実態としてはそうなるんじゃないかという、そんな説明だったかと思うんですけれども、例えば広報紙の発行で、地域ニーズの調査というふうになっているんですけれども、そうすると、全区民を対象に考えるとなると。","respondent":"中山地域活動課長","answer":"確かに雇用形態としては会長の任用というふうになりますけれども、実務的に町会長がそういうことに対応するのは難しゅうありますので、ご質問にもありますように、実際には地域センターも含め、あるいは区のＯＢの職員も入れますから、区と地域団体との話の中で。","voiceIndex":42,"id":"exchange-016"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"初めてなので、とりあえずやってみて、私どももいろいろ見ていきたいなと思いますけれども。先ほども話したんですけれども、今町会の方々、非常に仕事が多くて大変だという声もありますので、ぜひ、そこら辺の声ですね、非常に配慮していただいて、無理のないようにしていただきたいなというふうに思います。これは要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"}]},{"id":"topic-03","title":"の「平成２０年度品川区民まつりの予定について」","agenda":"の「平成２０年度品川区民まつりの予定について」","exchanges":[{"speaker":"稲川委員","kind":"質問・要望","question":"この区民まつり、毎年毎年やられていて、非常に私、地域の結束力とかをつけるのにはすごいすばらしい、これはずっと続けていただきたいという思いの中で質問させていただきたいんですが、質問１点なんですけれども、これをやるに当たって、さっと見ると、荏原地区に関して、全体がそうなのかもしれないですけれども、以前、土日やっていたところがあると思うんです。なぜそうなったのか。","respondent":"中山地域活動課長","answer":"たまたま、昨年は、選挙の関係で、会場が急きょ変わったりしたようなところは、今までやっていなかったところということで、目の前のマンションの方から何事だというふうな苦情が運営委員のほうに寄せられているのを、私も、それはちょうど行ったときにあって。","voiceIndex":50,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"みんな、地域のため、子どもたちのためということで、その地域地域でこういった区民まつりをやるわけですから、苦情とか逆に来ちゃうと、そこの担当の人たちのモチベーションが下がるというわけじゃないですけれども、だんだん、だんだん勢いがなくなってきちゃうんじゃないかなというのを僕は危惧して、話はそれてしまうけれども、救急車が出るときの音もうるさいという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎クラブというところなんですけれども、冊子にもありますけれども、東京２１ｃクラブを参考にしたということなんですが、もう少し施設、事業のかかわりとかで、どういうものなのか、もう少し説明していただきたいのと、冊子の３ページのところで、「ものづくり産業の現状」というところで、「三極的構造が際立つ」ということで、中堅・大手の業務機能の集中、ファブレス企業の台頭、小規模下請工場群。","respondent":"金子産業振興課長","answer":"こういった形態につきましては今後も踏襲して、大手企業のご意見を伺いつつ、また中小企業のご意見等を伺いながら、どちらもそれぞれ発展していけるような、それで品川区のものづくり産業が発展していけるような、そういった方向で検討を進めたいと思っているところです。","voiceIndex":58,"id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"２点目の件なんですが、現時点での中小企業に対する、ものづくり企業に対するこの事業のどういう支援につながるのかという、現時点の認識で構わないんですけれども、区としての考え方のようなものは。","respondent":"金子産業振興課長","answer":"先ほどちょっと申し上げましたとおり、まだまだ、具体的な計画というのはこれから詰めていくので、非常に茫漠としたものがありますけれども、少なくともさまざまな情報交換の交流の拠点という中に、例えば大手企業しか入れなくて。","voiceIndex":60,"id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"あるいは、そのつくったものを検査していく、そういう施設というのがどういうふうになるのかなと思うんですけれども、これは、必要性のところで、大手メーカーのというようなところからの質問になっているんですけれども、内容はこれからという話なんですけれども、そういう中小企業の試作品だとか、あるいは検査機器の設置なんかも当然考えていくということになっているんでしょうか。","respondent":"金子産業振興課長","answer":"今後の検討によるというふうには考えております。","voiceIndex":62,"id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"わかりました。そういうところ、逆に切っていくというふうにするのかどうかというのは、企業の生き方になっていくと思うんです。本来であるともっと企業自身がそういう開発だとか、研究、試作品というのは、もっとそういう視野を持っていただいて、もっと力を入れてやっていく必要があるんじゃないかと思うんですけれども、いわゆる自治体の絡みというんですか、どこら辺までやるのか。","respondent":"金子産業振興課長","answer":"例えば賃料をその地域の相場に対して１００％でいくのか、７０％でいくのか、そういったことも今後の検討になりますので、そういう意味では１００％支援しないというわけではありませんけれども、何らかの形で、支援施設もどこまで支援していくかというのは。","voiceIndex":64,"id":"exchange-023"}]},{"id":"topic-04","title":"の「八都県市地球温暖化防止キャンペーンについて」","agenda":"の「八都県市地球温暖化防止キャンペーンについて」","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"国のほうでは「クールアース・デー」というふうに、６月９日の福田総理の記者会見、それから１７日の対策推進本部で正式決定をしたという報道を見たんですが、国のクールアース・デーとこの八都県市のキャンペーンの関係性を教えていただきたいと思います。それ以外の施設についての周知徹底といいますか、キャンペーンの呼びかけ、協力行動としてどういうふうにされるのか、以上お聞きします。","respondent":"工藤環境課長","answer":"その部分で、うちもそれに連動しまして、臨海部の野球場、テニスコートという形で連動したわけです。来年度以降どういった形でやるのかというのは、今後検討させていただきたいというふうに考えております。","voiceIndex":71,"id":"exchange-024"},{"speaker":"若林委員","kind":"確認","question":"答えが出ていないんですが、総合庁舎、中小企業センター以外の、多分地域センターとかというのを全体的に教えてほしいのと、確認で、2)のほうは、今まで利用予約のない施設の９時以降とか８時以降というのは消灯していなかったんですかということを。","respondent":"工藤環境課長","answer":"来年度以降は、どういうふうな形になるのかというのは今後検討したいというふうに思っております。","voiceIndex":73,"id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"区としても呼応していくということなんですが、これ、区民とか事業者への呼びかけの仕方、内容にもかかわってくるのかなと思うんですけれども、区としてはこのキャンペーンというのはどういうふうに、意義というか、もちろん純粋に、電気が消えれば電力が軽減され、ＣＯ２の排出が瞬間的には抑えられるというのはありますけれども、どういうふうに区としてはこの事業の意義をとらえて、呼応したというふうに。","respondent":"工藤環境課長","answer":"区としてのこの事業をどのように認識したかですけれども、このキャンペーン、やはりライトアップに慣れた私ども、区民、事業者、一人ひとりに対して、日ごろからいかに照明をしているかというものを実感していただくということと。","voiceIndex":75,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"事業者に対してこのキャンペーンというのはどのような効果をねらうというか、教えてください。","respondent":"工藤環境課長","answer":"事業者に対しましても、当然さまざまな部門で、事業部門、環境部門といろいろとあるわけですね。そういった中で、それぞれのやれる範囲でこういった部分を啓発するということで、十分効果があるものだというふうに思っております。","voiceIndex":77,"id":"exchange-027"},{"speaker":"若林委員","kind":"意見","question":"１件だけ。環境のうち、地球温暖化について、担当課長だったと思いますが、東京都でお話を聞く機会がありまして、北九州市の地球温暖化、環境も含めまして、先進的に取り組まれているというお話を聞きましたので、意見として出します。ある意味では東京都が一番今先行しているのかなと思いますが、具体的な事実として北九州市では取り組んでいるという具体的な事例がありましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"改めて日程表を見まして、例年、私たち会派として、都市問題会議、研修に行っておりまして、できれば１日ぐらい平日が、月曜日があるとありがたいなということだけ申し上げておきたいと思います。正副のほうでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-029"},{"speaker":"安藤委員","kind":"意見","question":"別に、今の調査項目が、ばあっとみんな上がっているというのであれば、また話は別なんですけれども、先に２泊３日ありきというふうにとらえ、区民の皆さんからもそういうふうに見えるんじゃないかと思うので、そこは柔軟に、この時点でそれが先にあるんだというふうにはならないんじゃないかなというような意見を持っているんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-030"},{"speaker":"若林委員","kind":"提案","question":"私も、東京もある意味では先進的と申し上げたのは、今回のＣＯ２削減のいわゆる対策をこれから具体的に進めていきましょうということが、環境建設委員会のほうで全会一致で可決されたということを指したまでであって、具体的に事業者に対してとか、また行政として、もう既に取り組んでいるということを、北九州市に関して指摘しましたので、間違いのないようにということと、また、２泊３日については。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-031"},{"speaker":"本多委員","kind":"意見","question":"行政視察につきまして、正副案というものを尊重したいと思いまして、あえて先ほど出しませんでしたが、基本的には所管事務調査の項目が決まりましたので、そういったものを充実していくんだろうなと思って、あえて発言は控えていたんですが、そういったところを委員会として充実させていくべきだと思います。行き先の都市、自治体ですとか、その日数については、正副委員長にお任せしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-032"}]},{"id":"topic-05","title":"の「所管質問について」","agenda":"の「所管質問について」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"福祉の後退政策だと思うんですね。そういった意味で、区としての現状、さっき言ったような健保の扶養家族の方について、現状を把握する必要があるんじゃないかと。健保の扶養家族の健診を国保とかに委託することも可能とされていると伺ったんですけれども、そういったさっきの現状を把握した上で、そうした対応をとる考えというのはあるのかどうかというのをちょっと聞きたいなと思いました。","respondent":"本城国保年金課長","answer":"１つは、各医療保険者、健康保険等ですが、そちらが特定の医療機関を指定して、そこに委託して実施する方法もありますが、そうしますといろいろな医療機関に個々に契約しなければいけないということになりまして。","voiceIndex":100,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"集合契約という話が、そういう手法があるんだという話で、ちょっと難しい話だったんですが、どれぐらいにめどが。もう少し後というのは、どれぐらいにめどがつくのかなと考えているのかということと、あと、難しいかもしれないですけれども、実際、実態把握という点ではどうですかね。","respondent":"本城国保年金課長","answer":"今、ご質問いただいた件ですが、基本的には、国保の立場からのお答えになってしまいますけれども、前段のどれぐらいかかるかということについては、今私どもとしては東京都の保険者協議会というところで場を持ちまして、保険者間の最終的な集合契約の調整をしているということで。","voiceIndex":102,"id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"その前段で、扶養者に限ったことと今理解をしているんですが、健診の通知の仕方というのは、要するに扶養者本人に直接されるのか、世帯主、健保側の加入者を通じてお知らせが行くのかというか、そこら辺を教えていただきたいと思います。","respondent":"本城国保年金課長","answer":"扶養者の関係の通知の仕方ですが、それにつきましては、専ら各医療保険者のほうで対応しているということになりますので、それぞれ千幾かある医療保険者、それぞれということだと思います。","voiceIndex":104,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"医師会側のいわゆる人員的なもの、いわゆる国保の特定健診以外に、ほかの保険者の中の扶養者も新たに加わってくるということでしょうから、それだけ人数が増えるわけですね。そこら辺、どのぐらい予想されて、医師会にできなくなるような負担といいますか、ということの医師会側の反応があれば、教えてください。","respondent":"本城国保年金課長","answer":"今、医師会側と代表保険者側との詳細のやりとり自体、私ども直にかかわっていないものですから、詳細は把握しているところではございませんが、そういった事務的なものも、確かにプラスでは出てくるんですが、ただ。","voiceIndex":106,"id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"この問題になるといつも質問したくなるんですけれども、１つ、今の区民健診と内容は同じにしましたということなんですけれども、とりあえず内容が同じというのはそれでいいんですけれども、やはり内容の充実といいますか、そういう点でどういうふうに考えているのかというのを１つ伺いたいのと、もう一つは、やはり今回特定健診あるいは保険指導、受診率や実施率がこういうふうに決まって。","respondent":"本城国保年金課長","answer":"それと、あと、これから目標達成に向けての方策につきましては種々あるかとは思いますが、先日も話題になったかと思うんですが、まずは、今回始まりました特定健診の大切さについてＰＲしていくとともに、指導自体、充実していくということが肝要だと考えているところです。","voiceIndex":108,"id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"受診率のところで、先ほど社会保険の家族の問題の質問があったんですが、受診率のほうでは、母数に社会保険の家族、こちらのほうはどういうふうに。入っているんでしょうか、入っていないんでしょうか。","respondent":"本城国保年金課長","answer":"あくまでも国保のほうの換算でいえば、社保の被扶養者はまたそちら側の対象になりますので、国保のほうにはカウントされていません。","voiceIndex":110,"id":"exchange-038"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"社会保険のほう、家族が入ってくる、入ってこないというのもありますけれども、少なくとも今時点では、現在の、平成２０年度３５％実施が行くかどうかというところなので、１年ごと５％、１０％アップというのは非常に大きなハードルだというふうに思うので、そこのところは考えられる対応をしっかりやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうのがもしあれば求めたいというのと、あと、以上のような関係から、「建築紛争予防条例」による説明会を行いますということで、そういう答弁があったんですが、いつ開催される予定なのかというのを具体的に聞きたいのと、あと、対象となる、「建築紛争予防条例」による説明会ですと、建物の高さ掛ける２倍の半径なので、あまり対象者がいないんじゃないかというふうに思うんですけれども。","respondent":"秋山資源循環推進課長","answer":"生活環境に関する内容を説明ということですけれども、内容につきましては、大気、騒音、振動等について、一般廃棄物の処理施設の基準に基づいて説明をしようと、各種の項目について説明をするということになっております。","voiceIndex":115,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後の件なんですが、私も、いや、これ、２つの施設がつくられる。寝屋川市ですか。もう一つは、４市が共同で運営する。都内の、都民の食の安全全体にもかかわってくるぐらいの勢いなんじゃないかなと思うんですけれども、そこ、不十分なままでゴーサインを出すのは非常によくないんじゃないかと思うので、少なくともそういったことをＪＲに求める必要があると思うんですが、いかがですか。","respondent":"秋山資源循環推進課長","answer":"先ほども申しましたけれども、今回の施設、「紛争予防条例」と、あと建築基準法の関係ということで、近隣住民、１００ｍ範囲の方に説明をするということで、法令ないしは条例の基準にのっとって説明会を行っておりますので、それ以外、それ以外と申しましょうか。","voiceIndex":117,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう姿勢だと、安全が保たれないんじゃないかなというふうにすごく思うんですけれども。別に品川区だけのことを考えていればいいというわけじゃ、もちろん考えではないでしょうし、もちろん、しかも、青果市場なわけですから、品川区民としたって、そこから物を買うわけですよね。だから、近隣にそういう施設がある中で、ＪＲにそういうことも求めないというのはちょっと理解できないんですけれども。","respondent":"秋山資源循環推進課長","answer":"それで、ＪＲに関しましても、全く説明会等何も説明をしなくてもいいというようなことをこちらが話したわけでもありませんし、今後も求めがあれば窓口をつくり、ＪＲのほうで適切に対応をとるようにということは、こちらのほうではお話しをしている。","voiceIndex":119,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"今、安藤委員のほうは、週刊誌の記事をもって、私、その内容、詳細わかりませんので、その部分については議論には加われないんですが、そこと同じだとか、同じでないとかいうところが、今、課長、理事者の中で答えられるのかどうかというのを一つ確認させていただきたいのと、さきの本質論である安全性ということについて、現状どういうふうに取り組まれているのかというのをまずはっきりさせないと。","respondent":"久保田環境清掃事業部長","answer":"それで、大田市場なんですけれども、大田市場については、あそこの場所から３５０ｍ離れているということで、その間に公園なんかも挟んでいますし、そういう点でいけば、かなり離れているので、直接的な影響はほとんどないだろうと私どもは判断していますので。","voiceIndex":121,"id":"exchange-043"},{"speaker":"若林委員","kind":"意見","question":"今のお話はよくわかりました。今の議論の中で払拭できていないのが、寝屋川市の問題です。委員の主張では同じなのだと。いずれにしても、八潮から大田市場の方々にという質疑がありましたので、安心感をもっていただいたほうがいいんじゃないかと思う。","respondent":"久保田環境清掃事業部長","answer":"したがって、これについては、当然今の、私どもが今ＪＲで予定しているああいう圧縮梱包の施設とは全く違うような環境条件が出ていますし、それについては、インターネットの情報だけで恐縮なんですけれども、安全は確保しているという施設長の主張ではあります。","voiceIndex":123,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"それを元にしているわけですから、それで、インターネットでも今情報がすぐわかるような状況なので、寝屋川市ですか、そこでこれだけの大きな問題になっているというのを踏まえて、なおかつ、ただの施設だったら、まあ、いいんですけれども、食料品の施設が近隣に、３５０ｍといったら全然、すぐ、近いと思いますけれどもね、私は。ですから、そこはよく調べる必要があるんじゃないかと。","respondent":"久保田環境清掃事業部長","answer":"先ほどから雑誌を元にしていろいろご主張があるんですけれども、私どももそれが正しいかどうかというのはなかなか確認できないので、発言を控えさせていただいているわけなんです。","voiceIndex":125,"id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"今回のような容器包装をリサイクルする過程で、やはりプラスチック自体が不安定な物質が混ざっていて、しかもそこに添加剤もいっぱい入っているやつを圧縮する過程でいろいろな、未知数な部分、わからない、未解明な部分でいろいろ影響が、どんな影響が出るかわからないという面もあるわけで、だから、リサイクルはリデュース、リユース、リサイクルなわけであって、リサイクル万能というだけにとらえて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":55990,"voices":139}},{"id":"h20-20080624-7","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"厚生委員会","time":"午前１０時０４分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"請願のところなんですけれども、昨日もかなり重い方の請願が出ていましたけれども、この方もかなり重度な方だと思うんですけれども、昨日、こういった重度で区内の方は７名いらっしゃるということだったんですけれども、その中に含まれていたお子さんはどういう状態なのか、把握をされていらっしゃるところなのか、個人的なことはいいんですが、それをまずお伺いします。","respondent":"高橋障害者福祉課長","answer":"昨日申し上げたのは、重度で人工呼吸器をつけている方ということなので、現在、この方についてはつけておりませんので、対象には入っておりません。","voiceIndex":8,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目なんですけれども、ご説明をいただいたところによると、在宅で常時、車いすの外出支援ということでは、これは成人の方という要件ととらえていいんでしょうか。その点と、あと車いす以外は全くこの要件に入っていないのか。この方の場合は別途ストレッチャーの使用に広げていただきたいということなので、その辺については、今までこういった例は全くないのかどうか、その辺を聞かせてください。","respondent":"高橋障害者福祉課長","answer":"車いすにもいろいろありますが、基本的には車いすとして、一般的に車いすと言われているものについては対象になっていますので、ストレッチャーと言われちゃうと、この部分については対象外になりますが、リクライニング式の車いすであれば車いすという扱いですので。","voiceIndex":10,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"この場合はベッドとはっきり書いてあるので、多分車いすの範疇では間に合わない方なのかなと思うんですけれども、先ほどはストレッチャーに関してはリフトつきの寝台タクシーのご利用をということだったんですけれども、なかなかそういうふうになってしまうと、例えば病院に行くときに利用しにくい、予約が取れなかったりとか、この辺で購入と改造の費用を。","respondent":"高橋障害者福祉課長","answer":"実際上、車を購入するとなりますと、一応車を購入し、それを１度陸運局に通して、その後、改造を通して、またそこのところで陸運局のところということで特殊車両として認められるので、相当の時間と手間がかかるのと、お金がかかるということなので、現在については。","voiceIndex":12,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"こういうお子さんは日ごろのお医者さんの管理のもとでないと予防注射なんかも受けられないと思うんですが、その辺はどうなんでしょうか。","respondent":"山岡健康課長","answer":"ただまれなケースで、例外的にそういう医療機関がないとは言えないと思いますけれども、そのケースについては、個別にご相談に応じるということになろうかと思います。めったにないケースだと思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"現状において行われているのか、あとインフルエンザなんかは６５歳以上の方だけなんですけれども、多分体の弱い方というのは、ちょっとした病気でも重篤になったりということにおいては、受けられる予防注射は事前に病気を予防するという意味ですごく大事だと思うので、こういった難病を抱えていらっしゃる方なんかは、一般のお子さんよりももっと枠を拡大して受けられる対象が広がってほしいなと思いますが。","respondent":"山岡健康課長","answer":"一律に考えるのは難しいかなと思っているところです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろな手当を先ほどご説明いただいたんですけれども、この辺で所得制限のことについてお伺いしたいんですが、先ほど区と都と国の制度の説明をしていただいたんですけれども、これは全部所得制限がついていたんでしたっけ。なので、制度はあるけれども受けられない人がいるという認識を持っているんですが、どの程度の方が先ほどの制度を受けられているのか、割合的にはどうなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"ほとんどのところが３６０万円、障害児福祉手当も３６０万円、区のほうの障害者福祉手当の３６０万円程度です。それから特別児童扶養手当については、扶養がなければ４５９万６,０００円、児童育成手当については３６０万円という形になっております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害の重い方のお世話というのは、家族の方に結構重くのしかかっていて、多分ここのご家庭も、１人でつきっきりで生活を支えていらっしゃると思うんですね。横浜市というところで他にもと書いてあるんですけれども、お伺いしたいんですが、この横浜市のこととか他都市のことで把握をしていらっしゃるところがありましたら、教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"横浜市と書いておりますが、神奈川県ということで調べさせていただいたところ、横浜市の場合は年額６万円出ております。それと県のところでも年額６万円ということで、東京都が対象者の部分、それから金額の部分につきましても、かなりよろしいのではないかと考えています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味では、明らかに障害があって援助が必要なのに、手帳を得られなかったりとかいろいろなことでその先に進まなくて、受けられないまま亡くなってしまうケースもあると伺ったんですね。そういった面では、わかっている障害だったら速やかに手続をする必要があると思うんですけれども、その辺はいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"手当のところですが、神奈川県よりかなりいいという金額ですが、これはあくまでも東京都が条例で行っているものなので、東京都の手帳のあるなしにかかわらずですので、申請を出して、東京都の心身障害者福祉センターが診断した上で交付しているものですので。","voiceIndex":22,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"請願の１１号のほう、車いすの自動車の関係で何点か伺いたいと思います。このケースの場合も踏まえ、現状の、確かに２台だったと思うんですが、頻度と台数を考えて、今、こういうケースの方が病院に通院等で利用する際にいっぱいであるとか、あるいはすぐ利用がほぼできるというか、その辺の見通しを伺わせてください。","respondent":"高橋障害者福祉課長","answer":"改造というのは、車いすが乗せられるように、自分の所有している車を改造するのに１５万円まで出していますので、３０万円と１５万円の金額の助成金となっておりますので、見積もりがそれより以下だったらどうだとかというようなことでは。","voiceIndex":24,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"幾つか質問させていただきたいと思います。先ほど飯沼委員のほうからもあったんですけれども、車いすがよくてストレッチャーはだめだという理由がどうしてもわからないんですね。質問からいきましょう。車いすの改造あるいは購入の助成、今、年間何件ぐらい利用がありますか。","respondent":"高橋障害者福祉課長","answer":"実際上の改造ですが、購入の補助金ですが、平成１７年度につきましては、両方で４件、平成１８年度につきましては２件、平成１９年度については１件を助成しております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"私はこれは車いす同様、金額が車いすへの助成額と同じぐらいの割合で出せるかどうかは別として、やはりストレッチャーも外出援助の１つとして助成の対象に加えるのが、自然な発想ではないかと思います。２つ目なんですけれども、ちょっと確認させていただきたいんですけれども、区独自の助成であるおたふく風邪と水ぼうそう、これについては区外の指定機関でも助成が受けられるということでしょうか。","respondent":"山岡健康課長","answer":"これは品川区の独自の助成ですので、基本的には品川区内の医療機関でやっていただきます。ほかのところで受けた場合についての仕組みというのは、現状のところではございません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"阿部委員","kind":"意見","question":"この公費の部分、つまりＢＣＧからポリオまでの予防接種というのは、まさにこれは国民全体、子どもたちが皆受けることで公衆衛生を維持している部分もありますので、これは区外の医療機関でも当然受けられるべきである。にもかかわらず、例えばこの方がそのことを知らないまま来られてしまったことに１つ大きな問題があると思います。つまりこの上４つについては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"請願の４つが既に公費負担されるということを、この方が重度であることが区で把握する機会はいくらでもあったはずなのに、その情報が１度もこの方のところに届かなかったということなんですね。あるいは逆に区としては、重度のお子さんの場合にはどのようなサービスをし得るのか、まとめて保護者の方に説明する機会があるのかないのか、現状を教えていただきたいと思います。","respondent":"山岡健康課長","answer":"予防接種のご案内についてだけまずご答弁申し上げますと、それぞれの時期に、難病の方であろうとなかろうと、対象になるお子さんすべてに通知を差し上げているところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"確かにそうだと思います。重たい状況の子どもは必ずしもその時期までに注射が可能になるとは限りません。逆にどうしても区内で受けろというとそれは危険なことになってしまうわけで、主治医の判断で受けるというのが当然のことだと思いますが、それだと助成の利益が受けられないというのは、こういう特殊な状況にある子どもにとっては酷なことではないかと思いますが、その辺の考えはいかがですか。","respondent":"山岡健康課長","answer":"ございませんけれども、特殊事情がありますれば、ご相談いただければ、例えば何らかの方法で助成をするということは可能かと思われますので、一たん自費で受けていただいて、後で償還払いといったような方法もありますので、その辺はご相談いただければと考えております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"であれば、重度の子どもたちがいるとわかった時点で、予防接種もこういう扱いができますよと区のほうから情報提供するような、これは予防接種だけじゃないと思います。重度の子なら仕組みに乗らない部分というのが幾つも項目があると思いますので、一覧表をつくっておけば、それで説明すれば１回ですべてのことが済むわけですから、そういったやり方もあるかと思います。一応一言お願いします。","respondent":"山岡健康課長","answer":"今のご意見を参考にしながら、個々の通知等については考えていきたいと考えています。","voiceIndex":36,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"５万円ですね。これはすぐにというわけにはいかないかもしれませんけれども、所得制限を区として見直しをする可能性があるのかどうかというのがまず１点です。自治体によっては１歳未満でも手帳を取れた例があると聞いておりますが、基本的には国の問題、都の問題であるということは認識しているんですけれども、区として、この年齢についてもう少し問題意識を持てないか、その辺のお考えをお伺いします。","respondent":"高橋障害者福祉課長","answer":"手帳を１歳未満でも取れた方もほかにはあると聞いているということなんですが、手帳そのものの申請につきましては、先ほども申し上げたとおり、区としてそれを受け付けないとかということではございませんので、申請があれば必ず東京都のほうに送付し。","voiceIndex":38,"id":"exchange-016"},{"speaker":"阿部委員","kind":"意見","question":"所得制限については撤廃しろというお話をしたのではなくて、もう少し上限を緩和できないかということでお話をさせていただきました。手帳については、区で判断できないというのは重々承知しておりますので、ただいろいろな機会のときに、都に問題意識を投げかけることはできないかという意味です。","respondent":"高橋障害者福祉課長","answer":"先ほどの所得制限の緩和につきましても、この基準を設けましていろいろなところを運営していますので、独自に緩和するということは現時点では考えることは難しいかと思います。","voiceIndex":40,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"この改造につきましても、車いすを常用で利用している方だけということなんですけれども、例えばこのリフト寝台つき福祉タクシーを通院で使うとか、またたまにはどこか違う景色でも子どもに見せようかとか、いろいろな使い方があると思うんですけれども、このタクシーの用途と、あとはこちらのリフトつきの車いすの購入・改造費、助成されておりますけれども、こちらのほうの用途と。","respondent":"高橋障害者福祉課長","answer":"車いすの助成のところの利用の目的、それからストレッチャーを使用したリフト寝台つきタクシーの目的は特に制限しておりませんので、使い道についてはそれぞれの利用の方が判断してご利用の申し込みをしていると思います。","voiceIndex":42,"id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"用途に対しては制限がないということで伺いました。それと手当拡充についてですけれども、こちらは陳情第１３号になりますけれども、所得制限の話も出ました。手帳につきましては都の制度ということで、これは区としては淡々とやるというお話だったと思いますけれども、これについても何かしらの要望といったらおかしいんですけれども、全く出せないのかどうか、この点を１点だけお伺いいたします。","respondent":"高橋障害者福祉課長","answer":"この東京都の基準につきましては、厚生労働省、それから都道府県は同一に行っているもので、機会があれば発言しますけれども、今のところそういう発言する機会はございませんので、その時点で、もしいろいろな条件緩和ということになれば発言はしたいと思いますが。","voiceIndex":44,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"確認","question":"陳情の部分からいきます。陳情第１４号については東京都の範囲ということで、区の判断は難しいのかなと。障害者手当の申請条件緩和は確かに厳しいなという状況はわかりましたけれども、手当拡充に関しての確認なんですけれども、先ほど所得制限が３６０万円という数字が出たんですけれども、これは３６０万円は手取り、それとも例えば住民税の基準とか、そこら辺をちょっと確認したい。","respondent":"高橋障害者福祉課長","answer":"あくまでも所得ですので、収入金額ではございませんで、いろいろなものを全部控除した上での所得ということになりますので、その辺については、この基準表をいろいろなもの、基礎年金も含めまして。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、３６０万円じゃなくて、もっと実際はお手元には増えていると判断をしているということでよろしいですね。請願の件に関してですけれども、逆にリフトつき寝台タクシーの利用度が非常に低いなという話になってしまう。利用料はそっくりそのまま払うということなんですか。","respondent":"高橋障害者福祉課長","answer":"それとタクシーの利用件数ですが、年間で２,６５７件を利用しているもので、寝台のみで申し上げたのが３人から９人ということになりますが、そのほかに車いすのみで利用している方もおりますので、その辺についてはプラスしていただければと考えております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用件数はこの事務事業には１,７５９件と出ているから、その数字からちょっと今、お聞きしたんだけれども、ちょっと数字が、全体がちょっと疑問もあったんだけれども。","respondent":"高橋障害者福祉課長","answer":"中古車でこういう車いすが乗る車は、流通しているかどうかというのは、申しわけないんですが、私はつかんでおりませんので。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ある程度意見のほうにもなるんだけれども、この請願、陳情がどこまで一般的な話かなというのを非常に感じているんですね。個人の請願なのか、それとも全体的な制度を変えてくれという請願なのか、ちょっとその辺が非常につかみにくい状況だと私どもは判断しているんですけれども、ちょっとその辺も踏まえて、これは意見で終わりますけれども、質問ではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"堺委員","kind":"確認","question":"これについての利用実績の中で、先ほども鈴木真澄委員からご指摘がありましたような事務事業概要に、確かに平成１７年、平成１８年、平成１９年の利用件数と実績が出ていたんですが、先ほどある方のご質問に対する答弁では、現在、このリフト寝台つき福祉タクシーの利用は、月平均すると大体３人から９人ですよということだったかなと思うんですが。","respondent":"高橋障害者福祉課長","answer":"それと手帳のところにつきましては、確認ということかと思いますが、あくまでも手帳につきましては、指定医が判断した上で私どもが東京都のほうに経由事務としまして申請し、東京都が判定医により判定した段階で手帳が交付されるですので。","voiceIndex":53,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"所得制限がないのが一番いいんでしょうけれども、ただ先ほどのご説明でいくと、平均すると重度の方が大体１４万６３０円交付されているようなんですけれども、こういう障害をお持ちの方から見ると、目に見えない経費というんでしょうかね、医療費については難病ですから、裏のほうに東京都が実施している難病治療の医療費助成制度（小児慢性疾患）は存在しているがということで。","respondent":"高橋障害者福祉課長","answer":"いろいろなところで医療にかかわるものについてのいろいろな薬品とか医療品というのがありますが、医者が必要ということになれば、今、子どもすこやか医療費助成の中で可能かと思いますので、その辺については、どういうものが必要かどうかというのは私のほうは判断できませんが。","voiceIndex":55,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この手当の所得制限の、特に配偶者や扶養義務者の所得制限の緩和というのは本当に必要だと思うんですけれども、それと同時に、この方の場合はちょっとわかりませんけれども、このさまざまな手当とかも含めての制度を知らないために受けられないということはないのかと、先ほどの予防接種のこともありましたけれども、そこのところをちょっと心配しているところなんですけれども。","respondent":"高橋障害者福祉課長","answer":"お知らせの部分ですが、手帳申請時に一覧表がございまして、その中で一つ一つにご本人に説明をさせていただいている状況であります。","voiceIndex":57,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"手帳申請時に説明をしていただく、このしおりもそのときに全員に渡されて、ご覧くださいということでお渡しされていると思うんですけれども、これってなかなか一般の人がばっと見てもわかりにくいということもありますので、保健師さんもずっとかかわられているということもあると思いますので、そこら辺のところが、受けられる制度が受けられないということがないというところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"請願第１１号についてなんですけれども、さっき聞き落とした点もあってちょっと失敗したんですけれども、非常に難しい判断をしています。今回、結論を出したほうがいいのか。ですから、継続が自民党としての考え方と思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-028"},{"speaker":"堺委員","kind":"質問","question":"請願第１１号については、判断が非常に。この2)の予防接種ですかね。区外であっても指定医ならばできるんだということなので、ただこの請願者の方はその辺の情報を知り得なかったからこういうふうに出されてきたのかなと思いますので、その辺の周知徹底については、区側のほうにもご努力をお願いしたいなと意見を申し上げておきたいと思います。ですから、この請願は分けていいんでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-029"},{"speaker":"阿部委員","kind":"意見","question":"方向性としては賛成なんですけれども、いろいろと重要な問題を含んでいると思いますので、もう少ししつこく話をしたいと考えていますので、そういう意味で今回は継続で、もう１回やりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"陳情第１３号につきましては、先ほど所得制限の緩和という質問が随分出たんですけれども、本件に対しては、拡充に関して、これは新設ですよね。陳情１４号につきましては、これは東京都の事務ということで、現状、区のほうで対応する部分ではないということで、これも願意に沿いがたいということで、両方とも不採択という答です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"堺委員","kind":"質問・要望","question":"陳情第１４号につきましては、これは東京都の事業であるということから、区がどうこうするものではないかもしれませんが、区として都のほうに意見を上げられる際には、何らかの形で制度がよくなることについてはまた改善点があれば、ご意見として申し上げていただきたいなと思いますが、まず１点、３歳未満の方でも、先ほど答弁いただきましたように、手帳の交付については可能性がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"意見","question":"陳情２件ですけれども、今日は３つの請願、陳情が出されましたけれども、この全部をとらえたところで、重度の方の障害児・者の方々の実態をもっとしっかりとつかんで、トータルでの支援の充実が必要であると深く受けとめました。ぜひ趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問・要望","question":"そこに現場があるからそこに生の声があって、そこから制度をつくっていくのが基本であるということを考えますと、都の制度だから、国の制度だから区は物を言いませんというのではなくて、現場の声こそ制度の改善に生かしてほしいと、常にそういうパイプというのをむしろ区のほうで場を見つけて、区の中で実際に福祉の現場で矛盾を感じたところは、どんどん都にも国にも言っていく姿勢。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"幾つかお伺いします。第７号といいますか、最初のなんですけれども、産業振興課のホームページが利用可能である。ただし広告扱いで有料ということだったんですけれども、大体どのくらいのものなんですか。普通に広告を出すぐらいの金額になるのか、それとももう少し安いのかなと。その金額を教えていただきたいと思います。技術支援教育訓練給付金事業、こっちのほうの実績を教えていただければと思います。","respondent":"諸岡児童課長","answer":"３番目の自立支援給付金の実績ですが、平成１９年度の支給実績で申し上げますと、これは申し込みと支給が、受講期間がありますので若干タイムラグがございまして、ホームヘルパーの２級を受けられた方が２名ですね。","voiceIndex":87,"id":"exchange-035"},{"speaker":"阿部委員","kind":"確認","question":"今の支給実績なんでけれども、支給年度で構いませんので、人数で何人なのかなかというのが、平成１９年、１８年ぐらいで、今、人数を言われなかったのは１人ということなんでしょうか。数字で確認させていただければと思います。どうなんでしょうか。","respondent":"諸岡児童課長","answer":"自立支援給付金事業実績ですが、平成１９年度は５名です。この制度は平成１７年度から開始されておりますが、平成１７年度は制度開始ということで、まだＰＲも十分ではないということで少かったんですが、だんだん周知されてきまして増えてきております。","voiceIndex":89,"id":"exchange-036"},{"speaker":"阿部委員","kind":"意見","question":"就業アドバイスについては、個別の状況を勘案してということで、そのことをぜひ強化していただければと思います。それから最初に聞き忘れました、実数を正確につかむことは実は意外に困難と聞いているんですけれども、区内に今、ひとり親家庭はどのくらいいらっしゃるのか、その中で計１０人の利用というのをどのように評価されているかということをお聞かせください。","respondent":"諸岡児童課長","answer":"実際やってみたいけれども、いざやるとなると、いろいろな事情があってちょっと躊躇してしまうのかなということもあります。ただ、だんだん増えてきている傾向でございまして、これは今後も十分ＰＲをしながら、丁寧な窓口対応も含めて進めてまいりたいと考えています。","voiceIndex":91,"id":"exchange-037"},{"speaker":"阿部委員","kind":"質問・要望","question":"国の制度ですので、根幹をどうこうということは難しいかと思うんですけれども、今、ＰＲともおっしゃっておりましたが、ぜひ事業の促進に努めていただきたいと思います。１個聞き落としておりました。ご本人のご希望で、あいているほうがいいとか、しめているほうがいいとか、そのようなことというのは、形の上ではできるかなと思うんですが、そういうお考えはありますか。","respondent":"志村生活福祉課長","answer":"これは非常に特異な例です。ですから、逆に言うと、あそこで面接をしなきゃだめなのよというわけでもありませんので、それはお申し出いただければそのような配慮というか、一定のできる範囲のことはしていきたいなと考えております。","voiceIndex":93,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"別に外に面して風を入れる窓ではなくて、ドアに見通せるような小窓をつけるという考え方です。伝わっていましたでしょうか。要は第三者の視線が入り得る構造にするということです。ドアのところですね。","respondent":"志村生活福祉課長","answer":"ちょっとこの辺が逆に言うと不十分じゃないかというケースもあります。声が聞こえちゃうということもあるんですけれども、この辺が許容の範囲かなと思ってやっておりますので、あとは個別の対応をさせていただきたいと思います。","voiceIndex":95,"id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"４点の項目に共通して伺いたいと思います。ちょっと確認で伺います。そういった中では、これまでこういったやりとりが個別であったのかどうか、おそらくそこまで把握は難しいかと思うんですが、何回か引き続きやりとりをして、どうしてもという中での陳情項目なのか、ちょっとその点を確認したいのが１つあります。","respondent":"諸岡児童課長","answer":"実際にご相談があったかどうかにつきまして、相談の秘密ということもございまして、個人情報ですので、私ども相談があればきちんと相談記録に基づき記録をしていますが、それについてはちょっとご容赦いただきたいと考えています。","voiceIndex":97,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺において、ここにはいろいろ書いてあるんですけれども、就職活動からもう一歩進んで、働く応援的なところで何か求められていると思うので、この辺何か工夫はないのかなと思うのが１つと、２点目のところは、事業助成金制度というのはないけれども、事業開始資金のご紹介があったんですが、無利子で貸すというこの制度がどのくらい活用されているのか、３年くらいの間の利用状況を教えてほしいのと。","respondent":"諸岡児童課長","answer":"それから最後の会計士とか税理士の顧問料の一部負担ということになりますと、なかなかひとり親の支援という面からはしづらいといいますか、さまざまなひとり親については母子手当と言われるような児童扶養手当とか、経済的な支援をしてきておりますので。","voiceIndex":99,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目のところの事業開始資金が平成１９年に１件、額的にはかなり大きな額でこういうのが受けられたら、仕事を始める意味ですごい助かると思うんですが、この件数がなかなかいっていないというあたりがどういうところなのかなというのを聞かせていただきたいのと、あと陳情第８号のほうにいきますけれども、これの最初のほうに、さっきご答弁の中に、陳情第８号のところは国の制度で。","respondent":"諸岡児童課長","answer":"そのようなきめ細かな対応を行わせていただいているところです。","voiceIndex":101,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"陳情第９号のほうにいきますけれども、まず１点目のところは、先ほどここに書かれているようなことはありませんというご答弁があったんですが、なかなかやりとりのところはデリケートなところがあると思うんですけれども、ここにも誤解印象を受けたためと書かれているので、誤解を招かない対応をしていただきたいなと、これはなかなかやりとりの問題で難しいと思っていますけれども。","respondent":"諸岡児童課長","answer":"制度的には、就職をしない場合は受け付けできないということはございません。ただ、アドバイスの中にそのような受け取られ方をしたのかなと考えています。その辺の言い方につきましては、私ども今後十分注意していきたいなと考えています。","voiceIndex":105,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"よろしくお願いします。この２と３のところにいろいろ細かく書かれているんですけれども、先ほどもすごく件数が多いとか、いろいろご説明いただいたんですが、わかりやすい載せ方というか、例えば事例か何かを幾つか載せるとか、その辺の工夫をしていただくことで、理解がもうちょっと進むというあたりがあるんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"諸岡児童課長","answer":"なかなか数が多くて、１,９００機関の５,８００講座、しかもこの講座が日々動いておりまして、ご承知のように、大手の英会話学校が経営破綻に陥りまして、そういったことでこの指定講座を受けていたのも一切指定取り消しになったりとか、あるいは新たに指定をされた講座。","voiceIndex":107,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなんですけれども、過去の実績というか、こういうのがこれだけ活用されていますという件数を出すこと自体は困難ですか。支給されているわかりやすい事例をこうやって載せるというのは、それほど困難ではないような気がするんですが、いかがでしょうか。","respondent":"諸岡児童課長","answer":"ただ、やはり窓口での十分な説明をするということが基本かなと考えています。","voiceIndex":109,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"その後に調査をする。そこについてここでおっしゃっているのではないかなと思うので、原則的には申請者が見えたら申請書を書くという、その行為をきちんと受けとめていかなくてはいけないなと思うんですが、よくこの間、聞くと、相談件数と、多分カウントされているのは来ていろいろお話を伺った相談件数、その中で何件申請になったのかというのを、ちょっと具体的にそこも含めてお伺いしたいと思うんですね。","respondent":"志村生活福祉課長","answer":"先ほど申し上げたとおり、年間で２,０００件ほどの相談といいますか、記録に残っているのがこれだけです。その中でといいますか、平成１９年度、生活保護の開始になった者が５３１件です。","voiceIndex":111,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"セーフティーネットというご説明もさっきありましたけれども、ぎりぎりのところに行って、拒否をしていないのかもしれないけれども、そういう受けとめをしてしまうという、そういったぎりぎりの状況の中であそこの窓口に来るんだというあたりを、職員の方は重々、わかっているとは思うんですけれども、そこは本当にしっかりと受けとめてほしいなと思うのと、それから。","respondent":"志村生活福祉課長","answer":"職員の研修ですけれども、一番身近なところでは、実は明日と明後日、これは別にこの委員会があるから予定したわけではありませんが、実は明日、明後日は、私どもの全課職員、７１名ですけれども、対象に、２日間にわたりまして、防災シアターをお借りして。","voiceIndex":113,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実はの話を聞くまでが大変と、本当にいろいろな方が相談に見えるので、その中から相談の本質、真実を見つけ出すのはすごく大変で、ご苦労されていらっしゃると思うんですが、研修のところにぜひ力を入れていただきたいなと思うのと、最後に１つだけ、２のところに職員の方は加筆修正が容易な鉛筆でと、この鉛筆で相談内容が書かれていることがあるのかどうか、もしあるとしたら、やはりこれはボールペンとか。","respondent":"志村生活福祉課長","answer":"それに基づいて、先ほど申し上げたとおり、年１回の東京都の指導検査、それから国あるいは会計検査院等の検査には、その公文書を出して検査を受けてまいりますので、そのようなご心配はないと、先ほど申し上げたのはこの内容です。","voiceIndex":115,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今までの質疑の中でもその説明とそんなに変わらない答ばかりが出ているような気がしていますので、全体的な聞き方をしますけれども、このケースの陳情に対して、この方も個別に陳情を出していらっしゃるんですけれども、全体的に、例えば母子家庭の方から同じようなご相談事というのは、かなり役所にはあるんですか。それともこんなケースはレアケースだよという、どちらで判断したらいいのか。","respondent":"諸岡児童課長","answer":"今回の陳情のようなご意見はほとんど初めてお受けするようなことですね。私どもこれを聞きまして、これからさらに工夫していかなければならない点もあるかと思いますけれども、今回につきましては、この陳情については、今までたび重ねてあったようなご意見ではないです。","voiceIndex":117,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ひとり親だから認めるよという問題ではないなと私は、これは意見のほうです。例えばその下に行っても、事業助成制度、助成を個人にしていくのは、ひとり親家庭に対する本当の支援なのかというのも非常に疑問を感じています。もうこれ以上質問ということではなくて、ある程度自分の意見も、この全体をまとめていくでしょうから、意見ということで述べさせてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-050"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらの第１号と、あと陳情第１０号のすべての項目もそうなんですけれども、先ほど飯沼委員も言われました研修ということについては、ぜひともある意味では重点的に進めていただきたいのと、それともう１つなんですけれども、この研修の中ではビデオを見るというような、ある意味では一方通行のままだと思うんですけれども、例えばある人が生活相談に来たという前提のもとで。","respondent":"諸岡児童課長","answer":"それを受けていただいて、それにパスして、入校が決まった段階で訓練手当の説明をして受給していただくという形になっていると聞いております。なお、母子家庭の方には母子家庭の優先枠などもあると聞いておりますので、まずは相談です。","voiceIndex":120,"id":"exchange-051"},{"speaker":"堺委員","kind":"意見","question":"この件につきましては、今、自民党の鈴木委員がおっしゃっておられましたように、今日結論を出すということで、採決方法については４件一括ではなくて、それぞれ個別に出すべきだろうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"意見","question":"個別に言います。全体的にこの方のおっしゃっている内容は、母子家庭ということでお１人で大変だということは十分承知した上での答ですが、もう１件、第１０号のほうの生活保護制度につきましても、理事者の説明を聞いておりまして、十分対応なさっているという点を考えると、この陳情項目につきましては、もう既に対応している部分ということで、不採択ということでいきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-053"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目については、助成金制度、貸付金ではないということですが、おっしゃっている意味合いも理解できないでもないんですが、基本的に事務事業概要等を見ましても、母子家庭等の資金の融資あっ旋というんでしょうか。申請が可能である資格の種類など、今以上に明確に公開、説明、記載を求めるとおっしゃっておられますが、さっき５,８００件ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"陳情第１０号に関しては、特にイのところで、まず申請を受け付けるという、職員の方は一生懸命やってくださっていることは承知の上なんですが、仕組みのところで、まずしっかりと申請書を希望する人にはすぐ書けるという状況をつくっていただいて、それから詳しく中に入るというところは、前から私たちもお願いしているところなので、特にこの辺の改善を求めたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-055"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただこの３つ、陳情第７号、第８号、第９号に関しましては、それぞれの陳情事項につきましては、ちょっとどうかなと思うものもあるんですけれども、そこに共通しているのは、結局はひとり親家庭の方のそれぞれの能力に応じて就職をするように道をつけてもらい、また、それぞれの能力を伸ばしてもらえるような制度を整えてほしい、そういう思いから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-056"},{"speaker":"阿部委員","kind":"質問・要望","question":"ですので、この相談を受けるときに、できるだけ早い段階で、これだけのことはこちらからも聞いていくんだということをお伝えしてわかってもらうということをしつつ、相談をしていくということも必要ではないかと、そういったことも含めて実施していただきたいという思いを込めて、この陳情については願意に沿いがたいという形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-057"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"ちょっと頭の中で整理できていなくて、教えてください。これは精神障害者の通所施設も入るんですか。精神障害者の通所施設というのはあるんでしたっけ。それが対象に入っているかどうか教えてください。","respondent":"高橋障害者福祉課長","answer":"精神障害者の通所施設は区内にありません。現在あるかもめ工房のことだと思うんですが、共同作業所ということで、現在、交通費等につきましては個別に出ております。","voiceIndex":145,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが受けられていて、今回新しく制度になったとき、不利益になる人がいないのかどうか、ちょっとその辺を教えてください。","respondent":"高橋障害者福祉課長","answer":"区内通所の人数が３１２人おります。一般の区分が入っているのが１９７人、低所得に生活保護までを含めますと１１５人という区分割合になりまして、今度世帯の変更になりますと個人単位となります。","voiceIndex":147,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"９割のところはわかりました。でも結構障害を持っていらっしゃる方でこの９割通うのは、通わないとこの３,０００円はいただけないということですよね。障害者本人の方を対象にということで、やっとこうなったなと思うんですけれども、その後の括弧のところがわからないんですけれども、本人と同一世帯の配偶者の所得で判断ということは、結婚をしていらっしゃる方は夫婦でという理解でいいんでしょうか。","respondent":"高橋障害者福祉課長","answer":"1)の部分につきましては、ご本人と配偶者ということで、ご夫婦の場合は２人の部分となります。","voiceIndex":149,"id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この利用料なんですけれども、全員が低所得者になるということで、１,５００円になるということなんですけれども、そうすると、今までは利用者実費負担が最大で、低所得者の場合は７５０円から１,５００円になるということでいいんでしょうか。","respondent":"高橋障害者福祉課長","answer":"予算額につきましては、あくまでも負担軽減の中の施策の１つと考えていますので、そこの中で十分充当できると考えております。全体の予算額ですと１,８００万円ちょっとをうちのほうでこの予算額を見込んでおりますので、その中で十分やりくりできるのかなと考えております。","voiceIndex":151,"id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"知的の方は欠席があまりないということなんですけれども、知的障害者の更生施設のほうは結構大変なんじゃないかという話もお聞きしたんですけれども、ここら辺のところで体調を崩して行けなかったりするとこの３,０００円が出ないということが、その体調を崩しやすい子どもさんにとって、この９割というのがかなり本人の状況からすると厳しいということがあるんじゃないかなという気がするんですけれども。","respondent":"高橋障害者福祉課長","answer":"利用料につきましては、その人の出勤の状況に応じて違うので、３,０００円を補助して上限まで使えば７５０円ということになりますが、それ以下の方もおりますので、その辺についてはその人個人の計算をしないとちょっとわかりませんので。","voiceIndex":153,"id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ただそれが９割以上行けば、逆にさらに３,０００円が支援金として出るので、９割以上行った方については、差し引き負担としては逆にプラスになるというところになるけれども、９割行かない方は、今までは最大７５０円で済んでいたものが１,５００円になるということで、そういう理解でいいんでしょうかということなんです。","respondent":"高橋障害者福祉課長","answer":"委員のおっしゃるとおり、そういうことになります。","voiceIndex":155,"id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと頑張って９割行けるという方は、そして頑張って９割出ている方というのもすごくたくさんいらっしゃると思うんですけれども、障害の程度に合わせて、行けないという場合があった場合は出ないというところは、またちょっとその障害の方に合わせた対応をぜひ検討していただけたらということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-064"}]},{"id":"topic-03","title":"の５、その他を議題に供します。 (1) 所管質問","agenda":"の５、その他を議題に供します。 (1) 所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園の待機児童の解消にあたって、ご答弁の中で具体的に公・私立の保育園数と解消人数の数字が述べられていたので、ぜひその中身を具体化されている部分において具体的にお知らせいただきたいのと、今、長期計画が検討中なんですけれども、中期的な、また短期的なこの待機児解消の計画がどのように進んで、どこを見たらそれがわかるのかというのも教えていただきたいと思います。","respondent":"小林保育課長","answer":"今、予定しておりますのは、既にご報告いたしましたが、今年度１２月を目途に学研の認定子ども園を五反田に開所し、おおむね６０人強という形で予定しておりますほか、ウエルカムセンター原の私立認可保育園、そして、今後は平成２２年。","voiceIndex":163,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"４つの計画が示されましたけれども、今年１０月の学研の認定子ども園というのは、これは認可保育園、認可幼稚園ですか。中身的にこれは、くくり方をちょっと教えてください。","respondent":"小林保育課長","answer":"学研の認定子ども園につきましては、保育園型の施設になります。したがいまして、基礎となりますところは認可保育園を取得すると同時に、認定子ども園の認証を受ける形になります。","voiceIndex":166,"id":"exchange-066"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"本年の調査項目の要望ですが、１つ目が発達障害者の支援に関係すること、２つ目に小規模多機能型の介護事業所、この２点を要望し、また、今、品川区の方策の中で、区民との協働という点から、ＮＰＯ法人等が運営されているケース等の先進的な事例という点で、テーマに上げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"具体的に申し上げてよろしいですか。今のところ以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-068"},{"speaker":"浅野委員","kind":"意見","question":"最近、自殺が増えているというか、そういう報道もある中で、１つの要因としましては、複雑な社会の中で精神障害を患うというようなケースがあると思うんですけれども、そういう精神的な疾患に関して取り組んでいるような施設とか、そういうものがあれば、ぜひとも過程、やり方とか、そういうのを含めて見学できれば、視察できればと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3208#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":59784,"voices":183}}]);
